(window.GIM_TS=window.GIM_TS||{})["Eruvin.5"]={"from":120,"a":[["\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003אביי בר אבין ורב חיננא בר אבין, ויתיב\u0004 \u0005[וישב]\u0006 \u0003אביי גבייהו\u0004 \u0005[עימם],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[וישבו ואמרו]:\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' מאיר\u0004 שהוא סתם משנתנו \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 \u0003דירת גוים שמה דירה,\u0004 כלומר, הגוי הדר בחצר נחשב כאחד הדיירים בחצר, ומאחר ואינו יכול להשתתף עם הישראל הרי שבהוצאת הישראל לחצר הריהו מוציא מרשות לרשות. \u0003ו\u0004משום כך \u0003לא שנא חד ולא שנא תרי\u0004 \u0005[אינו שונה אחד ואינו שונה שניים]\u0006 ולכן הגוי אוסר גם על אחד.","\u0003אלא ר' אליעזר בן יעקב מאי קסבר\u0004 \u0005[מה הוא סבור]\u0006 מה דעתו היסודית בנושא זה? \u0003אי קסבר\u0004 \u0005[אם\u0006 תאמר ש\u0005הוא סבור]\u0006 \u0003דירת גוי שמה דירה — אפילו חד נמי ניתסר\u0004 \u0005[אחד גם כן ייאסר]!\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא שמה דירה — אפילו תרי נמי לא ניתסר\u0004 \u0005[שניים גם כן לא ייאסרו]!\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי:\u0004 עיקרה של הנחתכם בטעות יסודה: \u0003ו\u0004כי \u0003סבר ר' מאיר דירת גוי שמה דירה? והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003חצירו של גוי — הרי הוא כדיר של בהמה,\u0004 שאין דירת הגוי כשלעצמה אוסרת על ישראל, כשם שאין דירת בעלי חיים אוסרת.","\u0003אלא\u0004 יש להניח הסבר זה ולהבין את הדברים בצורה שונה: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003דירת גוי לא שמה\u0004 \u0005[אינה נקראת]\u0006 \u0003דירה, והכא\u0004 \u0005[וכאן]\u0006 \u0003בגזירה שמא ילמד ממעשיו קא מיפלגי\u0004 \u0005[הם נחלקו],\u0006 האם יש מקום לאסור כאן משום חשש זה.","וכך יש להבין, \u0003ר' אליעזר בן יעקב סבר: כיון דגוי חשוד אשפיכות דמים\u0004 שמא יהרגנו ואין מצוי שיהא אדם אחד מישראל דר עם הגוי בחצר, \u0003תרי דשכיחי דדיירי\u0004 \u0005[שניים שמצוי ש\u0006הם \u0005גרים\u0006 עם הגוי\u0005],\u0006 שכיון שהם שנים שוב אינם חוששים ומצוי שיגורו עם הגוי, משום כך \u0003גזרו בהו\u0004 \u0005[בהם]\u0006 חכמים שיאסור הגוי עליהם, כדי להכביד עליהם את הדירה בחצר אחת, ולהביא שישנו דירתם ויתרחקו מהגוים, ולא ילמדו מדרכיהם. \u0003חד לא שכיח\u0004 \u0005[\u0006אדם \u0005אחד לא מצוי]\u0006 שיגור עם הגוי — \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים],\u0006 שאין חכמים גוזרים בדבר שאינו מצוי.","\u0003ו\u0004אילו \u0003ר' מאיר סבר: זימנין דמקרי ודייר\u0004 \u0005[פעמים שמזדמן ו\u0006הוא \u0005גר]\u0006 עם הגוי, וראוי לגזור אף במקרה זה. \u0003ו\u0004לכך \u0003אמרו רבנן\u0004 \u0005[חכמים]:\u0006 \u0003אין עירוב מועיל במקום גוי, ו\u0004אף \u0003אין ביטול רשות\u0004 לשאר הדיירים \u0003מועיל במקום גוי,\u0004 ואין אפשרות לטלטל בחצר שאחד מדייריה גוי \u0003עד שישכיר. וגוי לא מוגר\u0004 \u0005[משכיר],\u0006 ומשום כך יכבידו תנאי הדיור עד שיצטרכו הישראלים לעקור.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לא ישכיר הגוי דירתו לצורך עירוב? \u0003אילימא משום דסבר: דלמא אתי לאחזוקי\u0004 \u0005[אם תאמר משום שסובר\u0006 אותו גוי: \u0005שמא יבואו\u0006 אחר כך \u0005להחזיק]\u0006 \u0003ברשותו\u0004 על סמך שכירות זו, \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שכירות בריאה בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא שכירות זו מושלמת ובעלת תוקף לכל דיני שכירות.","\u0003אלא למאן דאמר\u0004 \u0005[למי שאומר]:\u0006 אפילו \u0003שכירות רעועה\u0004 שאינה שלימה \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 שדי לנו רק בדבר הנראה כשכירות, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלא יבין הגוי שאין זו שכירות של ממש, ולא יחשוש מלהשכיר דירתו. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שבבעיה זו נחלקו אמוראים, \u0003רב חסדא אמר: שכירות בריאה. ורב ששת אמר: שכירות רעועה.\u0004","וכיון שהוזכר הענין מבררים: \u0003מאי\u0004 \u0005[מהי]\u0006 שכירות \u0003רעועה, מאי\u0004 \u0005[ומהי]\u0006 שכירות \u0003בריאה? אילימא\u0004 \u0005[אם תאמר]:\u0006 שכירות \u0003בריאה\u0004 — שנותן לו בשכירות זו \u0003פרוטה, רעועה — פחות משוה פרוטה.\u0004 ואולם \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 ששכירות \u0003מגוי בפחות משוה פרוטה לא\u0004 תופסת? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלח ר' יצחק בר' יעקב בר גיורי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: הוו יודעין ששוכרין מן הגוי אפילו בפחות משוה פרוטה.\u0004","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: בן נח\u0004 שגזל, הרי לפי דיני שבע מצוות בני נח הוא \u0003נהרג\u0004 כעונש על הגזילה אפילו \u0003על פחות משוה פרוטה.\u0004 שכל דבר השוה משהו, יש בו דין גזילה, \u0003ו\u0004בדיני בן נח \u0003לא ניתן\u0004 הגזל אף \u0003להשבון\u0004 (להשבה), שלא נאמרה תקנה זו לגזלן להשיב גזלתו אלא בישראל בלבד. ולעניננו למדנו שמה שאומרים שפחות משוה פרוטה אינו נחשב לממון, הוא לגבי ישראל בלבד, אבל אצל בני נח, אפילו פחות משוה פרוטה ממון הוא ואפשר לשכור בו.","\u0003אלא\u0004 כך יש להסביר: שכירות \u0003בריאה\u0004 — משמעו \u0003במוהרקי ואבורגני\u0004 \u0005[בכתיבה ובשטרות],\u0006 \u0003רעועה — בלא מוהרקי ואבורגני,\u0004 ואינה אלא הסכמה שאינה מחייבת בבית דין. ואם כן לענין חששו של הגוי מלהשכיר, \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שכירות בריאה בעינן\u0004 \u0005[צריכים אנו]\u0006 יש להבין מדוע יסרב הגוי להשכיר.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שכירות רעועה בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 על כך, מדוע לא ירצה הגוי להשכיר? ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003חשיש\u0004 \u0005[חושש]\u0006 ה\u0003גוי\u0004 מה \u0003כשפים,\u0004 שמא יעשו לו כשפים על ידי כך, \u0003ו\u0004לכן \u0003לא מוגר\u0004 \u0005[אינו משכיר\u0006 דירתו\u0005].\u0006","כיון שהוזכרה הלכה זו באים לדון בה \u0003גופא\u0004 \u0005[עצמה]:\u0006 \u0003נאמר בתוספתא שחצירו של גוי הרי הוא כדיר של בהמה, ומותר להכנס ולהוציא מן חצר לבתים ומן בתים לחצר,\u0004 שאין דיני עירוב חלים כלל במקום דירת הגוים.","\u0003ואם יש שם ישראל אחד\u0004 באותה חצר — \u0003אוסר,\u0004 ואין תקנה לטלטל אלא על ידי שישכיר לו הגוי רשותו למשך יום השבת, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' אליעזר בן יעקב אומר: לעולם אינו אוסר,\u0004 ישראלי אחד אינו נחשב, ומותר לטלטל בחצר. \u0003עד שיהו שני ישראלים\u0004 שמצד עצמם \u0003אוסרים זה על זה\u0004 וחלה עליהם חובת העירוב, ולא יוכלו לעשות זאת בשל הגוי."],["\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חצירו של גוי הרי הוא כדיר של בהמה\u0004 משמע שאין דירתו נחשבת דירה כלל. \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]:\u0006 \u0003הדר עם הגוי בחצר הרי זה אוסר עליו\u0004 משמע שדירת הגוי נחשבת כדירה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דאיתיה\u0004 \u0005[כשישנו]\u0006 הגוי במקום, אוסר. \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דליתיה\u0004 \u0005[כשאינו\u0006 נמצא במקום\u0005],\u0006 אינו אוסר.","ושואלים: \u0003ומאי קסבר\u0004 \u0005[ומה\u0006 בעצם \u0005הוא סבור],\u0006 \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 ש\u0003דירה בלא בעלים שמה דירה,\u0004 ואוסרת היא אף אם אין בעליה כעת בתוכה, אם כן לפי עקרון זה \u0003אפילו\u0004 היה שם \u0003גוי, נמי ניתסר\u0004 \u0005[גם כן יאסור].\u0006 \u0003ואי קסבר\u0004 \u0005[ואם הוא סבור]\u0006 ש\u0003דירה בלא בעלים לא שמה דירה, אפילו ישראל\u0004 שני שיצא מביתו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניתסר\u0004 \u0005[יאסור]!\u0006","ומשיבים: \u0003לעולם\u0004 תאמר \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003דירה בלא בעלים — לא שמה דירה. ו\u0004אולם \u0003ישראל, דכי איתיה אסר\u0004 \u0005[שכאשר מצוי\u0006 הוא בדירה, \u0005אוסר]\u0006 על הדר עמו ומצריכו עירוב. לכן גם \u0003כי ליתיה\u0004 \u0005[כאשר איננו]\u0006 — \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 שתאסור דירתו כאילו היה מצוי במקום.","ואולם \u0003גוי,\u0004 גם \u0003דכי איתיה\u0004 \u0005[שכאשר מצוי\u0006 הוא בדירתו\u0005]\u0006 אינו אוסר מעיקר הדין אלא משום \u0003גזירה שמא ילמד ממעשיו,\u0004 על כן לא הוסיפו בו גזירה יתרה. ולכן \u0003כי איתיה\u0004 \u0005[כאשר נמצא] —\u0006 \u0003אסר\u0004 \u0005[אוסר],\u0006 \u0003כי ליתיה\u0004 \u0005[כאשר איננו] —\u0006 \u0003לא אסר\u0004 \u0005[אוסר].\u0006","ושואלים: \u0003וכי ליתיה, לא אסר\u0004 \u0005[וכאשר איננו, אינו אוסר]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המניח את ביתו והלך לו לשבות בעיר אחרת, אחד גוי ואחד ישראל — אוסר\u0004 על השכנים שבחצר אם לא עירב, אלו \u0003דברי ר' מאיר.\u0004 הרי שר' מאיר סבור שגוי, גם אם אינו מצוי בביתו, בכל זאת אוסר!","ומשיבים: \u0003התם דאתי ביומיה\u0004 \u0005[שם\u0006 מדובר \u0005שיבוא,\u0006 יחזור \u0005ביומו,\u0006 בשבת\u0005].\u0006 ומתוך שכשיחזור יאסור, לכן גזרו אף לפני שחזר. אבל כשיצא מביתו ואיננו עתיד לחזור עד לאחר השבת — שוב אינו אוסר כשאינו בו.","\u0003אמר רב יהודה אמר שמואל: הלכה כר' אליעזר בן יעקב. ורב הונא אמר:\u0004 אין זו הלכה פסוקה שמלמדים אותה לרבים, אלא \u0003מנהג כר' אליעזר בן יעקב\u0004 וכך פוסקים למעשה לשואל. \u0003ור' יוחנן אמר: נהגו העם כר' אליעזר בן יעקב,\u0004 שאין פוסקים כן אף לשואל הלכה, אבל המקל בכך, אין מוחים בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף\u0004 רבו: \u0003קיימא לן\u0004 \u0005[מוחזק בידינו]\u0006 ש\u0003משנת ר' אליעזר בן יעקב קב ונקי,\u0004 כלומר מעטה אבל ברורה ושלמה בתכלית, שהלכה כמותו בכל מקום, ויתר על כן לעניננו \u0003אמר רב יהודה אמר שמואל: הלכה כר' אליעזר בן יעקב,\u0004 ואם כן אין כל ספק בכך,","\u0003מהו\u0004 הדין, האם מותר לתלמיד \u0003לאורויי\u0004 \u0005[להורות]\u0006 הלכה \u0003במקום רבו,\u0004 ושמא דבר כזה הידוע ופשוט לכל אינו בגדר הוראה שאסורה לתלמיד במקום רבו?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו ביעתא בכותחא בעו מיניה\u0004 \u0005[\u0006בישול \u0005ביצה בכותח\u0006 המכיל חלב אם מותר \u0005שאלו ממנו]\u0006 \u0003מרב חסדא כל שני\u0004 \u0005[שנות\u0006 חייו\u0005]\u0006 של \u0003רב הונא, ולא אורי\u0004 \u0005[הורה]\u0006 שהיה תלמידו, ואסור לתלמיד להורות במקום רבו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב בר אבא לאביי: כגון מגלת תענית דכתיבא ומנחא\u0004 \u0005[ש\u0006היא \u0005כתובה ומונחת]\u0006 ונמנים בה במפורש הימים שיש להתענות בהם ושאסור להתענות בהם. \u0003מהו לאורויי באתריה דרביה\u0004 \u0005[להורות\u0006 דבר זה \u0005במקום רבו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יוסף: אפילו ביעתא בכותחא בעו מיניה\u0004 \u0005[ביצה בכותח שאלו ממנו]\u0006 \u0003מרב חסדא כל שני\u0004 \u0005[שנות\u0006 חייו\u0005]\u0006 של \u0003רב הונא ולא אורי\u0004 \u0005[הורה].\u0006","מסופר כי אף על פי כן \u0003רב חסדא אורי בכפרי בשני\u0004 \u0005[הורה ב\u0006עיירה \u0005כפרי בשנותיו]\u0006 של \u0003רב הונא,\u0004 כי לא היה הדבר במקום רבו ממש."],["\u0003רב המנונא אורי\u0004 \u0005[הורה]\u0006 \u0003ב\u0004עיר \u0003חרתא דארגז בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003רב חסדא,\u0004 אף שהיה רבו.","מסופר: \u0003רבינא סר סכינא\u0004 \u0005[בדק סכין]\u0006 של שוחט \u0003בבבל,\u0004 בימיו של רב אשי רבו, שאף הוא היה גר בבבל, לראות אם הסכין ראויה לשחוט בה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי\u0004 רבו: \u0003מאי טעמא עבד מר הכי\u0004 \u0005[מה טעם עושה אדוני כן]\u0006 והלא אסור לתלמיד להורות בזמן שרבו קיים?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב המנונא אורי\u0004 \u0005[הורה]\u0006 \u0003ב\u0004עיר \u0003חרתא דארגז בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003רב חסדא\u0004 מכיון שלא היו באותה העיר אף על פי ששניהם היו בבבל, ואף אני איני דר בעירך ומותר לי להורות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרבינא: \u0003\"לאו אורי\" אתמר\u0004 \u0005[\"לא הורה\" נאמר]\u0006 וכך היא הגירסה הנכונה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003איתמר \"אורי\", ואתמר \"לא אורי\"\u0004 \u0005[נאמר \"הורה\", ונאמר \"לא הורה\"]\u0006 ושתי הגירסות נכונות, שכן \u0003בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003רב הונא רביה\u0004 \u0005[רבו\u0006 המובהק\u0005]\u0006 \u0003הוא\u0004 ש\u0003לא אורי\u0004 \u0005[הורה]\u0006 רב המנונא כלל, \u0003ואורי בשני\u0004 \u0005[והורה בשנות]\u0006 \u0003רב חסדא,\u0004 ש\u0003תלמיד חבר דיליה הוה\u0004 \u0005[שלו היה].\u0006 \u0003ואנא נמי\u0004 \u0005[ואני גם כן]\u0006 \u0003תלמיד חבר דמר אנא\u0004 \u0005[של אדוני אני],\u0006 ומשום כך מותר לי לבדוק סכין כשהוא שלא במקום מגוריך.","\u0003אמר רבא: צורבא מרבנן חזי לנפשיה\u0004 \u0005[תלמיד חכם רואה\u0006 סכין \u0005לעצמו]\u0006 אם רצונו לשחוט בה, ואינו חייב להראותה לחכם העיר. מסופר: \u0003רבינא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003מחוזא\u0004 שהיה גר בה, \u0003אייתי אושפזיכניה סכינא וקא מחוי ליה\u0004 \u0005[הביא המארח שלו סכין\u0006 לשחוט \u0005והראה לו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אמטייה\u0004 \u0005[לך הביאנה]\u0006 \u0003לרבא\u0004 שהיה חכם העיר, שיבדקנה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סבר מר הא דאמר\u0004 \u0005[\u0006וכי \u0005אין אדוני סבור\u0006 את \u0005זה שאמר]\u0006 \u0003רבא צורבא מרבנן חזי לנפשיה\u0004 \u0005[תלמיד חכם רואה לעצמו],\u0006 והרי בשבילך אני שוחט. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא מיזבן זבינא\u0004 \u0005[אני\u0006 הרי \u0005קונה]\u0006 ממך ומשלם את מחיר הבשר, ואינך שוחט ממש עבורי, ובענין זה לא התיר רבא.","(סימן לשמות החכמים הנזכרים הלאה \u0003זיל\"א להני\"א\u0004 ר' אלעזר מהגרוניא \u0003מחלי\"ף\u0004 רב אבא בר תחליפא, \u0003איק\"א\u0004 רב אחא בר איקא, \u0003ויעק\"ב\u0004 רב אחא בר יעקב).","מסופר, \u0003ר' אלעזר מהגרוניא ורב אבא בר תחליפא איקלעו לבי\u0004 \u0005[הזדמנו לביתו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא, באתריה\u0004 \u0005[במקומו]\u0006 של \u0003רב אחא בר יעקב. בעי\u0004 \u0005[רצה]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא למיעבד להו עיגלא תילתא\u0004 \u0005[לעשות להם עגל משולש]\u0006 בשליש שנותיו שהוא משובח, \u0003אייתי סכינא וקא מחוי להו\u0004 \u0005[הביא סכין\u0006 שחיטה \u0005והראה להם].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אחא בר תחליפא: לא ליחוש ליה לסבא\u0004 \u0005[האם לא נחשוש לזקן]\u0006 לרב אחא בר יעקב, להראות לו את הסכין כראוי? \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אלעזר מהגרוניא: הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבא, צורבא מרבנן חזי לנפשיה\u0004 \u0005[תלמיד חכם רואה סכין לעצמו].\u0006 \u0003חזי\u0004 \u0005[ראה]\u0006 את הסכין, ולאחר זמן \u0003איעניש\u0004 \u0005[נענש]\u0006 בידי שמים \u0003רב אלעזר מהגרוניא\u0004 על שזלזל בכבוד הרב.","ותוהים: והלא יפה עשה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: צורבא מרבנן חזי לנפשיה\u0004 \u0005[תלמיד חכם רואה לעצמו]!\u0006 ומשיבים: \u0003שאני התם דאתחילו\u0004 \u0005[שונה שם שהתחילו]\u0006 לדון \u0003ב\u0004ענין \u0003כבודו.\u0004 שאילו לא הוזכר שמו של רב אחא בר יעקב כלל, מותר היה להם לבדוק סכין לעצמם. אבל כיון שכבר דובר בו, צריכים היו לשאול אותו, ולא לזלזל כך בכבודו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב אחא בר יעקב\u0004 ש\u0003מופלג\u0004 היה בזקנה ובחכמה, וחייבים להדר בכבודו מעל לחובה הרגילה.","\u0003אמר רבא:\u0004 אף שאמרנו שאסור לתלמיד להורות במקום רבו, \u0003לאפרושי מאיסורא\u0004 \u0005[להפריש\u0006 אדם \u0005מאיסור\u0006 שהוא עושה\u0005]\u0006 \u0003— אפילו בפניו\u0004 של רבו \u0003שפיר דמי\u0004 \u0005[מותר].\u0006 מסופר: \u0003רבינא הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב אשי, חזייה לההוא גברא דקא אסר ליה לחמריה בצינתא בשבתא\u0004 \u0005[ראה אדם אחד שקושר חמורו בדקל בשבת]\u0006 ועבר על גזירת חכמים שלא להשתמש באילנות בשבת. \u0003רמא ביה קלא, ולא אשגח ביה\u0004 \u0005[הרים עליו קולו\u0006 וגער בו, \u0005ולא השגיח בו\u0006 האיש\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ליהוי האי גברא בשמתא\u0004 \u0005[שיהא אדם זה בחרם]\u0006 שעבר על דברי חכמים ולא שם לב לגערתו של תלמיד חכם.","לאחר מעשה \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא לרב אשי: \u0003כי האי גוונא, מי מתחזא כאפקרותא\u0004 \u0005[כעין זה\u0006 מה שעשיתי עתה בפניך, \u0005האם\u0006 זה \u0005נראה כזלזול\u0006 בכבוד\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: על כגון זה נאמר: \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה'\"\u0004 (משלי כא, ל), וכבר דרשוה חכמים: \u0003כל מקום שיש בו חילול השם — אין חולקין כבוד לרב,\u0004 שאז אין משגיחים בחכמתו ותבונתו של הרב.","\u0003באמר רבא:\u0004 בדין המורה הלכה במקום רבו ואין בו משום הפרשה מאיסור יש לחלק: \u0003בפניו\u0004 ממש — \u0003אסור\u0004 להורות, ואם הורה — \u0003חייב מיתה\u0004 בידי שמים. ולהורות במקומו \u0003שלא בפניו ממש — אסור, ואין חייב מיתה.\u0004","ושואלים: וכי \u0003שלא בפניו לא\u0004 חייב מיתה? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר: לא מתו בני אהרן עד שהורו הלכה בפני משה רבן. מאי דרוש\u0004 \u0005[מה דרשו]\u0006 לחזק דעתם שהגיעו למסקנה שהם צריכים להכניס את האש פנימה, שנאמר בתורה \u0003\"ונתנו בני אהרן אש על המזבח\u0004 וערכו עצים על האש\u0003\"\u0004 (ויקרא א, ז), \u0003אמרו: אף על פי שהאש יורדת מן השמים,\u0004 בכל זאת מצוה מן התורה \u0003להביא\u0004 אש \u0003מן ההדיוט.\u0004 ואף שדרשו זאת מן המקראות נענשו על שהורו בפני רבן.","ומסופר, \u0003תלמיד אחד היה לו לר' אליעזר, שהורה הלכה בפניו. אמר ר' אליעזר לאימא שלום אשתו: תמיה אני אם יוציא זה שנתו\u0004 (אם יחיה עד סוף השנה). וכך היה, \u0003ולא הוציא שנתו.\u0004","\u0003אמרה לו: נביא אתה? אמר לה: לא נביא אנכי ולא בן נביא אנכי, אלא כך מקובלני: כל המורה הלכה בפני רבו חייב מיתה. ואמר רבה בר\u0004","\u0003בר חנה אמר ר' יוחנן: אותו תלמיד יהודה בן גוריא שמו, והיה רחוק ממנו שלש פרסאות.\u0004 משמע איפוא מכל זה שחייב מיתה, גם אם הורה שלא ממש בפני רבו?!","ומשיבים: שמעשה זה \u0003בפניו\u0004 של רבו ממש \u0003הוה\u0004 \u0005[היה]\u0006 ולכן נענש. ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רחוק ממנו שלש פרסאות קאמר\u0004 \u0005[אמר]\u0006 ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולדעתך]\u0006 שהדבר נועד רק לסיפור דברים בלבד \u0003שמו ושם אביו למה? אלא שלא תאמר משל היה\u0004 ולכן מסר גם פרטים על מקומו, אבל אותה הוראה שהורה — בפני רבו ממש היתה.","ועוד באותו נושא \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל המורה הלכה בפני רבו, ראוי להכישו נחש, שנאמר \"ויען אליהוא בן ברכאל הבוזי ויאמר צעיר אני לימים\u0004 ואתם ישישים \u0003על כן זחלתי\u0004 ואירא מחוות דעי אתכם\u0003\"\u0004 (איוב לב, ו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"עם חמת זחלי עפר\"\u0004 (דברים לב, כד) שמשמעו נחשים. וכך מבינים את דברי אליהוא: חייב הוא להתנצל על שמדבר בפני רבו, אף שהמורה בפני רבו נענש בנשיכת נחש.","\u0003זעירי אמר\u0004 בשם \u0003ר' חנינא:\u0004 המורה במקום רבו \u0003נקרא חוטא, שנאמר \"בלבי צפנתי אמרתך למען לא אחטא לך\"\u0004 (תהילים קיט, יא), ואימתי יש חטא בהוצאת דבריו — כשהוא מורה במקום רבו.","\u0003רב המנונא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה בין שני מקראות\u0005]:\u0006 \u0003נאמר \"בלבי צפנתי אמרתך\"\u0004 משמע שלא רצה דוד לגלות דברי תורה, ובפסוק אחר נאמר \u0003\"בשרתי צדק בקהל רב\"\u0004 (תהילים מ, י)! ויש להשיב: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]!\u0006 \u0003כאן\u0004 ששתק — \u0003בזמן שעירא היאירי\u0004 רבו של דוד \u0003קיים, כאן\u0004 כשפרסם דבריו — היה זה \u0003בזמן שאין עירא היאירי קיים.\u0004 ואגב הזכרת עירא היאירי מביאים דבר אחר שנאמר בענין זה.","\u0003אמר ר' אבא בר זבדא: כל הנותן מתנותיו\u0004 (מתנות הניתנות לכהנים) \u0003לכהן אחד\u0004 בלבד, אינו עושה כראוי ו\u0003מביא רעב לעולם\u0004 כעונש. וראיה לדבר, \u0003שנאמר: \"\u0004וגם \u0003עירא היארי היה כהן לדוד\"\u0004 (שמואל ב כ, כה). ויש לשאול: וכי \u0003לדוד\u0004 בלבד \u0003הוא דהוה\u0004 \u0005[שהיה]\u0006 \u0003כהן, לכולי עלמא\u0004 \u0005[לכל העולם]\u0006 \u0003לא?! אלא\u0004 הכונה \u0003שהיה משגר לו\u0004 לבדו את \u0003מתנותיו,\u0004 והוא היה כהן המיוחד שהיה נהנה ממתנותיו של דוד. \u0003וכתיב בתריה\u0004 \u0005[וכתוב אחר כך]:\u0006 \u0003\"ויהי רעב בימי דוד\u0004 שלש שנים שנה אחר שנה\u0003\"\u0004 (שמואל ב כא, א).","\u0003ר' אליעזר אומר:\u0004 כל המורה בפני רבו, \u0003מורידין אותו מגדולתו, שנאמר \"ויאמר אלעזר הכהן אל אנשי הצבא\u0004 הבאים למלחמה זאת חוקת התורה אשר צוה ה' את משה\u0003\"\u0004 (במדבר לא, כא), \u0003אף על גב דאמר להו\u0004 \u0005[אף על פי שאמר להם\u0006 אלעזר לאנשי הצבא\u0005]:\u0006 \u0003לאחי אבא צוה\u0004 ה' חוק זה, \u0003ואותי\u0004 עצמי \u0003לא צוה — אפילו הכי, איענש\u0004 \u0005[כך, נענש]\u0006 על שאמר את הדברים לפני משה רבו.","ומה עונשו, שתחילה אמר ה' למשה כי יהושע \u0003\"ולפני אלעזר הכהן יעמד\u0004 ושאל לו במשפט האורים לפני ה' על פיו יצאו ועל פיו יבואו הוא וכל בני ישראל אתו וכל העדה\u0003\"\u0004 (במדבר כז כא). ניתנה לו איפוא גדולה יתירה \u0003ולא אשכחן\u0004 \u0005[מצאנו]\u0006 בכתוב \u0003דאיצטריך ליה\u0004 \u0005[שהצטרך לו]\u0006 \u0003יהושע\u0004 לאלעזר הכהן שיצטרך להשתמש במשפט האורים, ונמצא שלא זכה אלעזר לגדולה זו.","באותו ענין \u0003אמר ר' לוי\u0004: \u0003כל דמותיב מלה קמיה רביה\u0004 \u0005[המשיב דבר בפני רבו] —\u0006 \u0003אזיל\u0004 \u0005[הולך]\u0006 \u0003לשאול בלא ולד, שנאמר \"ויען יהושע בן נון משרת משה מבחריו ויאמר אדני משה כלאם\"\u0004 (במדבר יא כח) וכיון שאמר דברים אלה לרבו שלא ברשות, נענש שלא היו לו בנים."],["\u0003\"נון בנו יהושע בנו\"\u0004 (דברי הימים א, ז, כז) ואין לרשימה זו המשך, ומזה משמע שלא היו בנים ליהושע.","\u0003ופליגא\u0004 \u0005[וחלוקה\u0006 מסורת \u0005זו]\u0006 על דבריו של \u0003ר' אבא בר פפא,\u0004 ש\u0003אמר ר' אבא בר פפא: לא נענש יהושע\u0004 שימות בלא בנים \u0003אלא בשביל שביטל את ישראל לילה אחד מפריה ורביה,\u0004 ומדה כנגד מדה נענש שלא יהיו לו בנים,","\u0003שנאמר \"ויהי בהיות יהושע ביריחו וישא עיניו וירא\u0004 והנה איש עומד לנגדו \u0003וגו'\", וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר לא כי אני שר צבא ה' עתה באתי וגו'\"\u0004 (יהושע ה, יג—יד), משמע שבא המלאך לתבוע דבר מה מיהושע ולהוכיחו.","\u0003אמר לו\u0004 המלאך: \u0003אמש\u0004 בשל עיסוקכם בפעולות המלחמה \u0003ביטלתם תמיד של בין הערבים, ועכשיו ביטלתם\u0004 בלילה \u0003תלמוד תורה.\u0004 שאל אותו יהושע \u0003על איזה\u0004 חטא \u0003מהם באת\u0004 במיוחד להוכיחני? \u0003אמר לו: \"עתה באתי\"\u0004 כלומר, ממה שלא באתי אמש אלא עתה מובן שעוון זה של ביטול תורה חמור יותר.","\u0003מיד\u0004 עשה יהושע תיקון לדבר והחליט שיש להוסיף בלימוד התורה, כאמור: \u0003\"וילך יהושע בלילה ההוא בתוך העמק\"\u0004 (יהושע ח, יג), \u0003ואמר ר' יוחנן: מלמד שהלך\u0004 כל הלילה \u0003בעומקה של הלכה,\u0004 ועל ידי כך כיפר על חטא ביטול תורה.","\u0003ו\u0004אולם \u0003גמירי\u0004 \u0005[למודים מן המסורת]\u0006 ש\u0003כל זמן שארון ושכינה שרויין שלא במקומן — אסורין\u0004 כל העם \u0003בתשמיש המטה,\u0004 ומשום שהיו עסוקים במלחמה לא החזירו את הארון למקומו במשכן. ויהושע שלא דאג לכך, גרם לעם להיבטל מפריה ורביה, ועל דבר זה נענש.","ומוסיפים עוד הנלמד מענין זה, \u0003אמר ר' שמואל בר איניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: גדול תלמוד תורה יותר מהקרבת תמידין,\u0004 שהרי \u0003אמר ליה\u0004 \u0005[לו]\u0006 המלאך: \u0003\"עתה באתי\",\u0004 כלומר על העוון האחרון, משמע שביטול תורה הוא חמור יותר מביטול התמידים.","\u0003בענין ביטול פריה ורביה מובא עוד שאמר רב ברונא אמר רב: כל הישן בקילעא\u0004 \u0005[בחדר]\u0006 \u0003שאיש ואשתו שרויין בה,\u0004 ועל ידי כך מבטלם מלהתיחד — \u0003עליו הכתוב אומר \"נשי עמי תגרשון מבית תענגיה\"\u0004 (מיכה ב, ט), ועונשו נאמר להלן באותו פרק.","\u0003ואמר רב יוסף:\u0004 דבר זה נאמר לא רק כאשר האשה טהורה ומותרת לבעלה, אלא \u0003אפילו באשתו נדה\u0004 נוח להם שיהו שניהם ביחד.","\u0003רבא אמר: אם אשתו נדה היא — תבא עליו ברכה,\u0004 שהריהו שומר את בני הזוג מאפשרות של חטא. ודוחים: \u0003ולא היא,\u0004 ואין נימוק זה תופס, \u0003דעד האידנא, מאן נטריה\u0004 \u0005[שעד עכשיו, מי שמר אותו]?\u0006 ואין אנו חוששים לענין זה. וכיון שיש בכך צער לבני הזוג, יש להיזהר שלא לעשות כן.","ומעתה חוזרים אנו לענין ההלכה בנושא שכירת רשות. מסופר, \u0003ההוא מבואה דהוה דייר בה\u0004 \u0005[מבוי אחד שהיה גר בו]\u0006 הגוי \u0003לחמן בר ריסתק. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אוגר לן\u0004 \u0005[השכר לנו]\u0006 \u0003רשותך,\u0004 כדי שלא תאסור רשותך את הטלטול בחצר, \u0003לא אוגר להו [השכיר להם]\u0004 ולא יכלו לטלטל במבוי בשבת.","\u0003אתו\u0004 \u0005[באו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לאביי\u0004 ושאלוהו מה לעשות. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו בטילו רשותייכו לגבי חד\u0004 \u0005[לכו בטלו\u0006 כולכם \u0005רשות\u0006 שימושכם במבוי \u0005אצל\u0006 אדם \u0005אחד]\u0006 שיהא מותר לו לטלטל בו, ועל ידי כך \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003יחיד במקום גוי, ו\u0004כבר נפסקה הלכה ש\u0003יחיד במקום גוי לא אסר,\u0004 ואז יוכל לפחות היחיד להשתמש במבוי.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מידי הוא טעמא\u0004 \u0005[והלא הטעם הוא]\u0006 \u0003אלא\u0004 ביחיד במקום גוי, ש\u0003לא שכיח\u0004 \u0005(\u0006מצוי\u0005)\u0006 \u0003דדירי\u0004 \u0005[שדרים\u0006 עמו\u0005],\u0006 \u0003והכא הא קדיירי\u0004 \u0005[וכאן הרי דרים הם],\u0006 שהרי בפועל דרים רבים במבוי זה ומצוי שיגורו עם הגוי, ובאופן כזה לא התירו!","\u0003אמר להו\u0004 \u0005[להם]\u0006 אביי: \u0003כל בטולי רשותייהו גבי חד, מילתא דלא שכיחא היא\u0004 \u0005[ביטול רשותם\u0006 של רבים \u0005אצל\u0006 אדם \u0005אחד, דבר שאינו שכיח הוא],\u0006 וכלל הוא: \u0003מילתא דלא שכיחא\u0004 \u0005[דבר שאינו שכיח],\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים],\u0006 ובשעת דחק זו אפשר להשתמש בהיתר זה.","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמרה לשמעתא קמיה\u0004 \u0005[להלכה\u0006 זו \u0005לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 רבא:"],["\u0003אם כן ביטלת תורת עירוב מאותו מבוי!\u0004 שלהלכה במבוי זה גר רק אדם אחד, ואין צורך לערב. וכשיטלטלו בו בלא עירוב, יש לחשוש שמא יטעו הרואים ויאמרו שטלטול מותר במבוי אפילו בלא עירוב.","ענה לו: \u0003דמערבי\u0004 \u0005[שמערבים]\u0006 בכל זאת, ואף שאין העירוב מועיל מצד עצמו, מכל מקום משאירים שם זכרון לעירוב. אמר לו: אם כן, חסרון אחר בדבר: הרי \u0003יאמרו\u0004 הרואים את הדבר כי \u0003עירוב מועיל במקום גוי?!\u0004 ושלא כהלכה! ענה לו: \u0003דמכרזינן\u0004 \u0005[שמכריזים אנו\u0006 על כך\u0005]\u0006 ומודיעים שאינם מטלטלים בו לפי שאין עירוב זה מועיל ולא נעשה אלא לזכרון.","ודחה רבא ואמר שאף זה אינו מועיל: וכי עושים \u0003אכרזתא לדרדקי\u0004 \u0005[הכרזה לתינוקות]?!\u0006 שאף אם מועילה ההכרזה למבוגרים המצויים שם, הרי לתינוקות הגרים במבוי זה, שלא שמעו את ההכרזה ולא הבינו אותה, כיצד יידעו הם מאוחר יותר? והלא ראו מנהג אבותיהם שמערבים במבוי זה, ויחשבו שעירוב זה מועיל במקום גוי! לכן אין לסמוך על תקנה זו של אביי.","\u0003אלא אמר רבא:\u0004 כך יש לעשות, \u0003ליזיל חד מינייהו, ליקרב ליה, ולשאול מיניה דוכתא, ולינח ביה מידי\u0004 \u0005[ילך אחד מהם, יתקרב\u0006 בדעתו ויתחבר \u0005לו\u0006 אל הגוי, \u0005וישאל ממנו\u0006 רשות להשתמש ב\u0005מקום, ויניח בו דבר מה]\u0006 \u0003דהוה ליה\u0004 \u0005[שהריהו נעשה לו\u0006 על ידי כך\u0005]\u0006 \u0003כשכירו ולקיטו,\u0004 כפועל המלקט עבור הגוי, \u0003ואמר רב יהודה אמר שמואל:\u0004 לא רק הגוי עצמו יכול להשכיר את הדירה לצורך עירוב אלא \u0003אפילו שכירו ואפילו לקיטו,\u0004 אם השכיר לישראל — \u0003נותן עירובו\u0004 במקום זה \u0003ודיו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: היו שמה חמשה שכירו וחמשה לקיטו מהו?\u0004 שאם היו כולם יהודים האם יש במעמדם גם כדי להחמיר, שיהיו חייבים כולם לערב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם אמרו שכירו ולקיטו להקל, יאמרו שכירו ולקיטו להחמיר?\u0004 לא נאמרה הלכה זו אלא להקל בדיני השכרה ולא להוסיף בה חומרות.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של אותו ענין, \u0003אמר רב יהודה אמר שמואל: אפילו שכירו ואפילו לקיטו, נותן עירובו ודיו. אמר רב נחמן: כמה מעליא הא שמעתא\u0004 \u0005[מעולה הלכה זו],\u0006 שאף רב נחמן הסכים לה וראה אותה כנכונה ומבוססת.","ואולם היתה הלכה אחרת ש\u0003אמר רב יהודה אמר שמואל: מי ששתה רביעית יין, אל יורה\u0004 בדבר הלכה, לפי שהיין מבלבל דעתו, ועליה \u0003אמר רב נחמן: לא מעליא הא שמעתא\u0004 \u0005[לא מעולה\u0006 היא \u0005הלכה זו],\u0006 \u0003דהא אנא\u0004 \u0005[שהרי אני]\u0006 \u0003כל כמה דלא שתינא רביעתא דחמרא\u0004 \u0005[שאיני שותה רביעית יין] —\u0006 \u0003לא צילא דעתאי\u0004 \u0005[אין דעתי צלולה],\u0006 ורק לאחר שתיית יין יכול הוא להורות כדין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מאי טעמא אמר מר הכי\u0004 \u0005[מה הטעם\u0006 מדוע\u0005, אומר אדוני כך]\u0006 בשבחן ובגנותן של הלכות? \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' אחא בר חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ורעה זונות יאבד הון\"\u0004 (משלי כט, ג) רמזו של פסוק זה: \u0003כל האומר \"שמועה זו נאה\"\u0004 (שבקיצור נשמע כמו \"זונה\") ו\u0003\"זו אינה נאה\" מאבד הונה של תורה!\u0004 שאין הדבר לכבוד התורה שיתנו בה הערכות כאלה. \u0003אמר ליה\"\u0004 \u0005[לו]\u0006 רב נחמן: \u0003הדרי בי\u0004 \u0005[חוזר אני בי]\u0006 ולא אומר כך על דברי תורה.","בנושא זה של שתיית יין \u0003אמר רבה בר רב הונא: שתוי אל יתפלל, ואם התפלל\u0004 בכל זאת — \u0003תפלתו תפלה,\u0004 ויצא ידי חובה. \u0003שיכור\u0004 ממש \u0003אל יתפלל, ואם התפלל — תפלתו תועבה.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 \u0003שתוי, והיכי דמי\u0004 \u0005[וכיצד בדיוק]\u0006 \u0003שיכור?\u0004 ומשיבים שאפשר ללמוד את הדבר ממעשה זה; \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003ר' אבא בר שומני ורב מנשיא בר ירמיה מגיפתי הוו קא מפטרי מהדדי אמעברא\u0004 \u0005[היו נפרדים זה מזה על מעבורת]\u0006 של \u0003נהר יופטי. אמרו: כל חד מינן לימא מילתא דלא שמיע לחבריה\u0004 \u0005[כל אחד מאתנו יאמר דבר שלא שמע חבירו]\u0006 שהרי \u0003אמר מרי בר רב הונא: לא יפטר אדם מחברו אלא מתוך דבר הלכה, שמתוך כך זוכרו.\u0004","\u0003פתח חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003ואמר: היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 \u0003שתוי, והיכי דמי\u0004 \u0005[וכיצד בדיוק]\u0006 \u0003שיכור? שתוי — כל\u0004 ששתה ועדיין דעתו צלולה עד \u0003שיכול לדבר לפני המלך. שיכור\u0004 — משמע שהוא מבולבל \u0003כל\u0004 כך \u0003שאינו\u0004 מסוגל במצב זה \u0003לדבר לפני המלך.\u0004","\u0003פתח אידך\u0004 \u0005[האחר]\u0006 \u0003ואמר\u0004 הלכה אחרת: \u0003המחזיק בנכסי הגר\u0004 (שהוא זוכה בהם מן ההפקר, שאם לא היו לגר בנים שנולדו לאחר שנתגייר, כל הקודם זוכה ברכושו) \u0003מה יעשה ויתקיימו בידו?\u0004 שכיון שלא רכשם ביגיע כפיו, אם לא יעשה בהם דבר מצוה, יאבדו ממנו — \u0003יקח\u0004 (יקנה) \u0003בהן ספר תורה\u0004 במקצת הכספים, ובזכות מצוה זו שעשה, יישמר השאר. \u0003אמר רב ששת: אפילו\u0004"],["\u0003בעל בנכסי אשתו\u0004 שקבל בנדוניה נכסים מרובים ראוי גם לו לקנות בקצתם ספר תורה.","\u0003רבא אמר: אפילו עבד עיסקא ורווח\u0004 \u0005[עשה עסק והרויח\u0006 הרבה\u0005]\u0006 — ראוי לו לעשות כך. \u0003רב פפא אמר: אפילו מצא מציאה. אמר רב נחמן בר יצחק:\u0004 אין הכרח דוקא לכתוב ספר תורה, אלא \u0003אפילו כתב בהו\u0004 \u0005[בהם]\u0006 \u0003תפילין,\u0004 שכיון שעשה מצוה בממון זה, יזכה על ידה להחזיק בשאר.","\u0003ואמר רב חנין, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' חנינא: מאי קראה\u0004 \u0005[מהו המקרא]\u0006 המרמז על כך, שנאמר: \u0003\"וידר ישראל נדר\u0004 לה' ויאמר אם נתון תתן את העם הזה בידי והחרמתי את עריהם\u0003\"\u0004 (במדבר כא, ב) שהרוצים בהצלחה, ראוי להם להקדיש ממנה לשם שמים.","ועוד בענין שתיית יין \u0003אמר רמי בר אבא:\u0004 הילוך \u0003דרך\u0004 של \u0003מיל, ו\u0004כן \u0003שינה כל שהוא — מפיגים את היין\u0004 ששתה. \u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו\u0004 הלכה זו \u0003אלא ששתה כדי רביעית\u0004 בלבד, \u0003אבל שתה יותר מרביעית\u0004 אין עצות אלה מועילות, \u0003כל שכן שדרך טורדתו\u0004 ומעייפת אותו, \u0003ושינה\u0004 מועטה \u0003משכרתו.\u0004","ושואלים: \u0003ו\u0004כי \u0003דרך מיל\u0004 די בה ו\u0003מפיגה היין?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה ברבן גמליאל שהיה רוכב על החמור והיה מהלך\u0004 בדרך \u0003מעכו לכזיב, והיה ר' אילעאי\u0004 תלמידו \u0003מהלך אחריו. מצא גלוסקין\u0004 (עוגה) \u0003בדרך, אמר לו\u0004 רבן גמליאל: \u0003אילעאי, טול גלוסקין מן הדרך. מצא\u0004 בדרכו הלאה \u0003גוי אחד, אמר לו\u0004 רבן גמליאל לגוי: \u0003מבגאי, טול גלוסקין הללו מאילעאי.\u0004","\u0003ניטפל לו ר' אילעאי\u0004 לאותו גוי, ו\u0003אמר לו: מהיכן אתה? אמר לו: מעיירות של בורגנין\u0004 הסמוכות לכאן. שאלו: \u0003ומה שמך?\u0004 אמר לו: \u0003מבגאי שמני\u0004 \u0005[שמי]\u0006 שאלו: \u0003כלום היכירך רבן גמליאל מעולם,\u0004 שיודע הוא את שמך? \u0003אמר לו: לאו\u0004 \u0005[לא].\u0006","ועל סיפור זה העירו: \u0003באותה שעה למדנו שכוון רבן גמליאל ברוח הקודש\u0004 לדעת את שם הגוי. \u0003ושלשה דברים\u0004 של הלכה \u0003למדנו באותה שעה\u0004 ממנהגו של רבן גמליאל: \u0003למדנו שאין מעבירין\u0004 (עוברים) \u0003על האוכלין.\u0004 ואדם הרואה דבר מאכל מונח בדרך, צריך להתעכב ולהרימו.","\u0003ולמדנו שהולכין אחרי רוב עוברי דרכים,\u0004 שכיון שמקום זה מקום גויים היה, הניח רבן גמליאל שאף גלוסקא זו של גוים היא, ואסורה באכילה לישראל, ולכן ציוה לתתה לגוי. \u0003ולמדנו שחמצו של גוי אחר הפסח, מותר בהנאה.\u0004 שאותו מעשה אחר הפסח היה, שהרי יש טובת הנאה מסויימת כשנותן את העוגה מתנה לגוי, ואינו מבערה כדין חמץ שעבר עליו הפסח.","מסופר עוד, \u0003כיון שהגיע\u0004 רבן גמליאל \u0003לכזיב בא אחד לישאל על נדרו. אמר לזה שעמו\u0004 (לר' אלעאי): \u0003כלום שתינו רביעית יין האיטלקי\u0004 קודם לכן? \u0003אמר לו: הן.\u0004 אמר לו: \u0003אם כן, יטייל אחרינו עד שיפיג יינינו\u0004 ואחר כך נוכל לעסוק בענינו.","\u0003וטייל\u0004 אותו אדם \u0003אחריהן שלשה מילין, עד שהגיעו לסולמא\u0004 \u0005[סולמה]\u0006 \u0003של צור. כיון שהגיע לסולמא של צור, ירד רבן גמליאל מן החמור, ונתעטף\u0004 בטליתו כדרך שעושים שיהא הדיין באימה וביראה בשעת הדין, \u0003וישב, והתיר לו נדרו.\u0004","ומעירים: \u0003והרבה דברים\u0004 של הלכה \u0003למדנו באותה שעה. למדנו שרביעית יין האיטלקי משכר, ולמדנו\u0004 מכאן כי \u0003שיכור אל יורה, ולמדנו שדרך מפיגה את היין, ולמדנו שאין מפירין נדרים לא\u0004 כשהמפיר \u0003רכוב ולא מהלך ולא עומד אלא יושב.\u0004","\u0003קתני מיהת\u0004 \u0005[מכל מקום שנינו\u0006 כאן\u0005]\u0006 שהצריך רבן גמליאל הילוך של \u0003שלשה מילין\u0004 כדי להתפכח מהיין! ומשיבים: אין זו סתירה, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003יין האיטלקי\u0004 שהוא \u0003משכר טפי\u0004 \u0005[ביותר]\u0006 וצריך דרך ארוכה יותר כדי להפיגו.","ושואלים: האם אמנם כן הוא הטעם? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר רבה בר אבוה: לא שנו אלא ששתה רביעית, אבל שתה יותר מרביעית, כל שכן דרך טורדתו ושינה משכרתו!\u0004 ואם היין האיטלקי משכר יותר — הריהו כיותר מרביעית?","ומשיבים: \u0003רכוב שאני\u0004 \u0005[שונה],\u0006 שכיון שאינו מהלך ברגליו, אין הדרך טורדתו, אף שגם יינו אינו פג במהירות. ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן],\u0006 \u0003ל\u0004שיטת \u0003רמי בר אבא\u0004 האומר שבהילוך מיל די, \u0003נמי לא קשיא\u0004 \u0005[גם כן אינו קשה]\u0006 שיכול אף הוא לומר \u0003רכוב שאני\u0004 \u0005[שונה]\u0006 וצריך לרכב יותר ממיל אחד.","ולפרטי המעשה מוסיפים ושואלים לגופם: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שחייב היה רבן גמליאל לרדת מהחמור כדי להתיר את הנדר?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: מפירין נדרים בין מהלך בין עומד ובין רכוב!\u0004 ומדוע אם כן, ירד רבן גמליאל מחמורו?","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא דאיכא למאן דאמר\u0004 \u0005[שיש מי שאומר]:\u0006 \u0003פותחין בחרטה\u0004 שאין לחפש להתרת הנדר טעם מיוחד להתירו, ודי כשאומר שהוא מתחרט על הנדר שנדר. ודבר זה אפשר לעשותו בקלות, אף בעמידה ברכיבה ובהליכה.","\u0003ואיכא למאן דאמר\u0004 \u0005[ויש מי שאומר]:\u0006 \u0003אין פותחין בחרטה,\u0004 אלא יש למצוא \"פתח\" — טעם היתר מיוחד לנדר זה, והדבר דורש עיון מרובה, ולצורך זה צריך יישוב הדעת, שאיננו קיים אלא בישיבה (תוס').","שכן \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מאי\u0004 \u0005[\u0006ב\u0005מה]\u0006 \u0003פתח ליה\u0004 \u0005[לו],\u0006 מה פתח היתר מצא \u0003רבן גמליאל לההוא גברא\u0004 \u0005[לאותו אדם],\u0006 שאמר לו על הכתוב \u0003\"יש בוטה כמדקרות חרב ולשון חכמים מרפא\"\u0004 (משלי יב, יח) והסביר לו: \u0003כל הבוטה\u0004 (המבטא) דברי נדר \u0003ראוי לדוקרו בחרב,\u0004 שמא לא יקיימו ולכך מלכתחילה אין ראוי כלל לאדם לנדור נדר. ואף אתה, אילו היית יודע שכל הנודר מתחייב בנפשו, האם היית נודר? \u0003אלא שלשון חכמים מרפא,\u0004 שאם מתירים לו חכמים, הרי הם מפקיעים את הנדר מעיקרו, וכאילו לא נדר.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 בתוך הדברים שסופרו ברבן גמליאל למדנו ש\u0003אין מעבירין על האוכלין\u0004 ויש להיזהר בכבודם ולהרימם. \u0003אמר ר' יוחנן משום [בשם] ר' שמעון בן יוחאי: לא שנו\u0004 הלכה זו \u0003אלא בדורות הראשונים, שאין בנות ישראל פרוצות\u0004 (רגילות ומשתמשות) \u0003בכשפים. אבל בדורות האחרונים, שבנות ישראל פרוצות בכשפים, מעבירין.\u0004 שמא עשו כשפים באותו לחם, ואין לאדם להסתכן בכך.","\u0003תנא\u0004 \u0005[שנינו]:\u0006 אם היו אלה לחמים \u0003שלימין — מעבירין\u0004 עליהם, שיש לחשוש שמא לכשפים הונחו. ואם מצא \u0003פתיתין — אין מעבירין,\u0004 משום שאין עושים בהם כשפים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אסי לרב אשי: ו\u0004כי על \u0003פתיתין לא עבדן\u0004 \u0005[אין הן עושות]\u0006 כשפים? והרי בכתוב המדבר במכשפות נאמר: \u0003\"ותחללנה אתי אל עמי בשעלי שערים ובפתותי לחם\"\u0004 (יחזקאל יג, יט) ומשיבים: אין הכוונה שעשו כשפים בפתותי הלחם, אלא פתיתים אלו הם \u0003דשקלי באגרייהו\u0004 \u0005[שהן מקבלות בשכרן]\u0006 אבל לכשפים, אין הפתיתים ראויים.","\u0003אמר רב ששת משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר בן עזריה:\u0004"],["\u0003יכול אני\u0004 לטעון טענה \u0003לפטור את כל העולם כולו מן הדין מיום שחרב בית המקדש ועד עכשיו, שנאמר: \"לכן שמעי נא זאת עניה ושכרת ולא מיין\"\u0004 (ישעיהו נא, כא). הרי שכל בני ישראל הינם לאחר חורבן בית המקדש בבחינת שיכורים, ואינם אחראים לעבירות שעברו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: כיצד אפשר לומר כן, והרי נפסק כי \u0003שיכור מקחו מקח\u0004 ואינו רשאי לאחר שהתפכח, לחזור בו מהמקח, \u0003ו\u0004כן \u0003ממכרו ממכר.\u0004 ואם \u0003עבר עבירה שיש בו מיתה — ממיתין אותו,\u0004 ואם יש בה עונש \u0003מלקות — מלקין אותו. כללו של דבר: הרי הוא כפיקח לכל דבריו, אלא שפטור מן התפלה.\u0004 ואם כן, אף אם שיכורים הם ישראל — עדיין הם אחראים למעשיהם.","ומתרצים שאף דברי ר' אלעזר בן עזריה לא לפטור מעונשה של כל עבירה נתכוונו, אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יכולני לפטור\" דקאמר נמי\u0004 \u0005[שאמר, גם כן]\u0006 כוונתו: \u0003מדין תפלה,\u0004 שאין להאשים את ישראל אם אינם מתפללים כראוי.","\u0003אמר ר' חנינא: לא שני\u0004 שהשיכור אחראי לכל מעשיו \u0003אלא שלא הגיע לשכרותו של לוט, אבל אם הגיע לשכרותו של לוט\u0004 שאינו יודע מה עושה — \u0003פטור מכולם.\u0004","\u0003אמר ר' חנינא: כל המפיק מגן בשעת גאוה\u0004 כלומר כל המכסה ושם כעין מגן על יצרו בשעת גאות היצר, כגון בשכרות וכיוצא בה (ר\"ח), \u0003סוגרין וחותמין צרות בעדו. שנאמר: \"גאוה אפיקי מגנים סגור חותם צר\"\u0004 (איוב מא, ז) הנדרש: כאשר אדם בשעת גאוה (\"גאוה\") שם מגן על יצרו (\"אפיקי מגנים\"), סוגרים לו וחותמים מלפניו את הצרות (\"חותם צר\").","ושואלים: \u0003מאי משמע\u0004 \u0005[מהי המשמעות,\u0006 כיצד אפשר להבין\u0005]\u0006 \u0003דהאי\u0004 \u0005[ש\u0006משמעות \u0005זו\u0006 המלה\u0005]\u0006 \u0003\"אפיק\",\u0004 שהוא צורת היחיד של \"אפיקי\" האמור בכתוב, \u0003לישנא דעבורי\u0004 \u0005[לשון עבירה\u0006 ודילוג\u0005]\u0006 \u0003הוא?\u0004 ועונים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אחי בגדו כמו נחל כאפיק נחלים יעברו\"\u0004 (איוב ו, טו), ומשמעו שאפיק הוא דבר ההולך ועובר.","\u0003ר' יוחנן אמר:\u0004 לא כך יש לדרוש, אלא כך: \u0003כל שאינו\u0004 מעביר ומכסה אלא \u0003מפיק\u0004 \u0005[מוציא]\u0006 מגן בשעת גאוה \u0003אתמר\u0004 \u0005[נאמר],\u0006 שצריך אדם להוציא מגן וכלי נשק ולהלחם ביצרו בשעה שתוקפו (ר\"ח).","ושואלים: \u0003מאי משמע\u0004 \u0005[מהי המשמעות,\u0006 מנין למדים אנו\u0005]\u0006 \u0003דהאי מפיק לישנא דגלויי\u0004 \u0005[שמפיק זה לשון של גילוי]\u0006 \u0003הוא?\u0004 ועונים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויראו אפיקי מים ויגלו מוסדות תבל\"\u0004 (תהילים יח, טז).","ושואלים: \u0003מכדי, קראי משמע\u0004 \u0005[הואיל ו\u0006דברי \u0005הכתובים משמעם,\u0006 ניתנים לדרשה\u0005]\u0006 \u0003בין ל\u0004שיטת \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003ובין למר\u0004 \u0005[לחכם זה],\u0006 \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין זה של \u0003רב ששת.\u0004 כי \u0003רב ששת מסר\u0004 את ההשגחה על \u0003שינתיה לשמעיה\u0004 \u0005[שנתו לשמשו],\u0006 והיה אומר לו: העירני כשיגיע זמן תפלה. \u0003מר, אית ליה\u0004 \u0005[חכם זה,\u0006 ר' חנינא \u0005יש לו\u0006 לשיטת\u0005]\u0006 \u0003רב ששת.\u0004 וסבור ר' חנינא שבשעה ששינה מתגברת עליו, מוטב שיישן מעט, ואחר כך יתגבר. \u0003ומר, לית ליה\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן\u0005, אין לו\u0006 לשיטת\u0005]\u0006 \u0003רב ששת.\u0004 וסבור הוא שיש להתגבר על עצמו ולהתפלל, ולא להיכנע לשינה.","\u0003אמר רב חייא בר אשי אמר רב: כל שאין דעתו מיושבת עליו — אל יתפלל, משום שנאמר \"בצר אל יורה\".\u0004 מסופר, \u0003ר' חנינא ביומא דרתח, לא מצלי\u0004 \u0005[ביום שהיה כועס\u0006 בו, \u0005לא\u0006 היה \u0005מתפלל]\u0006 \u0003אמר: \"בצר אל יורה\" כתיב\u0004 \u0005[נאמר].\u0006 וכן מסופר, \u0003מר עוקבא ביומא דשותא, לא הוה נפיק לבי דינא\u0004 \u0005[ביום של רוח דרומית, לא היה יוצא לבית הדין].\u0006 שרוח זו חמה וקשה, ולא היתה דעתו צלולה עליו כראוי.","\u0003אמר רב נחמן בר יצחק: הלכתא בעיא צילותא כיומא דאסתנא\u0004 \u0005[\u0006עיון \u0005הלכה דורש צלילות\u0006 הדעת \u0005כיום של רוח צפונית]\u0006 שהיא נוחה לכל. \u0003אמר אביי\u0004 מעין זה: \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמרה לי אם\u0004 (האומנת): \u0003קריב כותחא\u0004 \u0005[הבא\u0006 לי \u0005כותח] —\u0006 שוב \u0003לא תנאי\u0004 \u0005[אינני\u0006 יכול \u0005ללמוד]\u0006 כפי רגילותי\u0005,\u0006 שאפילו מלאכה קלה כזו מטרידתו ומפריעה ללימודו.","ובדומה לזה \u0003אמר רבא: אי קרצתן\u0004 \u0005[אם עקצתני]\u0006 \u0003כינה —\u0004 שוב \u0003לא תנאי\u0004 \u0005[אינני\u0006 יכול \u0005ללמוד\u0006 כפי רגילותי\u0005]. מסופר:\u0006 \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא עבדה ליה אמיה\u0004 \u0005[עשתה לו אמו]\u0006 \u0003שבעה מני\u0004 \u0005[בגדים]\u0006 \u0003לשבעה יומי\u0004 \u0005[ימים],\u0006 שלא יעקצוהו כנים הנמצאות בבגדים ישנים (ר\"ח).","\u0003אמר רב יהודה: לא איברי ליליא\u0004 \u0005[נברא הלילה]\u0006 \u0003אלא לשינתא\u0004 \u0005[לשינה].\u0006 \u0003אמר ר' שמעון בן לקיש: לא איברי סיהרא\u0004 \u0005[נברא הירח]\u0006 \u0003אלא לגירסא\u0004 \u0005[ללמוד]\u0006 לאורו. \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003לר' זירא: מחדדן שמעתך\u0004 \u0005[מחודדות,\u0006 מפולפלות \u0005הלכותיך]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דיממי נינהו\u0004 \u0005[של\u0006 שעות \u0005היום הן],\u0006 ומכאן שהלימוד ביום מועיל ויפה לצלילות הדעת.","\u0003אמרה ליה ברתיה\u0004 \u0005[לו בתו]\u0006 של \u0003רב חסדא לרב חסדא\u0004 אביה: \u0003לא בעי מר מינם פורתא\u0004 \u0005[האין אדוני רוצה לישון מעט]?\u0006 \u0003אמר לה: השתא אתו יומי דאריכי וקטיני, ונינום טובא\u0004 \u0005[עכשיו\u0006 עוד מעט \u0005באים ימים ארוכים וקצרים, ונישן הרבה].\u0006 כלומר לאחר מיתה, שעשויים להאריך בשינה ולקצר בלימוד התורה.","\u0003אמר רב נחמן בר יצחק: אנן פועלי דיממי אנן\u0004 \u0005[אנחנו,\u0006 תלמידי חכמים\u0005, פועלי יום אנחנו],\u0006 ועיקר עבודתנו הלימוד, ואינה אלא ביום. ומסופר על \u0003רב אחא בר יעקב\u0004 שהיה \u0003יזיף ופרע\u0004 \u0005[לווה ומחזיר],\u0006 שאם בטל מלימוד בשעות היום, היה שונה אותו זמן שהפסיד, בשעות הלילה.","\u0003אמר ר' אלעזר: הבא מן הדרך, אל יתפלל שלשה ימים,\u0004 עד שינוח מטורח הדרך, \u0003שנאמר: \"ואקבצם אל הנהר הבא אל אחוא ונחנה שם ימים שלשה ואבינה בעם\" וגו'\u0004 (עזרא ח, טו). ונאמר לאחר מכן \"ואקרא שם צום על הנהר אהוא להתענות לפני אלוהינו ולבקש ממנו דרך ישרה\" (עזרא ח, כא), משמע שלפני שנחו שלשה ימים, לא יכלו להתפלל.","מסופר, \u0003אבוה דשמואל, כי אתי באורחא, לא מצלי תלתא יומי\u0004 \u0005[אביו של שמואל, כאשר היה בא מן הדרך, לא היה מתפלל שלשה ימים]\u0006 שנח מטורח הדרך. \u0003שמואל\u0004 עצמו \u0003לא מצלי בביתא דאית ביה שיכרא\u0004 \u0005[היה מתפלל בבית שיש בו שיכר],\u0006 שריח השיכר היה מפריע לו מהתרכזות בתפלה. וכן, \u0003רב פפא לא מצלי בביתא דאית ביה הרסנא\u0004 \u0005[היה מתפלל בבית שיש בו דגים קטנים\u0006 מטוגנים\u0005]\u0006 משום ריחם.","\u0003אמר ר' חנינא: כל המתפתה ביינו,\u0004 שלאחר ששותה יין נעשה נוח יותר לבריות, \u0003יש בו מדעת קונו\u0004 (ה'). שאף הקדוש ברוך הוא נוהג כן, שנאמר \u0003\"וירח ה' את ריח הניחח\u0004 ויאמר ה' אל לבו לא אוסיף לקלל עוד את האדמה בעבור האדם\u0003\"\u0004 (בראשית ח, כא), שכביכול אף הוא מתרצה לבריות לאחר שמפייסים אותו במשהו, וכפי ששנינו למעלה שכח הריח הוא כשתיה עצמה.","\u0003אמר ר' חייא: כל המתיישב ביינו\u0004 ואינו משתכר — \u0003יש בו דעת שבעים זקנים.\u0004 ורמז לדבר: \u0003יין ניתן בשבעים אותיות,\u0004 שחשבון הגימטריא של \"יין\" הוא שבעים. וכן חשבון הגימטריא של \u0003\"סוד\" ניתן בשבעים אותיות. נכנס יין יצא סוד,\u0004 ומי שאינו מגלה סוד בשעת היין — סימן שדעתו איתנה.","\u0003אמר ר' חנין: לא נברא יין אלא לנחם אבלים\u0004 בצערם, \u0003ולשלם שכר לרשעים\u0004 שיהנו ממנו בעולם הזה ולא יקבלו שכר לעתיד, \u0003שנאמר: \"תנו שכר לאובד\u0004 ויין למרי נפש ישתה וישכח רישו\u0003\"\u0004 (משלי לא, ו). ה\"אובד\" הוא הרשע האובד מן העולם, ו\"מרי הנפש\" הם האבלים.","\u0003אמר ר' חנין בר פפא: כל שאין יין נשפך בתוך ביתו כמים — אינו בכלל ברכה,\u0004 שעדיין לא התקיימה בו ברכת התורה, \u0003שנאמר \"וברך את לחמך ואת מימיך\"\u0004 (שמות כג, כה) ורמז שמים אלה שנאמרו בפסוק זה משמעם יין נלמד בדרך ההיקש: \u0003מה לחם,\u0004 דבר \u0003שניקח\u0004 (שניקנה) \u0003בכסף מעשר,\u0004 שמותר לקנותו בכסף שנפדה בו מעשר שני — \u0003אף מים\u0004 מדובר בנוזלים \u0003שניקח בכסף מעשר, ומאי ניהו\u0004 \u0005[ומהו]\u0006 — \u0003יין,\u0004 שמותר לקנותו בכסף מעשר, ולא מים כפשוטם, \u0003וקא קרי ליה\u0004 \u0005[והוא קורא לו]\u0006 \u0003מים.\u0004"],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003נשפך בביתו כמים — איכא\u0004 \u0005[יש]\u0006 \u0003ברכה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא,\u0004","\u0003אמר ר' אילעאי: בשלשה דברים אדם ניכר\u0004 ונודע מה אופיו האמיתי: \u0003בכוסו\u0004 בשעת שתיה, \u0003בכיסו\u0004 כאשר עליו להוציא כסף \u0003ובכעסו. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אף בשחקו\u0004 שאף אז מתגלה מהותו של אדם.","\u0003אמר רב יהודה אמר רב:\u0004 היו שתי חצירות זו לפנים מזו, \u0003ישראל וגוי\u0004 גרים בחצר ה\u0003פנימית, וישראל\u0004 אחד גר \u0003בחיצונה. בא מעשה\u0004 זה \u0003לפני רבי\u0004 אם אפשר להתיר חצר זו על ידי עירוב בלא לשכור מן הגוי, \u0003ואסר.\u0004 בא המעשה \u0003לפני ר' חייא, ואסר.\u0004","\u0003יתוב\u0004 \u0005[ישבו]\u0006 \u0003רבה ורב יוסף בשילהי פירקיה\u0004 \u0005[בסוף דרשתו]\u0006 של \u0003רב ששת ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב ששת וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003כמאן\u0004 \u0005[כ\u0006שיטתו של \u0005מי]\u0006 \u0003אמרה רב לשמעתיה\u0004 \u0005[להלכתו]\u0006 זו בענין הדרים בשתי חצירות, \u0003כ\u0004שיטתו של \u0003ר' מאיר,\u0004 שלדעתו גוי אוסר אף על ישראל אחד הדר עמו וצריך לשכור. \u0003כרכיש\u0004 \u0005[הניד]\u0006 \u0003רבה רישיה\u0004 \u0005[ראשו]\u0006 כמסכים להסבר זה.","\u0003אמר רב יוסף: תרי גברי רברבי כרבנן, ליטעו בהאי מילתא\u0004 \u0005[שני אנשים גדולים כחכמים\u0006 אלה, רבה ורב ששת\u0005, שיטעו בדבר זה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הלכה זו \u0003כ\u0004שיטתו של \u0003ר' מאיר,\u0004 אם כן \u0003למה לי ישראל בחיצונה?\u0004 שהרי לשיטת ר' מאיר גם אם לא היה עוד ישראל, אסור היה לישראל הדר עם הגוי לטלטל בחצירו.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שכן הוא להלכה, ואין חשיבות אם היה ישראל בחיצונה, אלא \u0003מעשה שהיה כך היה,\u0004 ונזדמן שבאו לשאול כשארע הדבר באופן זה, \u0003ו\u0004אולם \u0003הא בעו מיניה\u0004 \u0005[והרי שאלו אותו]\u0006 את \u0003רב\u0004 עצמו באותו ענין: \u0003פנימי במקומו מהו?\u0004 כלומר ישראל הדר בחצר הפנימית, האם מותר לו כשלעצמו לטלטל בחצר זו? \u0003ואמר להם: מותר,\u0004 משמע שגוי אינו אוסר על ישראל אחד, ושלא כשיטת ר' מאיר כלל.","ומקשים: \u0003ואלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 שפסק \u0003כר' אליעזר בן יעקב? והאמר\u0004 \u0005[והרי אמר]:\u0006 \u0003עד שיהו שני ישראלים אוסרים זה על זה!\u0004 ובמקרה זה הרי אינם באותה חצר, ואינם יכולים לאסור זה על זה.","\u0003אלא\u0004 תאמר שפסקו \u0003כר' עקיבא,\u0004 ש\u0003אמר: רגל המותרת במקומה\u0004 בכל זאת \u0003אוסרת שלא במקומה,\u0004 ולכן אף שהישראלי שבחצר הפנימית רשאי לטלטל בחצירו, מכל מקום החצר החיצונה אסורה עליו, וכיון שהוא עובר בה הריהו אוסר גם על חבירו.","ואולם יש להקשות: אם כשיטה זו, \u0003למה לי גוי? אפילו ישראל\u0004 הפנימי \u0003נמי\u0004 \u0005[גם כן]\u0006 דיו לאסור על שניהם את הטלטול באותן חצירות לשיטת ר' עקיבא, גם אם לא היה גוי כלל!","\u0003אמר ר' הונא בריה\u0004 \u0005[בנו]\u0006 \u0003של רב יהושע\u0004 שכך יש להבין: \u0003לעולם כר' אליעזר בן יעקב\u0004 לענין גוי, \u0003וכ\u0004שיטת \u0003ר' עקיבא\u0004 לענין רגל אסורה, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 \u0003כגון שעירבו\u0004 אותם שני ישראלים זה עם זה, \u0003וטעמא\u0004 \u0005[והטעם\u0006 דוקא\u0005]\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003גוי דאסיר\u0004 \u0005[שאוסר],\u0006 \u0003אבל ליכא\u0004 \u0005[\u0006אם \u0005אין]\u0006 \u0003גוי לא אסיר\u0004 \u0005[אוסר],\u0006 שהרי עירבו ומותרים הם.","מספרים, \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' אלעזר מרב:\u0004 היו \u0003ישראל וגוי ב\u0004חצר ה\u0003חיצונה וישראל בפנימית מהו,\u0004 האם יכולים לטלטל בחיצונית ללא שכירות דירת הגוי? \u0003התם\u0004 \u0005[שם]\u0006 בישראל וגוי שבחצר הפנימית \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאסור הוא \u0003משום דשכיח דדייר\u0004 \u0005[שמצוי שדרים]\u0006 ישראל וגוי באופן זה, כי אותו ישראל שבחצר הפנימית סבור \u0003דמירתת\u0004 \u0005[שמפחד]\u0006 ה\u0003גוי\u0004 להרוג את שכנו, \u0003וסבר\u0004 \u0005[וחושב]:\u0006 \u0003השתא אתי\u0004 \u0005[עכשיו יבוא]\u0006 \u0003ישראל\u0004 הגר בחצר החיצונית \u0003ואמר לי: ישראל דהוה גבך היכא\u0004 \u0005[שהיה\u0006 גר \u0005אצלך היכן\u0006 הוא\u0005]?\u0006 ולא יוכל להשתמט ולומר שהלך לו, שהרי היהודי האחר יושב בחצר החיצונה ויודע אם עבר דרכה אם לא, ולכן דירת הגוי אוסרת.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 כאשר גר הגוי בחצר החיצונה, אינו חושש להרוג את הישראלי שכנו. ואומר הוא לעצמו: אם יבוא האחר וישאלני, \u0003אמינא ליה\u0004 \u0005[אומר לו]\u0006: \u0003נפק אזל ליה\u0004 \u0005[יצא\u0006 ו\u0005הלך לו]\u0006 ואין אני יודע לאן.","\u0003או דילמא, הכא נמי מירתת\u0004 \u0005[שמא, כאן גם כן מפחד\u0006 הוא\u0005]\u0006 \u0003דסבר: השתא אתי\u0004 \u0005[ש\u0006הוא \u0005סבור: עכשיו יבוא]\u0006 \u0003ישראל\u0004 הפנימי \u0003וחזי לי\u0004 [\u0005ויראה אותי]\u0006 בשעה שאני הורג את חבירו. שהרי אינו יודע מתי יעבור האיש מהחצר הפנימית שדרכו לעבור בחיצונה, ושמא יראהו בשעת מעשה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 כדברי הכתוב: \u0003\"תן לחכם ויחכם עוד\"\u0004 (משלי ט, ט) כלומר, יש להחמיר אף במקרה זה, ואסור לטלטל שם, אלא אם כן שכר מהגוי.","מסופר, \u0003ריש לקיש ותלמידי דר' חנינא איקלעו לההוא פונדק\u0004 \u0005[הזדמנו לפונדק אחד]\u0006 שחדריו היו עשויים להשכרה, ובאותו פונדק היו דרים בקביעות לפחות שני ישראלים וגוי אחד ששכרו דירותיהם מבעל הפונדק שהיה אף הוא גוי. \u0003ו\u0004אולם \u0003לא הוה\u0004 \u0005[היה]\u0006 מצוי באותו מקום \u0003שוכר\u0004 הדירה שהלך באותה שבת, אבל \u0003הוה\u0004 \u0005[היה]\u0006 במקום ההוא הגוי ה\u0003משכיר,\u0004 וחששו שמא יחזור הגוי השוכר בשבת לביתו ויאסור עליהם, ולכן דנו בשאלה האם יכול משכיר הדירה הגוי לחזור ולהשכירה לצורך עירוב.","\u0003אמרו: מהו למיגר מיניה\u0004 \u0005[\u0006האם אפשר \u0005לשכור ממנו]\u0006 ומפרטים; \u0003כל היכא דלא מצי מסליק ליה\u0004 \u0005[מקום שאינו יכול לסלק אותו\u0006 את השוכר\u0005] —\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, \u0003דלא אגרינא\u0004 \u0005[שאין שוכרים].\u0006 כי אם המשכיר איננו יכול לסלק את שוכר הדירה ממקומו, הרי שלפי הדין הדירה היא לפי שעה של השוכר בלבד, ורק הוא יכול להשכירה. \u0003כי תיבעו\u0004 \u0005[כאשר תישאל]\u0006 השאלה — הרי זה \u0003היכא דמצי מסליק ליה\u0004 \u0005[במקום שיכול הוא לסלק אותו].\u0006","\u0003מאי [מה]? כיון דמצו מסליק אגרינא\u0004 \u0005[שיכול לסלק\u0006 את השוכר, \u0005שוכרים\u0006 ממנו\u0005],\u0006 שהדירה נמצאת עוד במדת מה ברשותו של המשכיר ואפשר לשכור ממנו אותה דירה עצמה. \u0003או דילמא, השתא מיהא הא לא סלקיה\u0004 \u0005[שמא, עכשיו\u0006 בכל אופן \u0005הרי לא סלקו]\u0006 ועדיין הדירה ברשות השוכר?","\u0003אמר להן ריש לקיש: נשכור,\u0004 שהרי כלל הוא שבכל ספק שבדברי חכמים נוטים להקל. \u0003ולכשנגיע אצל רבותינו שבדרום, נשאל להן\u0004 אם יפה עשינו. לאחר מכן \u0003אתו שיילו\u0004 \u0005[באו שאלו]\u0006 את \u0003ר' אפס, אמר להן: יפה עשיתם ששכרתם.\u0004","כיוצא בו מסופר: \u0003ר' חנינא בר יוסף ור' חייא בר אבא ור' אסי איקלעו לההוא פונדק דאתא גוי מרי דפונדק בשבתא\u0004 \u0005[הזדמנו לפונדק אחד שבא הגוי בעל הפונדק בשבת]\u0006 אבל לא היה שם מבעוד יום. \u0003אמרו: מהו למיגר מיניה\u0004 \u0005[\u0006האם יש \u0005לשכור ממנו]?\u0006 וצדדי השאלה: האם \u0003שוכר כמערב דמי\u0004 \u0005[נחשב]\u0006 \u0003שהרי כמו בעירוב, גם בכך הוא מכשיר את רשותו לטלטול.\u0004","\u0003מה מערב מבעוד יום\u0004 יכול לערב, אבל לא לאחר כניסת השבת, \u0003אף שוכר\u0004 אינו יכול לשכור אלא \u0003מבעוד יום. או דילמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003שוכר כמבטל רשות דמי\u0004 \u0005[נחשב],\u0006 \u0003מה מבטל רשות\u0004 יכול לבטל \u0003ואפילו בשבת\u0004 עצמה, \u0003אף שוכר — ואפילו בשבת?\u0004 ויוכלו לשכור מן הגוי בשוה כסף בשבת עצמה.","\u0003ר' חנינא בר יוסף אמר: נשכור, ורב אסי אמר: לא נשכור, אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' חייא בר אבא: נסמוך על דברי זקן\u0004 הוא ר' חנינא בר יוסף \u0003ונשכור.\u0004 לאחר מכן \u0003אתו שיילו ליה\u0004 \u0005[באו שאלו\u0006 בענין זה \u0005את]\u0006 \u0003ר' יוחנן, אמר להן:\u0004"],["\u0003יפה עשיתם ששכרתם.\u0004 בשמועה זו \u0003תהו\u0004 (תמהו) \u0003בה נהרדעי\u0004 \u0005[\u0006חכמי \u0005נהרדעא]:\u0006 \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: שוכר כמערב דמי\u0004 \u0005[נחשב],\u0006 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 כך צריך לפרש, \u0003שכוונתו להחמיר: מה מערב\u0004 אינו מערב אלא \u0003מבעוד יום, אף שוכר מבעוד יום!\u0004","ודוחים: \u0003לא,\u0004 שלא התכוון אלא להקל וכך יש לדמות: \u0003מה מערב, ואפילו בפחות משוה פרוטה,\u0004 עירובו עירוב, \u0003אף שוכר בפחות משוה פרוטה. ומה מערב\u0004 יכול \u0003אפילו שכירו ולקיטו\u0004 שותפו הישראלי של הגוי לערב, \u0003אף שוכר\u0004 אינו חייב לשכור מבעל הבית עצמו, \u0003אלא אפילו שכירו ולקיטו\u0004 משכיר בשמו ומטעמו.","\u0003ו\u0004כן, \u0003מה מערב\u0004 דינו שאם \u0003חמשה ששרויין בחצר אחת — אחד מערב על ידי כולן\u0004 שאחד מבני חצר יכול לערב עם חצר אחרת, ואין צורך שכולם יערבו, אף \u0003שוכר נמי\u0004 \u0005[גם כן],\u0006 \u0003חמשה ששרויין בחצר אחת\u0004 עם הגוי, \u0003אחד שוכר על ידי כולן.\u0004","\u0003תהי\u0004 \u0005[היה תמה]\u0006 \u0003בה\u0004 בשמועה זו, שהובאה לעיל, ששכרו את דירת הגוי ולאחר מכן ביטלוה כדי שלא יאסור עליהם, \u0003ר' אלעזר. אמר ר' זירא: מאי תהייא\u0004 \u0005[מה\u0006 היא \u0005תמיהתו]\u0006 של \u0003ר' אלעזר? אמר רב ששת: גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003כר' זירא לא ידע מאי תהייא\u0004 \u0005[יודע מה תמיהתו]\u0006 של \u0003ר' אלעזר? קא קשיא ליה דשמואל רביה\u0004 \u0005[הוקשה לו\u0006 מה \u0005ש\u0006אמר \u0005שמואל רבו]\u0006","ש\u0003אמר שמואל: כל מקום שאוסרין\u0004 האחד על השני, \u0003ומערבין,\u0004 אם רצו, כדי להתירם בטילטול — \u0003מבטלין\u0004 את רשות הגוי כדי להתירה בטלטול, אם שכחו לערב. אבל מקום ש\u0003מערבין, ואין\u0004 הדיירים \u0003אוסרים\u0004 זה על זה, וכן \u0003אוסרין\u0004 זה על זה, אבל \u0003אין מערבין — אין מבטלין.\u0004","וביאור הדברים בפירוט: \u0003כל מקום שאוסרין ומערבין — מבטלין, כגון שתי חצירות זו לפנים מזו\u0004 ששתי החצירות אוסרות זו על זו ויכולות לעשות עירוב משותף זו עם זו כדי להתירן, ואכן, אף אם לא עירבו, יכולים הדיירים לבטל רשותם לגבי אחד מהם.","מהו \u0003מערבין ואין אוסרין — אין מבטלין, כגון שתי חצירות הפתוחות למבוי ופתח אחד ביניהן,\u0004 שאמנם יכולות שתי החצירות לערב ולהיעשות כחצר אחת. אבל אם לא עירבו, אין החצירות אוסרות זו על זו, לפי שאינן חייבות להשתמש זו בזו, וכיון שכך אף אי אפשר לבטל רשות מחצר לחברתה.","מה שאמרו: \u0003אוסרין ואין מערבין — אין מבטלין. לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005מה]\u0006 לאיזה ענין אמר זאת שמואל, \u0003לאו לאתויי\u0004 \u0005[האם לא להביא,\u0006 לרבות\u0005]\u0006 \u0003גוי\u0004 הגר בחצר אחת עם שני ישראלים? שבני חצר זו אוסרים, אבל אינם מערבים בשל הגוי.","ונדון בפרטי הדברים: \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר פה \u0003דאתא\u0004 \u0005[שבא]\u0006 הגוי \u0003מאתמול\u0004 לפני השבת \u0003לוגר\u0004 \u0005[שישכור]\u0006 \u0003מאתמול\u0004 ותהא אז אפשרות לערב או לבטל, ואין כאן \"אוסרין ואין מערבין\"!"],["\u0003אלא לאו דאתא בשבתא\u0004 \u0005[האם לא\u0006 מדובר כאן \u0005שבא\u0006 הגוי \u0005בשבת],\u0006 \u0003וקתני\u0004 \u0005[ושנינו]\u0006 \u0003אוסרין ואין מערבין, אין מבטלין.\u0004 ו\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאי אפשר לבטל רשות כשבא הגוי ביום שבת. ולכן תהה ר' אלעזר על דברי ר' יוחנן, משום שהם סותרים את דברי שמואל, רבו הראשון.","\u0003אמר רב יוסף: לא שמיע לי\u0004 \u0005[שמעתי]\u0006 \u0003הא שמעתא\u0004 \u0005[הלכה זו]\u0006 שאמר שמואל בשתי חצירות זו לפנים מזו, שהפנימיים מבטלים את דריסת רגלם בחיצונה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: את אמרת ניהלן, ואהא אמרת ניהלן\u0004 \u0005[אתה אמרת\u0006 אותה \u0005לנו, ועל\u0006 דבר \u0005זה אמרת\u0006 אותה \u0005לנו]\u0006 (שרב יוסף שכח את תלמודו בשעת מחלתו והזכירו אביי תלמידו), ש\u0003אמר שמואל: אין ביטול רשות מחצר לחצר,\u0004 שיכול אדם לבטל רשות דירתו בחצר אחת, אבל לא מחצר אחת לחברתה.","ואף \u0003אין ביטול רשות בחורבה,\u0004 שאם היתה חורבה משותפת לשתי חצירות, אין אחד יכול לבטל את רשותו בחורבה לגבי חבירו. שלא תקנו חכמים ביטול אלא בחצר שהיא עיקר צורך השימוש.","\u0003ואמרת לן עלה\u0004 \u0005[לנו עליה]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל אין ביטול רשות מחצר לחצר, לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 כשהיו \u0003שתי חצירות\u0004 זו בצד זו, \u0003ופתח אחד ביניהן. אבל\u0004 אם היו החצירות \u0003זו לפנים מזו, מתוך שאוסרין זה על זה — מבטלין\u0004 רשותן זה לזה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף בתמיהה: \u0003אנא אמינא משמיה דשמואל הכי\u0004 \u0005[אני אמרתי משמו של שמואל כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: אין לנו\u0004 להקל בדיני \u0003עירובין אלא כלשון משנתנו\u0004 וכדיוק לשונה, והרי במשנה נאמר \u0003\"אנשי חצר\"\u0004 אחת מבטלים רשותם \u0003ולא אנשי חצירות,\u0004 משמע שאין דין ביטול רשות בשתי חצירות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003כי אמרת לן\u0004 \u0005[כאשר אמרת לנו]\u0006 הלכה זו משם שמואל \u0003אין לנו בעירובין אלא כלשון משנתנו — אהא אמרת לן\u0004 \u0005[על\u0006 משנה \u0005זו אמרת לנו]\u0006 שנאמר בה: \u0003שהמבוי לחצירות כחצר לבתים,\u0004 ודייק שמואל מלשון זו שאם אין לפחות שתי חצירות במבוי, אין להתירו בלחי וקורה, כפי שהחצר אינה ניתרת בעירוב אלא אם יש בה שתי דירות.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של ענין שהוזכר קודם לכן, \u0003אמר שמואל: אין ביטול רשות מחצר לחצר ואין ביטול רשות בחורבה. ו\u0004אילו \u0003ר' יוחנן אמר: יש ביטול רשות מחצר לחצר, ויש ביטול רשות בחורבה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 לפרש שנחלקו בשני הנושאים ואין ללמוד דבר מדבר, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 שאין ביטול רשות \u0003מחצר לחצר\u0004 בלבד, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003שמואל\u0004 שאין ביטול, \u0003משום דהא תשמישתא\u0004 \u0005[שזה שימוש]\u0006 \u0003לחוד, והא תשמישתא\u0004 \u0005[וזה שימוש]\u0006 \u0003לחוד,\u0004 שהרי בני כל חצר משתמשים לעצמם בחצר שלהם. \u0003אבל\u0004 ב\u0003חורבה, תשמישתא חדא לתרוייהו\u0004 \u0005[שימוש אחד לשניהם],\u0006 שמשותפת היא ושני השכנים משתמשים בה. \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מודי ליה\u0004 \u0005[מודה\u0006 הוא \u0005לו]\u0006 \u0003לר' יוחנן.\u0004","ולהיפך, \u0003ו\u0004אילו \u0003כי אתמר בהא\u0004 \u0005[כאשר היה נאמר\u0006 רק \u0005בזה],\u0006 בענין חורבה, הייתי אומר \u0003בהא קאמר\u0004 \u0005[בזו\u0006 בלבד \u0005אמר]\u0006 \u0003ר' יוחנן, אבל בהך מודי ליה\u0004 \u0005[בההיא,\u0006 מחצר לחצר, \u0005מודה לו]\u0006 \u0003לשמואל\u0004 שאין מבטלים מחצר לחצר, על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שתיהן.","\u0003אמר אביי: הא\u0004 \u0005[זה]\u0006 ש\u0003אמר שמואל אין ביטול רשות מחצר לחצר לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא בשתי חצירות\u0004 הסמוכות זו לזו \u0003ופתח אחד ביניהן, אבל\u0004 היו \u0003שתי חצירות זו לפנים מזו, מתוך שאוסרין\u0004 אלו על אלו אף \u0003מבטלין\u0004 לאלו.","\u0003רבא אמר: אפילו שתי חצירות זו לפנים מזו\u0004 אין להן דין קבוע, \u0003פעמים מבטלין, ופעמים אין מבטלין. כיצד\u0004 פרטי הלכה זו? אם \u0003נתנו\u0004 בני שתי החצירות את \u0003עירובן ב\u0004חצר ה\u0003חיצונה, ושכח\u0004 אדם \u0003אחד, בין מן\u0004 הדרים בחצר \u0003הפנימית ובין מן\u0004 הדרים בחצר \u0003החיצונה, ולא עירב\u0004 עם האחרים — \u0003שתיהן אסורות,\u0004 שהוא אוסר על כולן להשתמש בחיצונה. שכיון שהעירוב, אף של הפנימית, מצוי כעת בחצר החיצונה, חצר זו אסורה בלא עירוב משום דריסת רגלם של בני הפנימית, נמצא שאין עירוב כלל, אף לא לבני החצר החיצונה.","אולם אם \u0003נתנו עירובן ב\u0004חצר ה\u0003פנימית,\u0004 יש לחלק, אם \u0003שכח אחד מן הפנימית ולא עירב\u0004 — \u0003שתיהן אסורות,\u0004 כי אז אין היתר לחצר הפנימית כשלעצמה בשל האחד שלא עירב. וכיון שהחצר הפנימית אסורה, הריהי אוסרת גם בחצר החיצונית שעוברים בה בני הפנימית.","אולם אם \u0003שכח אחד מן החיצונה ולא עירב — פנימית מותרת וחיצונה אסורה,\u0004 שהרי בני הפנימית יש להם עירוב. שכל בני חצר זו עירבו יחד, וחצרם שלהם מותרת בטלטול, ואין בני החצר החיצונה אוסרים עליהם, כי אין הם חייבים להכנס לחצר הפנימית ובני הפנימית יכולים לנעול דלת בתיהם. ומעתה מבארים מדוע אין אף תקנה לבני חצירות אלה על ידי ביטול רשות.","ומפרטים: אם \u0003נתנו עירובן ב\u0004חצר ה\u0003חיצונה ושכח אחד, בין מן הפנימית ובין מן החיצונה, ולא עירב — שתיהן אסורות,\u0004 ואין אותו ששכח יכול לבטל. כי \u0003האי בר פנימית, למאן ניבטיל\u0004 \u0005[אותו\u0006 השוכח \u0005בן\u0006 חצר \u0005פנימית, למי יבטל\u0006 את רשותו\u0005]?\u0006 \u0003ליבטיל\u0004 \u0005[\u0006אם \u0005יבטל]\u0006 \u0003לבני פנימית — ליתא לעירובייהו גבייהו\u0004 \u0005[אין עירובם אצלם]\u0006 אלא בחצר החיצונה הוא, ואם יבטלו רשותם, נמצא שאין להם עירוב כלל, ואוסרים האחת על חבירתה. \u0003לבטיל\u0004 \u0005[שיבטל]\u0006 \u0003לבני חיצונה —\u0004 הלא קבע שמואל ש\u0003אין ביטול רשות מחצר לחצר!\u0004","וכן: \u0003האי בר חיצונה למאן נבטיל\u0004 \u0005[אותו בן חיצונה\u0006 ששכח, \u0005למי יבטל],\u0006 \u0003ליבטיל\u0004 \u0005[שיבטל]\u0006 \u0003לבני\u0004 החצר ה\u0003חיצונה — איכא\u0004 \u0005[יש]\u0006 חצר \u0003פנימית דאסרה עלייהו\u0004 \u0005[שאוסרת עליהם].\u0006 \u0003לבטיל\u0004 \u0005[שיבטל]\u0006 \u0003לבני פנימית —\u0004 הלא \u0003אין ביטול רשות מחצר לחצר,\u0004 ולכן אין להם תקנה בביטול.","ואם \u0003נתנו עירובן בפנימית, ושכח אחד מן הפנימית ולא עירב — שתיהן אסורות.\u0004 וטעמו של דבר: \u0003האי בר\u0004 \u0005[אותו בן]\u0006 החצר ה\u0003פנימית למאן נבטיל\u0004 \u0005[למי יבטל]?\u0006 \u0003ליבטיל\u0004 \u0005[שיבטל]\u0006 \u0003לבני הפנימית —\u0004 הלא \u0003איכא\u0004 \u0005[יש]\u0006 חצר \u0003חיצונה דאסרה עלייהו\u0004 \u0005[שאוסרת עליהם],\u0006 כי הרי העירוב שבין החצירות בעל תוקף הוא ביסודו, ובני החצר החיצונית יכולים להיכנס על ידו גם בחצר זו. \u0003ליבטיל\u0004 \u0005[שיבטל]\u0006 \u0003לבני חיצונה,\u0004 הרי לדעת שמואל \u0003אין ביטול רשות מחצר לחצר,\u0004 שהרי כיון שהפנימית אסורה, אוסרת היא אף את החיצונה."],["\u0003שכח אחד מן החיצונה ולא עירב — ודאי\u0004 חצר \u0003פנימית מותרת, דאחדא דשא\u0004 \u0005[שמחזיקה\u0006 וסוגרת \u0005את הדלת]\u0006 ואינה נותנת לבני החיצונה להיכנס, \u0003ומשתמשא\u0004 [\u0005ומשתמשת]\u0006 רק היא בחצרה, \u0003וחיצונה אסורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: וכי\u0004 \u0005[וכאשר]\u0006 \u0003שכח אחד מהפנימית ולא עירב אמאי\u0004 \u0005[מדוע]\u0006 \u0003שתיהן אסורות, לבטיל בר\u0004 \u0005[שיבטל בן]\u0006 ה\u0003פנימית\u0004 את רשותו \u0003לבני\u0004 החצר ה\u0003פנימית,\u0004 והחצר החיצונה הרי עירבה עם הפנימית \u0003ותיתי חיצונה ותשתרי בהדייהו\u0004 \u0005[תבוא\u0006 החצר \u0005החיצונה ותהיה מותרת\u0006 יחד \u0005עמם]!\u0006","אמר לו רבא, \u0003כמאן\u0004 \u0005[כמי]\u0006 אומר אתה פתרון זה — \u0003כ\u0004שיטת \u0003ר' אליעזר דאמר: אינו צריך לבטל רשות לכל אחד ואחד,\u0004 ודיו שמבטל רשותו לאחד ושוב אין לו רשות לעצמו ואינו אוסר, ולשיטה זו יכול בן החצר הפנימית לבטל רשותו לבני חצרו שלו בלבד אף על פי שהשתתפו עמם בני החיצונה, אולם \u0003כי קאמינא לרבנן דאמרי\u0004 \u0005[כאשר אמרתי\u0006 אני היה זה \u0005לשיטת חכמים שאומרים]:\u0006 \u0003צריך לבטל לכל אחד ואחד!\u0004 וכיון שצריך לבטל גם לבני החיצונה, ואינו יכול, לפי שאין מבטלים מחצר לחצר, שוב אין תקנה לחצירות אלה.","מסופר: \u0003רב חסדא ורב ששת כי פגעי בהדי הדדי\u0004 \u0005[כאשר היו פוגשים זה את זה]\u0006 \u0003רב חסדא מרתען שפוותיה ממתנייתא\u0004 \u0005[היו שפתיו מרתתות ממשניות]\u0006 \u0003רב ששת,\u0004 שהיה רב ששת בקי גדול ורב חסדא היה מלא יראת כבוד מפניו בשל כך. וכן \u0003רב ששת מרתע כוליה גופיה מפלפוליה\u0004 \u0005[היה מזדעזע כל גופו מחריפותו]\u0006 של \u0003רב חסדא\u0004 שהיה מעמיק וחריף ביותר.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב חסדא מרב ששת\u0004 אם היו \u0003שני בתים משני צידי רשות הרבים\u0004 שמתוך שרשות הרבים מפסיקה אין כל קשר בין הבתים \u0003ובאו גוים והקיפום מחיצה בשבת מהו?\u0004 שהרי על ידי המחיצה בטלו הגוים את רשות הרבים שבאמצע ועשאוה כחצר לבתים. והשאלה היא: אם ביטל האחד את רשותו לאחר, האם מותר להתיר לטלטל מבית לבית?","ומפרטים: \u0003אליבא דמאן דאמר\u0004 \u0005[לפי שיטת מי שאמר]\u0006 \u0003אין ביטול רשות מחצר לחצר, לא תיבעי\u0004 \u0005[תשאל]\u0006 \u0003לך\u0004 שאלה זו כלל וודאי שהטלטול אסור. \u0003השתא דאי בעו לערובי מאתמול מצו מערבי\u0004 \u0005[עכשיו אילו היו רוצים לערב מאתמול היו יכולים לערב]\u0006 כגון שתי חצירות שיש פתח ביניהן \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003\"אין ביטול רשות מחצר לחצר\" הכא\u0004 \u0005[כאן]\u0006 בענין בתים משני עברי רשות הרבים \u0003דאי בעו לערובי מאתמול לא מצו מערבי\u0004 \u0005[שאם היו רוצים לערב מאתמול לא היו יכולים לערב]\u0006 \u0003לא כל שכן\u0004 שאין מבטלים?!","\u0003כי תיבעי\u0004 \u0005[כאשר תשאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטת מי שאמר]\u0006 \u0003\"יש ביטול רשות מחצר לחצר\"\u0004 וצדדי השאלה: \u0003התם דאי בעו לערובי מאתמול מצו מערבי — בטולי נמי מצי מבטל\u0004 \u0005[שם שאם היו רוצים לערב מאתמול היו יכולים לערב —\u0006 \u0005לבטל גם כן יכולים לבטל]\u0006 \u0003אבל הכא דלא מצו מערבי\u0004 \u0005[כאן שאין יכולים לערב]\u0006 \u0003מאתמול בטולי נמי לא מצי מבטל\u0004 \u0005[ביטול גם כן אינו יכול לבטל]\u0006","\u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה]\u0006 שמאחר שלפי המצב עתה אפשר לבטל אין דנים במה שהיה קודם לכן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003אין מבטלין.\u0004","ועוד שאלו שאלה דומה: אם היו שני ישראלים וגוי בחצר, ולא עשו כל תיקון, והיתה החצר אסורה עליהם, ו\u0003מת גוי בשבת מהו?\u0004 שכיון שמת הסתלקה רשותו, ויש לעיין האם יכול עתה אחד מהם לבטל רשותו לגבי חבירו ויוכלו לטלטל בחצר.","ומפרטים: \u0003אליבא דמאן דאמר\u0004 \u0005[לפי שיטת מי שאומר]\u0006 \u0003שוכרין\u0004 מן הגוי הבא בשבת עצמה \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו כי \u0003השתא תרתי עבדינן\u0004 \u0005[עכשיו,\u0006 הרי \u0005שתיים עושים]\u0006 לשכור וגם לבטל, שהרי גם שוכרים מן הגוי וגם מבטלים. \u0003חדא מיבעיא\u0004 \u0005[אחת נצרכה\u0006 לומר\u0005]\u0006 וודאי מותר לבטל בתוך השבת.","\u0003אלא כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לפי שיטת מי שאומר]\u0006 \u0003אין שוכרין.\u0004 וצדדי השאלה: \u0003תרתי הוא דלא עבדינן\u0004 \u0005[שתים הוא שאין אנו עושים]\u0006 לשכור וגם לבטל, \u0003הא חדא\u0004 \u0005[אבל אחת] —\u0006 \u0003עבדינן [\u0004\u0005עושין אנו],\u0006 \u0003או דילמא לא שנא\u0004 \u0005[שמא, אינו שונה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת \u0003אני אומר: מבטלין, ו\u0004רב \u0003המנונא אמר: אין מבטלין.\u0004","\u0003אמר רב יהודה אמר שמואל: גוי\u0004 שדר בחצר הפתוחה למבוי שגרים בו ישראלים רבים, \u0003שיש לו\u0004 לגוי עוד \u0003פתח\u0004 אפילו הוא \u0003ארבעה על ארבעה\u0004 טפחים בלבד, \u0003פתוח\u0004 מן הצד האחר של החצר \u0003לבקעה\u0004 (לשדה). \u0003אפילו מכניס ומוציא גמלים וקרונות כל היום כולו דרך מבוי,\u0004 והכל רואים שעיקר שימושו במבוי זה, מכל מקום \u0003אין אוסר על בני המבוי.\u0004 שאינו נקרא כשותף להם במבוי זה, אלא שפתחו האמיתי לצד הבקעה הוא.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אומרים אנו כך שפתחו הקטן לבקעה נחשב פתח עיקרי עבורו \u0003בפיתחא דמיחד ליה, בההיא ניחא ליה\u0004 \u0005[בפתח המיוחד לו, בו נוח לו].\u0006 ואף שהפתח המיוחד קטן הוא, מכל מקום רואה בעל הבית פתח זה כפתחו העיקרי, ובמבוי משתמש רק לנוחיות בלבד.","על סמך הנחה זו \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם היה פתח הגוי \u0003פתוח לקרפף\u0004 (בקעה מגודרת) ולא במישרין לבקעה, \u0003מהו?\u0004 האם נאמר שמשמש פתח זה כפתח ראשי או לא? \u0003אמר רב נחמן בר אמי משמיה דאולפנא\u0004 \u0005[בשם המסורת]\u0006 שנמסרה לו מרבותיו:"],["\u0003אפילו פתוח לקרפף,\u0004 הרי הוא נחשב כפתחו העיקרי, ואין שימושו במבוי שימוש עיקרי לו.","\u0003רבה ורב יוסף דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 שיש לחלק בהלכה זו בין בעלי החצירות; \u0003גוי\u0004 אם היה הקרפף מאחורי חצרו רק בשיעור \u0003בית סאתים\u0004 — \u0003אוסר\u0004 על בני המבוי, כי קרפף כזה אין שטחו מספיק להוציא כל צרכיו לתוכו, ולכן פתחו העיקרי הוא מצד המבוי. ואם היה \u0003יותר מבית סאתים — אינו אוסר\u0004 על בני המבוי, משום שקרפף כזה ניתן להשתמש בו די צרכו, וזהו אם כן פתחו העיקרי.","\u0003ו\u0004אילו \u0003ישראל\u0004 שהיה לו קרפף \u0003בית סאתים — אינו אוסר\u0004 על בני המבוי, אף אם לא עירב עימם, כי מאחר שקרפף עד בית סאתים מותר לטלטל בו בשבת, הריהו מטלטל אליו ולא דרך המבוי שהוא אסור בו, ונוח לו לטלטל במקום המותר שהוא כולו שלו.","ואולם אם היה הקרפף \u0003יותר מבית סאתים,\u0004 שאסור לטלטל בו, ולכן אינו מטלטל אלא דרך המבוי, ונמצא אם כן \u0003אוסר\u0004 על בני המבוי, כל עוד לא עירב עימם.","בענין זה \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא בר חקלאי מרב הונא:\u0004 אם היה פתח של גוי \u0003פתוח לקרפף מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי אמרו בית סאתים — אוסר, יותר מבית סאתים\u0004 — \u0003אינו אוסר.\u0004","\u0003אמר עולא אמר ר' יוחנן: קרפף יותר מבית סאתים שלא הוקף לדירה, ואפילו\u0004 היה שטחו בית \u0003כור ואפילו\u0004 בית \u0003כוריים — הזורק\u0004 בשוגג חפץ \u0003לתוכו\u0004 מרשות הרבים \u0003חייב\u0004 חטאת, כמכניס לרשות היחיד. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 חייב הוא, כי מחיצת הקרפף \u0003מחיצה היא,\u0004 ומדין תורה הריהו כרשות היחיד, \u0003אלא שמחוסרת דיורין.\u0004 ולכן לא התירו חכמים לטלטל בה כברשות היחיד גמורה.","על כך \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בר חיננא\u0004 מברייתא: \u0003סלע שבים\u0004 שהיה \u0003גבוה עשרה\u0004 טפחים \u0003ורוחב ארבעה — אין מטלטלים לא מן תוכו לים ולא מן הים לתוכו.\u0004 שסלע זה דינו כרשות היחיד, והים הוא כרמלית, ואין מטלטלים מרשות היחיד לכרמלית. \u0003פחות מכאן\u0004 בגובהו או ברוחבו שאינו עוד כרשות היחיד — \u0003מטלטלין. עד כמה\u0004 יהא שטח הסלע — \u0003עד בית סאתים.\u0004","ומבררים: \u0003אהייא\u0004 \u0005[על איזה]\u0006 מן הדינים הקודמים מתייחס הביטוי \"עד בית סאתיים\"? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על הסוף]\u0006 שמדובר בסלע שהיה גובהו פחות מעשרה — \u0003בית סאתים, טפי\u0004 \u0005[יותר]\u0006 \u0003לא? והא\u0004 \u0005[והרי]\u0006 \u0003מכרמלית לכרמלית קא מטלטל\u0004 \u0005[הוא מטלטל]\u0006 ובודאי מותר לטלטל מכרמלית לכרמלית.","\u0003אלא לאו ארישא\u0004 \u0005[האם לא\u0006 מדובר \u0005על ראשה\u0006 של הברייתא\u0005],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 כך יש להבין את דבריו: \u0003סלע שבים, גבוה עשרה\u0004 טפחים \u0003ורוחב ארבעה — אין מטלטלין לא מתוכו לים ולא מן הים לתוכו,\u0004 שכן דינו כרשות היחיד. \u0003ועד כמה\u0004 נאמר איסור זה — \u0003עד בית סאתים, הא\u0004 \u0005[הרי]\u0006 אם היה הסלע \u0003יתר\u0004 בשטחו \u0003מבית סאתים — מטלטלין. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003כרמלית היא,\u0004 ומשמע שבדין זה נחשב המקום לכרמלית, לא רק לחומרה אלא גם להקל, והוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' יוחנן!\u0004","\u0003אמר רבא: מאן דלא ידע תרוצי מתנייתא\u0004 \u0005[מי שאינו יודע ליישב את המשניות]\u0006 \u0003תיובתא מותיב\u0004 \u0005[קושיות מקשה]\u0006 \u0003לר' יוחנן\u0004 שהוא מגדולי החכמים שבדור! ואת הברייתא יש להבין כך: \u0003לעולם\u0004 מתייחסת ההוספה \u0003ארישא\u0004 \u0005[על תחילת\u0006 הדברים\u0005],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 יש לדייק כך מן הדברים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בתוכו\u0004 בתוך הסלע — \u0003מטלטלין,\u0004 שאסור לטלטל מן הסלע לים, אבל הוא עצמו רשות היחיד ומטלטלין בו. ואולם \u0003עד כמה\u0004 יהא שטחו ועדיין יהא מותר לטלטל בו — \u0003עד בית סאתים.\u0004","\u0003רב אשי אמר\u0004 כי את הברייתא אפשר להסביר בצורה אחרת, ובכל זאת לא תהא סתירה לדברי ר' יוחנן: \u0003לעולם\u0004 מוסבת ההוספה \u0003ארישא\u0004 \u0005[על תחילת\u0006 המשנה\u0005],\u0006 וכדברי רב הונא בר חיננא, אלא שאין להוציא מסקנה כללית לגבי דין קרפף, שכן \u0003הן אמרו והן אמרו.\u0004 כי החכמים הם שאמרו דין יסודי זה להחמיר, והם עצמם שאמרו להקל.","כיצד, \u0003הן אמרו\u0004 וקבעו תקנה כי \u0003קרפף יתר מבית סאתים שלא הוקף לדירה, אין מטלטלין בו אלא בארבע אמות,\u0004 שכן דינו לענין זה ככרמלית. \u0003ו\u0004אף \u0003הן אמרו: אין מטלטלין מרשות היחיד לכרמלית.\u0004 ושני הדברים בגדר גזירות חכמים הם.","וכך צרפו חכמים את הדברים: \u0003בית סאתים דשרי לטלטולי בכוליה\u0004 \u0005[שמותר לטלטל בכולו],\u0006 \u0003אסרי רבנן לטלטולי\u0004 \u0005[אסרו חכמים לטלטל]\u0006 \u0003לא מן הים לתוכו ולא מתוכו לים. מאי טעמא\u0004 \u0005[מה הטעם],\u0006 \u0003רשות היחיד גמורה היא,\u0004 ולא התירו לטלטל מרשות היחיד לכרמלית.","ואולם אם היה \u0003יתר מבית סאתים,\u0004 ש\u0003אסור לטלטולי בכוליה\u0004[לטלטל בכולו] מגזירת חכמים, \u0003שרו רבנן\u0004 \u0005[התירו חכמים]\u0006 \u0003לטלטולי\u0004 \u0005[לטלטל]\u0006 \u0003מתוכו לים ומן הים לתוכו.\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003דלמא אמרי\u0004 \u0005[שמא\u0006 יבואו אנשים \u0005לומר]:\u0006 \u0003רשות היחיד גמורה היא, ואתי לטלטולי בכוליה\u0004 \u0005[ויבואו לטלטל בכולה].\u0006 כי אם יאסרו לטלטל מתוכו לים, יחשבו הכל שדינו כרשות היחיד גמורה, ולכן אף יבואו לטלטל בתוכו. וכיון שעיקרן של הגזירות הוא מדברי חכמים, אמרו חכמים עצמם להתיר טלטול מרשות היחיד לכרמלית, כדי שלא יעברו על גזרת חכמים האחרת שאין לטלטל בשטח הגדול מבית סאתיים. אבל אין להסיק מכאן כל מסקנה כללית.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 מדוע העדיפו לקיים גזרה זו דווקא? ומשיבים: כי הטלטול ב\u0003תוכו\u0004 של הסלע \u0003שכיח. מתוכו לים ומן הים לתוכו — לא שכיח,\u0004 לכן התירו חכמים טלטול זה שאינו שכיח, כדי לחזק גזירת טלטול בתוכו שהוא שכיח.","מסופר: \u0003ההוא ינוקא דאשתפיך חמימיה\u0004 \u0005[תינוק אחד שנשפכו\u0006 המים \u0005החמים]\u0006 שהכינו עבורו למילה ביום השבת. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבה: נייתו ליה חמימא מגו ביתאי\u0004 \u0005[שיביאו לו\u0006 מים \u0005חמים מתוך ביתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא לא ערבינן\u0004 \u0005[והרי לא עירבנו\u0006 בחצר\u0005]\u0006 ואסור לטלטל את המים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003נסמוך אשיתוף\u0004 \u0005[על שיתוף\u0006 המבואות\u0005]\u0006 שישמש אף במקום עירוב חצירות בדיעבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003הא לא שתפינן\u0004 \u0005[הרי לא נשתתפנו\u0006 \u0003במבוי\u0004\u0005]!\u0006 אמר לו רבה: אם כן, \u0003נימרו ליה\u0004 \u0005[שיאמר לו]\u0006 \u0003לגוי ליתי ליה\u0004 \u0005[שיביא לו],\u0006 אף שבדרך כלל אסרו לומר לגוי לעשות בשביל ישראל מלאכה שיש בה חילול שבת.","\u0003אמר אביי: בעי לאותביה למר, ולא שבקן\u0004 \u0005[רציתי להקשות לאדוני\u0006 לרבה, \u0005ולא הניחני]\u0006 \u0003רב יוסף\u0004 להקשות, ש\u0003אמר רב יוסף אמר רב כהנא: כי הוינן בי\u0004 \u0005[כאשר היינו בביתו]\u0006 של \u0003רב יהודה, הוה אמר לן\u0004 \u0005[היה אומר לנו]\u0006 כאשר יש בעיה בהלכה לפנינו, אם הדבר \u0003בדאורייתא\u0004 \u0005[מדברי תורה] —\u0006 \u0003קודם מותבינן תיובתא, והדר עבדינן\u0004 \u0005[מקשים קושיות, ואחר כך עושים אנו]\u0006 \u0003מעשה.\u0004 שאם מוצא מישהו מקום להקשות על המעשה, יש לו להקשות ויתברר הענין, ואחר כך יעשו מעשה. ואולם \u0003בדרבנן\u0004 \u0005[בדברי חכמים] —\u0006 \u0003קודם עבדינן\u0004 \u0005[עושים אנו]\u0006 \u0003מעשה, והדר מותבינן תיובתא\u0004 \u0005[ואחר כך מקשים קושיות].\u0006","\u0003לבתר הכי\u0004 \u0005[לאחר כך]\u0006 כאשר הביאו את המים \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: \u0003מאי בעית לאותביה למר\u0004 \u0005[מה רצית להקשות לאדוננו,\u0006 לרבה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הזאה\u0004 על טמא מת לטהרו בשבת אינה מלאכה האסורה מן התורה, אלא \u0003שבות\u0004 היא, כלומר גזירת חכמים שעשו סייג לשמירת השבת. \u0003ו\u0004אף \u0003אמירה לגוי\u0004 שיעשה מלאכה עבור ישראל \u0003שבות\u0004 היא."],["\u0003מה הזאה — שבות, ואינה דוחה את השבת,\u0004 אף לצורך מצוה. \u0003אף אמירה לגוי — שבות, ואינה דוחה את השבת.\u0004 וכיצד אמר רבה שיאמרו לגוי, והרי יעברו בכך על השבות?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003ו\u0004כי \u0003לא שני\u0004 \u0005[שונה]\u0006 \u0003לך בין שבות דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003מעשה לשבות דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003מעשה? דהא מר\u0004 \u0005[שהרי החכם\u0006 רבה\u0005]\u0006 \u0003לא אמר לגוי: זיל אחים\u0004 \u0005[לך חמם]\u0006 בשבת, אלא רק אמר לו להביא דבר לרשות אחרת, ושבות קלה היא.","כאשר סופר מעשה זה והדיון בו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנן לאביי: מבואה דאית ביה תרי גברי רברבי כרבנן\u0004 \u0005[מבוי שיש בו שני אנשים גדולים כחכמים,\u0006 כרבה ואביי\u0005],\u0006 היתכן ש\u0003לא ליהוי ביה\u0004 \u0005[יהא בו]\u0006 מלכתחילה \u0003לא עירוב ולא שיתוף?! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי נעביד\u0004 \u0005[מה נעשה]?\u0006 \u0003מר, לאו אורחיה\u0004 \u0005[רבינו,\u0006 רבה\u0005, אין\u0006 זו \u0005דרכו]\u0006 ללכת לחזר על בני המבוי ולגבות מהם את העירוב. \u0003אנא, טרידנא בגירסאי\u0004 \u0005[אני, טרוד בגירסתי]\u0006 ואין שעתי פנויה לגבות. \u0003אינהו, לא משגחי\u0004 \u0005[הם,\u0006 שאר בני המבוי\u0005, אינם משגיחים]\u0006 ולא עשו זאת.","\u0003ואי אקני להו פיתא בסלא\u0004 \u0005[ואם אקנה להם פת בסל]\u0006 לבני המבוי, ועל ידי כך אזכה אותם בשיתוף — \u0003כיון דאי בעו לה מינאי\u0004 \u0005[שאם ירצו אותה ממני],\u0006 \u0003ולא אפשר\u0004 לי \u0003ליתבה נהלייהו\u0004 \u0005[לתת אותה להם],\u0006 משום שהיה עני ופתו מועטה וצריכה לו לעצמו, הרי אז \u0003בטיל\u0004 \u0005[מבוטל]\u0006 ה\u0003שיתוף.\u0004","שכיון שאינו נותן, אין זה עירוב, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד מבני מבוי שביקש יין ושמן\u0004 מן השיתוף, \u0003ולא נתנו לו — בטל השתוף,\u0004 שהרי זה מוכיח שאין מחשיבים אותו באמת לשותף.","ושאל עוד: \u0003ונקני להו מר רביעתא דחלא בחביתא\u0004 \u0005[ושיקנה להם אדוני רביעית חומץ ב\u0006אחת \u0005החביות],\u0006 וכמות מועטה זו של חומץ יכול היה אף אביי לתת עבור כולם. אמר לו אביי: \u0003תניא\u0004 \u0005[\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אין משתתפין באוצר\u0004 (במחסן), כי לא ברור מה הוא החלק המדויק המופרש לצורך העירוב. וכן הדין אם כן לרביעית שאינה מסויימת בתוך החבית.","והקשה לו: \u0003והא תניא\u0004 \u0005[והרי שנינו,\u0006 בברייתא אחרת\u0005]\u0006 \u0003משתתפין! אמר רב אושעיא: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האומרת שאין משתתפין — כשיטת \u0003בית שמאי, הא\u0004 \u0005[זו]\u0006 המתירה — כשיטת \u0003בית הלל,\u0004 שנחלקו בבעיה זו של ברירה, אם אומרים שמועיל בירור שלאחר מעשה.","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה המת בבית, ולו\u0004 (לבית) \u0003פתחים הרבה — כולן טמאין.\u0004 משום שאין יודעים מאיזה פתח יוציאוהו, ואפשר שיוציאו את המת באחד מהפתחים הללו, ואז יטמא תוכו של פתח זה בטומאת האוהל. והלכה היא שמחמת חשש זה, הרי זה כאילו כבר יצא המת דרכו, וכבר נטמא מראש.","\u0003נפתח אחד מהן — הוא,\u0004 אותו פתח, \u0003טמא\u0004 שודאי יוציאו דרכו. \u0003וכולן טהורין.\u0004 ואם \u0003חישב\u0004 תחילה \u0003להוציאו באחד מהן, או בחלון שיש בו ארבעה על ארבעה — מציל על כל הפתחים כולם\u0004 שלא יטמאו.","\u0003בית שמאי אומרים: והוא שחישב\u0004 על כך \u0003עד שלא ימות המת.\u0004 שכאשר מת, ברור היה כבר באיזה פתח יוציאוהו. \u0003ובית הלל אומרים: אף משימות המת,\u0004 שאנו אומרים שהתברר הדבר למפרע שבפתח זה ייצא. וכמחלוקתם במת, אף בשיתוף שבאוצר נחלקו אם רביעית היין שנותנים לאחר מכן משמעה שהתברר למפרע שנשתתף בה כל הזמן.","מסופר: \u0003ההוא ינוקא דאישתפוך חמימיה\u0004 \u0005[תינוק אחד שנשפכו\u0006 מים \u0005חמים שלו]\u0006 שהיו מיועדים למילתו ביום השבת, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא\u0004 לשואלים: \u0003נישיילה לאימיה\u0004 \u0005[נשאל את אמו\u0006 של התינוק\u0005]\u0006 \u0003אי צריכא\u0004 \u0005[אם צריכה]\u0006 היתה למים חמים — \u0003נחים ליה\u0004 \u0005[יחמם לו\u0006 אותם\u0005]\u0006 \u0003גוי אגב אימיה\u0004 \u0005[אמו],\u0006 כיון שהיולדת בחזקת מסוכנת היא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא לרבא: אימיה קא אכלה תמרי\u0004 \u0005[אמו\u0006 בריאה עד שאפילו \u0005היא אוכלת תמרים]\u0006 ובודאי אינה מסוכנת שתצטרך לחמין. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימור, תונבא בעלמא הוא דנקט לה\u0004 \u0005[אמור, שמא בולמוס בלבד הוא שאחזה]\u0006 ולכן אינה מבחינה במה שאוכלת, אבל באמת עדיין חולה היא.","כעין זה מסופר: \u0003ההוא ינוקא דאשתפוך חמימיה\u0004 \u0005[תינוק אחד שנשפכו\u0006 המים \u0005החמים שלו]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא: פנו לי מאני מבי גברי\u0004 \u0005[כלי מחדר הגברים]\u0006 הפתוח לחצר \u0003לבי נשי\u0004 \u0005[לחדר הנשים]\u0006 שבחצרי, הפנימי לו, \u0003ואיזיל ואיתיב התם\u0004 \u0005[ואלך ואשב שם]\u0006 בחדר הנשים \u0003ואיבטיל להו\u0004 \u0005[ואבטל להם]\u0006 לבני חצר התינוק את \u0003הא\u0004 \u0005[זו]\u0006 ה\u0003חצר,\u0004 כדי שיוכלו להעביר את המים החמים מחצר לחצר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: אין ביטול רשות מחצר לחצר,\u0004 ואם כן כיצד יכול אתה לבטל רשותך משם?! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כר' יוחנן סבירא לי\u0004 \u0005[סבור אני]\u0006 ש\u0003אמר: יש ביטול מחצר לחצר,\u0004","\u0003ואי לא סבר לה מר\u0004 \u0005[ואם אין אדוני סבור]\u0006 \u0003כ\u0004שיטת \u0003שמואל\u0004"],["\u0003ניתיב מר בדוכתיה, וניבטיל לדידהו\u0004 \u0005[ישב אדוני במקומו, ויבטל\u0006 רשותו \u0005להם].\u0006 וכדי שיוכל אחר כך לטלטל, \u0003וניהדרו אינהו וניבטלו ליה למר\u0004 \u0005[ויחזרו הם ויבטלו לו לאדוני]\u0006 לאחר הבאת המים, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רב:\u0004 שנים הדרים בחצר אחת, ושכחו לערב, הריהם \u0003מבטלין\u0004 רשותם כל אחד לחבירו בזמן שהוא צריך להשתמש בה, \u0003וחוזרין ומבטלין\u0004 אותם שביטלו עבורם אותה רשות עצמה, בזמן שהראשונים צריכים לה.","ענה לו: \u0003אנא בהא\u0004 \u0005[אני ב\u0006דבר \u0005זה]\u0006 \u0003כשמואל סבירא לי\u0004 \u0005[סבור אני]\u0006 ש\u0003אמר: אין מבטלין וחוזרין ומבטלין.\u0004","הקשה רבינא: \u0003ולאו חד טעמא\u0004 \u0005[וכי לא טעם אחד]\u0006 \u0003הוא\u0004 לשתי ההלכות? שהרי \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אין מבטלין וחוזרין ומבטלין — לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003כיון דבטליה לרשותיה, אסתלק ליה מהכא\u0004 \u0005[שביטל את רשותו,\u0006 הרי הוא כמי ש\u0005הסתלק לו מכאן]\u0006 \u0003לגמרי, והוה ליה\u0004 \u0005[ונהיה לו]\u0006 \u0003כבן חצר אחרת, ו\u0004כדעת שמואל \u0003אין ביטול רשות מחצר לחצר.\u0004 ואם כן \u0003מר נמי, לא נבטיל\u0004 \u0005[אדוני גם כן, לא יבטל].\u0006 שאם מקבל אתה את שיטת שמואל לענין ביטול חוזר, צריך אתה לקבל שיטתו אף לענין ביטול רשות מחצר לחצר.","ענה לו רבא: לא זהו טעמו של שמואל בענין ביטול חוזר, אלא \u0003התם היינו טעמא: כי היכי דלא ליהוי מלתא דרבנן כחוכא ואטלולא\u0004 \u0005[שם זהו הטעם: כדי שלא יהיו דברי חכמים כצחוק וליצנות]\u0006 שעל ידי כך נראה שעושים כרצונם ומבטלין וחוזרים ומבטלים עד שאין לדבר כל משמעות.","כיון שהוזכרה הלכה זו דנים בה כעת. \u0003גופא\u0004 \u0005[לגוף\u0006 הענין\u0005]\u0006 \u0003רב אמר: מבטלין וחוזרין ומבטלין, ושמואל אמר: אין מבטלין וחוזרין ומבטלין.\u0004","ורוצים להציע \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003רב ושמואל בפלוגתא\u0004 \u0005[במחלוקת]\u0006 \u0003דרבנן ור' אליעזר קא מיפלגי\u0004 \u0005[הם חולקים].\u0006 שמצאנו שנחלקו ר' אליעזר וחכמים בדין אנשי חצר ששכח אחד מהם לערב, ולמחר ביטל רשותו, שלדברי ר' אליעזר (לעיל עירובין כו, א—ב) ביתו אסור לו להכניס ולהוציא ולאנשי החצר מותר, וחכמים סבורים (להלן עירובין סט,ב) כי אף להם אסור.","ש\u0003רב אמר כ\u0004שיטת \u0003רבנן\u0004 שדעתם שאף המבטל רשות חצירו לא ביטל רשות ביתו ולא הסתלק לגמרי, ולכן אפשר לחזור ולבטל לו. \u0003ושמואל\u0004 ש\u0003אמר כר' אליעזר\u0004 שהריהו כמסולק מן החצר, ולכן אי אפשר לחזור לבטל לו רשות, שהרי אינו נחשב כדר שם.","ודוחים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003רב, אנא דאמרי\u0004 \u0005[אני\u0006 מה \u0005שאמרתי]\u0006 \u0003אפילו לר' אליעזר\u0004 אמרתי, וכך אפשר לפרש: \u0003עד כאן לא\u0004 שמענו ש\u0003אמר ר' אליעזר התם\u0004 \u0005[שם]\u0006 ש\u0003המבטל רשות חצירו — רשות ביתו ביטל, משום\u0004 ש\u0003בבית בלא חצר לא דיירי אינשי\u0004 \u0005[דרים אנשים],\u0006 ולכן נראה שביטל הכל. \u0003אבל לענין איסתלוקי\u0004 \u0005[סילוק],\u0006 שיחשב כמסלק עצמו לגמרי מהחצר, ולא יוכלו לבטל אותה חזרה בשבילו, \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 וייתכן שבכך יודה לשיטת רב.","\u0003ושמואל אמר: אנא דאמרי\u0004 \u0005[אני שאמרתי\u0006 דברי\u0005],\u0006 \u0003אפילו כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו \u0003קאמרי רבנן התם\u0004 \u0005[שאמרו חכמים שם]\u0006 \u0003אלא\u0004 שקבעו \u0003מאי דבטיל — בטיל, ודלא בטיל — לא בטיל\u0004 \u0005[מה שבוטל —\u0006 \u0005בוטל, ו\u0006מה \u0005שלא בוטל —\u0006 \u0005לא בוטל]\u0006 \u0003אבל מאי דבטיל — מיהא איסתלק [אבל מה שביטל —\u0004 \u0005בכל אופן הסתלק]\u0006 \u0003לגמרי\u0004 מאותו דבר. והכל מודים שהמבטל רשותו כאילו אינו מצוי עוד באותו מקום.","\u0003אמר רב אחא בר חנא אמר רב ששת: כתנאי\u0004 \u0005[כתנאים,\u0006 שנחלקו בדבר\u0005]\u0006 ששנינו: \u0003מי שנתן רשותו\u0004 לשאר דיירי החצר, לאחר ששכח לערב מבעוד יום וביטלה להם, וחזר \u0003והוציא\u0004 אחר כך, \u0003בין בשוגג\u0004 ששכח שביטל ו\u0003בין במזיד — אוסר\u0004 שוב על כל בני החצר, שעל ידי כך הפקיע את הביטול, אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אם הוציא \u0003במזיד — אוסר,\u0004 אם \u0003בשוגג — אינו אוסר.\u0004","\u0003מאי לאו, בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר\u0005]\u0006 \u0003סבר\u0004 שכשמבטל, הריהו מסולק לגמרי מרשותו, ולכן \u0003מבטלין וחוזרין ומבטלין,\u0004 וכיון שהוציא הרי זה כמבטל את ביטולו. \u0003ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר\u0004 שכשמבטל, הריהו מסולק לגמרי מרשותו, ולכן \u0003אין מבטלין וחוזרין ומבטלין.\u0004","\u0003אמר רב אחא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא\u0004 בענין זה נחלקו, \u0003דכולי עלמא\u0004 \u0005[ש\u0006כן לדעת \u0005הכל]\u0006 לאחר שביטל, הריהו מסולק לגמרי, ולכן \u0003אין מבטלין וחוזרין ומבטלין. והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה אם \u0003קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד קמיפלגי\u0004 \u0005[הם נחלקו].\u0006 \u0003מר\u0004 \u0005[החכם\u0006 ר' מאיר\u0005]\u0006 \u0003סבר: קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד, ומר\u0004 \u0005[והחכם\u0006 ר' יהודה] \u0003סבר: לא קנסו שוגג אטו\u0004 \u0005[משום]\u0006","\u0003מזיד. רב אשי אמר\u0004 שבאמת \u0003רב ושמואל בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר ורבנן קא מיפלגי\u0004 \u0005[וחכמים הם חולקים],\u0006 ולא כפי שדחינו.","במשנתנו מסופר ש\u0003אמר רבן גמליאל מעשה בצדוקי אחד שהיה דר עמנו\u0004 בחצר, ודנו כיצד אפשר להשתמש בחצר כשהוא מצוי שם. ותחילה שואלים: \u0003צדוקי מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמו]?\u0006 הרי קודם דובר רק בגוי, ומשום מה בא רבן גמליאל לספר מעשה שהיה בצדוקי?","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003צדוקי הרי הוא כגוי, ורבן גמליאל אומר: צדוקי אינו כגוי. ואמר רבן גמליאל: מעשה בצדוקי אחד שהיה דר עמנו במבוי בירושלים\u0004 וביטל לנו רשותו, \u0003ואמר לנו אבא: מהרו והוציאו את הכלים למבוי\u0004 כדי להחזיק בו, שלא יוכל הצדוקי לחזור בו מביטולו \u0003עד שלא יוציא\u0004 כליו ויחזור בו מביטולו, \u0003ויאסר עליכם.\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שכך יש להבין את הדבר, שיש בו מחלוקת תנאים: \u0003הדר עם גוי, צדוקי וביתוסי, הרי אלו אוסרין עליו. רבן גמליאל אומר: צדוקי וביתוסי אינן אוסרין. ומעשה בצדוקי אחד שהיה דר עם רבן גמליאל במבוי\u0004 אחד \u0003בירושלים, ואמר להן רבן גמליאל לבניו: בני, מהרו והוציאו מה שאתם מוציאין והכניסו מה שאתם מכניסין, עד שלא יוציא התועב\u0004 (המתועב) \u0003הזה\u0004 את כליו ויחזור בו מביטולו, \u0003ויאסר עליכם, שהרי ביטל רשותו לכם,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר: בלשון אחרת\u0004 אמר: \u0003מהרו ועשו צורכיכם במבוי\u0004 מבעוד יום, \u0003עד שלא תחשך ויאסר עליכם.\u0004 ומעתה מעיינים בברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הוציאו מה שאתם מוציאין, והכניסו מה שאתם מכניסין, עד שלא יוציא התועב הזה ויאסר עליכם.\u0004 ושואלים: האם אפשר לדייק בלשון, \u0003למימרא\u0004 \u0005[האם לומר\u0006 מכאן\u0005]\u0006 \u0003דכי מפקי אינהו, והדר מפיק איהו לא אסר\u0004 \u0005[שאם מוציאים הם\u0006 חפצים, ואחר כך \u0005יחזור ויוציא הוא\u0006 ביום השבת, \u0005לא יאסור\u0006 עליהם\u0005]?!\u0006"],["\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 \u0003במשנה\u0004\u0005]\u0006 \u0003מי שנתן רשותו והוציא, בין בשוגג בין במזיד — אוסר, דברי ר' מאיר.\u0004 משמע שגם אם הוציא אחר כך, פקע ביטול הרשות! ודבריו אלו סותרים את מה שאמר בענין הצדוקי.","\u0003אמר רב יוסף: אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 שאמר ר' מאיר: \u0003אינו אוסר. אביי אמר: לא קשיא\u0004 \u0005[אינו קשה],\u0006 ואפשר ליישב את הסתירה בדברי ר' מאיר כך: \u0003כאן\u0004 בצדוקי שאינו יכול לבטל ביטולו — מדובר \u0003שהחזיקו בני מבוי במבוי\u0004 קודם שהוציא, \u0003כאן — שלא החזיקו בני מבוי במבוי.\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 \u0003בברייתא\u0004\u0005]:\u0006 מי שלא עירב, אם \u0003עד שלא נתן\u0004 (ביטל) \u0003רשותו, הוציא בין בשוגג בין במזיד — יכול לבטל\u0004 אחר כך, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: אם הוציא בשוגג — יכול לבטל, במזיד — אינו יכול לבטל,\u0004 שהמחלל שבת במזיד ובפרהסיה דינו כגוי.","ואולם \u0003מי\u0004 שכבר \u0003נתן\u0004 (ביטל) \u0003רשותו והוציא\u0004 אחר כך, \u0003בין בשוגג בין במזיד — אוסר,\u0004 שפקע ביטול רשותו, \u0003דברי ר' מאיר. ר' יהודה אומר: במזיד — אוסר, בשוגג — אינו אוסר. במה דברים\u0004 (דבריו של ר' מאיר) \u0003אמורים — בשלא החזיקו\u0004 עדיין \u0003בני מבוי במבוי, אבל\u0004 אם כבר \u0003החזיקו בני מבוי במבוי,\u0004 והוציא \u0003בין בשוגג ובין במזיד — אינו אוסר.\u0004","\u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר בלשון אחרת: מהרו ועשו צורכיכם במבוי עד שלא תחשך ויאסר עליכם. אלמא\u0004 \u0005[מכאן]\u0006 שהצדוקי כ\u0003גוי הוא,\u0004 שאין ביטולו מועיל. \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"עד שלא יוציא\" תנן\u0004 \u0005[שנינו]!\u0006 משמע שרק עד אז יוכלו להשתמש במבוי, ומכאן שביטולו מכל מקום ביטול הוא!","ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 \u0003\"עד שלא יוציא היום\",\u0004 כלומר עד שלא יגמר היום הששי. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן\u0004 ששנינו במשנה שהצדוקי מבטל — מדובר \u0003במומר לחלל שבתות בצנעא. כאן\u0004 בדברי ר' יהודה — \u0003במומר לחלל שבתות בפרהסיא,\u0004 שהוא כגוי גמור, ולכן אינו יכול לבטל.","\u0003ומעירים: כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו]:\u0006 \u0003מומר וגילוי פנים — הרי זה אינו מבטל רשות.\u0004 ולפני עצם הדיון תוהים על הלשון \u0003\"גילוי פנים\",\u0004 כלומר מחוצף העושה דברים בגלוי בניגוד לתורה, האם \u0003מומר הוי\u0004 \u0005[הוא],\u0006 ומדוע נאמרו הדברים יחד?","\u0003אלא\u0004 יש לתקן את הלשון כך: \u0003מומר בגילוי פנים,\u0004 שהוא מומר המראה את סטייתו מהתורה בפרהסיא — \u0003אינו יכול לבטל רשות, כמאן\u0004 \u0005[כמי\u0006 הולכת שיטה זו\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה.\u0004","ומסופר: \u0003ההוא דנפק בחומרתא דמדושא\u0004 \u0005[\u0006אדם \u0005אחד שיצא בטבעת אלמוג]\u0006 שאסור לטלטלה ברשות הרבים בשבת. \u0003כיון דחזייה\u0004 \u0005[שראה]\u0006 את \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא],\u0006 \u0003כסייה\u0004 \u0005[כיסה אותה].\u0006 שאף שחילל שבת, מכל מקום לא רצה להראות זאת בפני ר' יהודה נשיאה. \u0003אמר\u0004 ר' יהודה נשיאה: \u0003כגון זה\u0004 (אדם מסוג זה) הנזהר מלחלל שבת בפרהסיא \u0003מבטל רשות\u0004 על פי שיטת \u0003ר' יהודה.\u0004","כיון שדובר במי שיצא מגבול תורת ישראל, \u0003אמר רב הונא: איזהו ישראל מומר — זה המחלל שבתות בפרהסיא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אומר אתה דבר זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר שאמר: חשוד לדבר אחד\u0004 כלומר, שיודעים שהוא עובר בענין אחד — \u0003חשוד לכל התורה כולה, אם כן, אפילו באחד מכל איסורין שבתורה נמי\u0004 \u0005[גם כן],\u0006 שגם אם עובר הוא על עבירה אחרת, אפילו אינה חמורה כחילול שבת הריהו כמומר.","\u0003אי כרבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים],\u0006 \u0003האמרי\u0004 \u0005[הרי אמרו]:\u0006 \u0003חשוד לדבר אחד — לא הוי\u0004 \u0005[אינו]\u0006 \u0003חשוד לכל התורה כולה,\u0004"],["\u0003עד דהוי\u0004 \u0005[שיהיה]\u0006 \u0003מומר לעבודה זרה,\u0004 וכל עוד איננו עובד עבודה זרה איננו נחשד לכול משום עבירה אחת שעובר.","\u0003אמר רב נחמן בר יצחק:\u0004 לא נאמרו דברי רב הונא לענין הגדרתו הכללית של מומר אלא לענין \u0003ליתן רשות ולבטל רשות\u0004 בדיני עירובין. \u0003וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בתוספתא\u0005]:\u0006 \u0003ישראל מומר,\u0004 אם היה \u0003משמר שבתו בשוק,\u0004 כלומר בפרהסיא — הרי הוא \u0003מבטל רשות\u0004 כישראל כשר. ואילו זה \u0003שאינו משמר שבתו בשוק — אינו מבטל רשות,\u0004 ששוב אינו נחשב לענין זה כישראל.","\u0003מפני שאמרו: ישראל נוטל רשות ונותן רשות\u0004 על ידי ביטול ואמירה בלבד. \u0003ובגוי\u0004 אינו כן, שאינו יכול להעביר ולבטל רשות \u0003עד שישכיר\u0004 ממש. \u0003כיצד? אומר לו\u0004 הישראל לחבירו: \u0003רשותי קנויה לך\u0004 או \u0003רשותי מבוטלת לך\u0004 — הרי \u0003קנה\u0004 רשות, \u0003ואין צריך לזכות\u0004 בקנין סודר.","\u0003רב אשי אמר:\u0004 דברי רב הונא לכל ענין נאמרו, ואם תשאל לפי מי פסק רב הונא, הרי זה כשיטת \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא הוא, דחמירא עליה\u0004 \u0005[שחמורה עליו\u0006, בעיניו\u0005]\u0006 \u0003שבת כעבודה זרה,\u0004 ולכן המחלל שבת הרי אף הוא כגוי ואינו יכול לבטל רשותו.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \"דבר אל בני ישראל ואמרת אליהם אדם כי יקריב מכם קרבן לה' מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\" (ויקרא א, ב-ג), ולמדנו: \u0003\"מכם\"\u0004 — למעט ש\u0003לא כולכם\u0004 מקריבים, \u0003פרט למומר. \"מכם\"\u0004 — הדגשה היא, וכוונתו לומר: \u0003בכם\u0004 בין בני ישראל \u0003חלקתי\u0004 בין מקיימי התורה הראויים להביא קרבן, ובין אלו שאינם ראויים, \u0003ולא באומות.\u0004 שבאומות, גם מי שאינו מקיים את המצוות השייכות לו, מותר לו להביא קרבן.","\u0003\"מן הבהמה\"\u0004 — נדרש: \u0003להביא\u0004 (לרבות, להוסיף) \u0003בני אדם הדומין לבהמה\u0004 בזלזולם במה שצריך אדם לעשות, כלומר הרשעים, וללמדנו שאף הם מקריבים קרבנות. \u0003מכאן אמרו\u0004 חכמים \u0003: מקבלין קרבנות\u0004 נדבה \u0003מפושעי ישראל, כדי שיחזרו בתשובה. חוץ מן המומר, והמנסך יין\u0004 לעבודה זרה, \u0003והמחלל שבתות בפרהסיא,\u0004 שמהם אין מקבלים קרבנות עד שיחזרו בתשובה שלמה.","ותוהים: \u0003הא גופא קשיא\u0004 \u0005[הרי היא עצמה,\u0006 ברייתא זו\u0005, קשה]:\u0006 \u0003אמרת\u0004 בתחילה, \u0003\"מכם\" — ולא כולכם, להוציא את המומר. והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003מקבלין קרבנות מפושעי ישראל!\u0004 ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 ויש לפרש כך: \u0003רישא\u0004 \u0005[בתחילה]\u0006 — מדובר \u0003במומר לכל התורה כולה,\u0004 שאין מקבלים קרבנותיו, \u0003מציעתא\u0004 \u0005[האמצע]\u0006 קטע זה שהזכרנו — \u0003במומר לדבר אחד\u0004 בלבד.","ומקשים: אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]\u0006 שנאמר בה: \u0003חוץ מן המומר והמנסך יין. האי מומר, היכי דמי\u0004 \u0005[מומר זה, כיצד הוא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר ב\u0003מומר לכל התורה — היינו רישא\u0004 \u0005[הרי זה\u0006 מה שנאמר ב\u0005תחילה].\u0006 אלא \u0003אי\u0004 \u0005[אם]\u0006 מדובר במומר \u0003לדבר אחד, קשיא מציעתא\u0004 \u0005[קשה האמצע],\u0006 שנאמר בו שממומר כזה מקבלים קרבנות.","\u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך\u0006 התכוון \u0005לומר]:\u0006 \u0003חוץ מן המומר לנסך ולחלל שבתות בפרהסיא\u0004 שפסול כמומר לכל התורה כולה. \u0003אלמא\u0004 \u0005[מכאן\u0006 נסיק\u0005]\u0006 כי \u0003עבודה זרה ושבת כי הדדי נינהו\u0004 \u0005[זה כמו זה הם],\u0006 משמע שיש תנא המחמיר במחלל שבת בפרהסיא כעובד עבודה זרה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003אנשי חצר ששכח אחד מהן ולא עירב\u0004 מבעוד יום עם האחרים, ולכן ביטל למחר את רשות חצירו להם ולא את רשות ביתו — \u0003ביתו אסור מלהכניס ומלהוציא\u0004 אל החצר ומן החצר, גם \u0003לו ו\u0004גם \u0003להם. ו\u0004אולם מן הבתים \u0003שלהם מותרין\u0004 להוציא לחצר ולהכניס לבית גם \u0003לו ו\u0004גם \u0003להם. נתנו לו רשותן,\u0004 שבטלו רשותם לגביו — \u0003הוא מותר, והן אסורין.\u0004","\u0003היו שנים\u0004 בין דרי החצר ששכחו ולא עירבו, וביטלו להם האחרים את רשותם — \u0003אוסרין זה על זה. שאחד נותן רשות ונוטל רשות, שנים\u0004 רק \u0003נותנין רשות ואין נוטלין רשות.\u0004 וכיון שלא עירבו, לא יתכן ששאר בני החצר יתנו להם רשות. וכיון שיש שנים האסורים, אוסרים הם זה על זה.","וכן שאלה כללית היא: \u0003מאימתי נותנין\u0004 (מבטלים) \u0003רשות?\u0004 נחלקו חכמים בדבר, \u0003בית שמאי אומרים: מבעוד יום, ובית הלל אומרים: משחשיכה.\u0004 ועוד אמרו: \u0003מי שנתן\u0004 (ביטל) \u0003רשותו\u0004 ואחר כך חזר \u0003והוציא, בין\u0004 שעשה זאת \u0003בשוגג ובין במזיד — הרי זה אוסר\u0004 על כל בני החצר, וביטל את מתן הרשות, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: במזיד — אוסר, בשוגג — אינו אוסר.\u0004","מתחילה מבררים את לשון המשנה. נאמר ש\"ביתו אסור מלהכניס ומלהוציא\" ונדייק: \u0003ביתו הוא\u0004 ש\u0003אסור, הא\u0004 \u0005[הרי]\u0006 חלקו היחסי בתוך \u0003חצירו — שריא\u0004 \u0005[מותרת]\u0006 לשאר בני החצר.","ונברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 \u0005היה הדבר];\u0006 \u0003אי דבטיל\u0004 \u0005[אם שביטל],\u0006 \u0003ביתו אמאי\u0004 \u0005[מדוע]\u0006 \u0003אסור. אי דלא בטיל\u0004 \u0005[אם שלא ביטל],\u0006 \u0003חצירו אמאי שריא\u0004 \u0005[מדוע מותרת]?\u0006 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה מיוחד \u0003כגון שביטל רשות חצירו\u0004 לאחרים, \u0003ולא ביטל רשות ביתו. וקא סברי רבנן\u0004 \u0005[וסבורים חכמים]:\u0006 \u0003המבטל רשות חצירו\u0004 — אף על פי כן \u0003רשות ביתו לא ביטל,\u0004 שמצוי \u0003דדייר איניש\u0004 \u0005[שדר אדם]\u0006 \u0003בבית בלא חצר.\u0004","ועוד מבררים: נאמר כי \u0003\"ושלהן מותר לו ולהן\",\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 מותר לו? ומשיבים: \u0003דהוי\u0004 \u0005[שהריהו]\u0006 כ\u0003אורח לגבייהו\u0004 \u0005[לגביהם]\u0006 והוא טפל להם, ומטלטל בשלהם.","במשנה שנינו: \u0003נתנו לו רשותן, הוא מותר והן אסורין.\u0004 ושואלים: \u0003ונהוי אינהו\u0004 \u0005[ושיהיו הם]\u0006 מבטלי הרשות \u0003לגביה\u0004 \u0005[לגביו]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003אורחין\u0004 (אורחים), ויטלטלו אף הם! ומשיבים: \u0003חד\u0004 \u0005[אחד]\u0006 \u0003לגבי חמשה — הוי\u0004 \u0005[הריהו]\u0006 \u0003אורח\u0004 ומתקבל הדבר על הדעת, אבל \u0003חמשה\u0004 ויותר \u0003לגבי חד\u0004 \u0005[אחד]\u0006 — \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003אורח,\u0004 ואין זו דרך העולם.","מלשון המשנה רוצים להסיק מסקנה נוספת; \u0003שמע מינה\u0004 \u0005[\u0006האם לא \u0005נלמד מכאן]\u0006 מסדר תיאור הדברים במשנה, כי \u0003מבטלין וחוזרין ומבטלין.\u0004 שקודם הוא מבטל להם, ומותר להם להשתמש, ואחר כך הם חוזרים ומבטלים לו, ואז מותר לו ולהם אסור!","ומשיבים שאין להוכיח מכאן, אלא \u0003הכי קאמר\u0004 \u0005[כך נאמר]:\u0006 \u0003נתנו לו רשותן מעיקרא\u0004 \u0005[מתחילה] —\u0006 \u0003הוא מותר והן אסורין,\u0004 שאין זה המשך לקטע הקודם אלא ענין בפני עצמו.","שנינו שאם \u0003היו שנים אוסרין זה על זה.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר ומה צורך להודיענו? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה שלאחר שביטלו האחרים את רשותם לשנים אלו, \u0003הדר חד מינייהו ובטיל ליה לחבריה\u0004 \u0005[חזר אחד מהם וביטל לו לחבירו],\u0006 \u0003מהו דתימא: לישתרי\u0004 \u0005[שתאמר: שיהא מותר],\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003כיון דבעידנא דבטיל לא הוה ליה שריותא בהאי\u0004 \u0005[שבזמן שבטל לא היה לו היתר באותה]\u0006 \u0003חצר,\u0004 למבטל לבד, שהרי הראשונים ביטלוה לשניהם יחד, אם כן אף הוא אינו יכול לבטל, ואין ביטולו מועיל, ושניהם אסורים.","במשנה מוסבר: \u0003שאחד נותן\u0004 (מבטל) \u0003רשות.\u0004 ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 הרי אפשר ללמוד את הדברים ממה שנאמר קודם. כי \u0003אי\u0004 \u0005[אם]\u0006 לענין \u0003נותן\u0004 רשות — כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 שאחד מבטל רשות, \u0003אי\u0004 \u0005[אם]\u0006 לענין \u0003נוטל — כבר תנינא\u0004 \u0005[שנינו],\u0006 ולשם מה החזרה?","ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[הסוף הוצרך לו]\u0006 שיש בו חידוש על הנאמר קודם, ואנו למדים כי \u0003שנים נותנין\u0004 (מבטלים) \u0003רשות\u0004 שיכולים הם לעשות זאת. ושוב תוהים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט\u0006 הוא\u0005]\u0006 שאף רבים נותנים רשות! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006"],["\u0003ליגזר דילמא אתי לבטולי להו\u0004 \u0005[שיגזור שמא יבואו לבטל להם]\u0006 שיאמרו שכשם ששניים נותנים רשותם לאחד, אף אחד נותן רשותו לשניים. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים.","נאמר במשנה ששנים \u0003אין נוטלין רשות.\u0004 ושואלים: \u0003למה לי\u0004 לומר זאת? הלא כבר נאמר הדבר קודם! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003אף על גב דאמרי ליה\u0004 \u0005[אף על פי שאמרו לו]\u0006 שאר בני החצר לאחד מאותם שלא עירבו: \u0003קני\u0004 \u0005[קנה]\u0006 וקבל רשותנו \u0003על מנת להקנות\u0004 רשות זאת לחברך האחר — אינו נעשה שליח, ואינו יכול להקנות לחבירו, משום שאף הוא עצמו אינו מקבל רשות במצב זה.","\u0003בעא מינה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: חמשה ששרויין בחצר אחת, ושכח אחד מהם ולא עירב, כשהוא מבטל רשותו\u0004 האם \u0003צריך לבטל לכל אחד ואחד\u0004 מן האחרים \u0003או לא? אמר ליה\u0004 \u0005[\u0006\u0003לו]: צריך לבטל לכל אחד ואחד.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006 אביי\u0005]\u0006 ממה ששנינו: \u0003אחד\u0004 משלושה הדרים בחצר \u0003שלא עירב — נותן\u0004 (מבטל) \u0003רשותו לאחד\u0004 מהאחרים \u0003שעירב. שנים שעירבו — נותנין\u0004 (מבטלים) \u0003רשותן לאחד שלא עירב, ו\u0004כן \u0003שנים שלא עירבו — נותנין רשותן לשנים שעירבו, או לאחד שלא עירב.\u0004","\u0003אבל לא אחד שעירב נותן רשותו לאחד שלא עירב. ואין שנים שעירבו נותנין רשותן לשנים שלא עירבו. ואין שנים שלא עירבו נותנין רשותן לשנים שלא עירבו. קתני מיהת רישא\u0004","\u0005[שנינו בכל אופן בתחילה]:\u0006 \u0003אחד שלא עירב — נותן רשותו לאחד שעירב. היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דליכא אחרינא בהדיה\u0004 \u0005[אם שאין אחר עמו],\u0006 שהיו רק שני אנשים בחצר, \u0003בהדי מאן\u0004 \u0005[עם מי]\u0006 \u0003עירב?\u0004 שהרי לא יתכן לומר שעירב לבדו כשהיו בחצר רק שני דיירים?","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן] — \u0003דאיכא אחרינא בהדיה\u0004 \u0005[שיש אחר עמו]\u0006 פרט לזה שלא עירב, ואתו עירב, ובכל זאת \u0003קתני\u0004 \u0005[שנינו]:\u0006 \u0003לאחד שעירב,\u0004 משמע שדי אם מבטל לאחד מן השכנים, ואינו צריך לבטל רשותו לכולם!","ושואלים: \u0003ורבה\u0004 כיצד הוא מבין זאת? ומשיבים שרבה מפרש \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה מיוחד \u0003דהוה\u0004 \u0005[שהיה]\u0006 בחצר עוד אדם אחד, ועירב עימו \u0003ומית\u0004 \u0005[ומת]\u0006 בינתיים, ולכן נשאר רק אחד שעירב, וזה שלא עירב מבטל לו רשותו.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 סבור אתה שמדובר \u0003דהוה\u0004 \u0005[שהיה]\u0006 אחד \u0003ומית\u0004 \u0005[ומת] —\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא, \u0003אבל אין אחד שעירב, נותן רשותו לאחד שלא עירב. ואי דהוה ומית\u0004 \u0005[ואם\u0006 מדובר כ\u0005שהיה\u0006 אחר עמו \u0005ומת],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יוכל לתת לו רשות, הרי רק אדם אחד שם!","\u0003אלא פשיטא דאיתיה\u0004 \u0005[פשוט,\u0006 מובן\u0005, שישנו]\u0006 האיש האחר שעימו עירב. \u0003ומדסיפא איתיה, רישא נמי איתיה\u0004 \u0005[ומ\u0006כיון \u0005ש\u0006ב\u0005סוף\u0006 הברייתא עוסקים במקרה \u0005שישנו, תחילת\u0006 הברייתא \u0005גם כן\u0006 עוסקים כ\u0005שישנו].\u0006","את ההוכחה הזו דוחים: \u0003מידי איריא\u0004 \u0005[האם הדברים שייכים]\u0006 זה לזה בהכרח, ושני הקטעים מדברים בדבר אחד? \u0003הא כדאיתא, והא כדאיתא\u0004 \u0005[\u0006דבר \u0005זה כמו שישנו, וזה כמו שישנו].\u0006 כלומר, כל פיסקה מדברת במצב דברים מיוחד, ואין הכרח להשוות את המצב בשני הקטעים.","ומוסיפים: \u0003תדע\u0004 שברייתא זו אינה עוסקת אך במצב אחד בלבד, \u0003דקתני סיפא דרישא\u0004 \u0005[ששנינו\u0006 ב\u0005סוף ההתחלה]:\u0006 \u0003ושנים שלא עירבו, נותנין רשותן לשנים שעירבו,\u0004 ונדייק: \u0003לשנים — אין\u0004 \u0005[כן],\u0006 שלא נאמר שיכולים לתת רשותם לאחד בלבד! \u0003לאחד — לא.\u0004","משמע שחייבים הם לבטל רשות לכל אחד מהם, \u0003ואביי אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לשנים\" — לאחד משנים,\u0004 והרי זה כמבטל לשניהם. \u0003אי הכי ליתני\u0004 \u0005[אם כך שישנה]\u0006 שמבטלים רשות \u0003לאחד שעירב או לאחד שלא עירב\u0004 ונבין כי מדובר שהיו שניים, וגם נלמד חידוש הלכה על ידי כך. ומסכמים: אכן דבר זה \u0003קשיא\u0004 \u0005[קשה]\u0006 לשיטת אביי, אבל אינו דוחה את דבריו מכל וכל.","\u0003נאמר בברייתא זו שאחד שלא עירב נותן רשותו לאחד שעירב. ל\u0004שיטת \u0003אביי\u0004 מדובר \u0003דאיתיה\u0004 \u0005[שישנו\u0006 אדם נוסף\u0005],\u0006 \u0003וקא משמע לן\u0004 \u0005[והשמיע לנו\u0006 בכך\u0005]:\u0006 ש\u0003אין צריך לבטל רשות לכל אחד ואחד. ולרבה\u0004 מדובר \u0003דהוה ומית\u0004 \u0005[שהיה\u0006 אחר \u0005ומת],\u0006 \u0003ו\u0004חידוש בכך כי \u0003לא גזור\u0004 \u0005[גזרו]\u0006 \u0003זימנין דאיתיה\u0004 \u0005[פעמים שהוא ישנו]\u0006 ונאסור לבטל אף לאחד שנשתייר משנים.","נאמר בברייתא: \u0003ושנים שעירבו נותנין רשותן לאחד שלא עירב.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שכן הוא, ומה החידוש בדבר? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כיון\u0004 ש\u0003לא עירב — ליקנסיה\u0004 \u0005[שיקנסוהו]\u0006 שיצטרך הוא לבטל רשות, אבל אין מבטלים רשות בשבילו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף מותר לבטל לו רשות.","שנינו שם: \u0003שנים שלא עירבו נותנין רשותן לשנים שעירבו. לרבה — תנא סיפא לגלויי רישא\u0004 \u0005[שנה\u0006 את \u0005הסוף\u0006 כדי \u0003לגלות\u0004 את משמעות \u0005ההתחלה]\u0006 כפי שהסברנו קודם, שמדובר בשהיה דייר נוסף ומת. \u0003לאביי — שנים שלא עירבו איצטריכא ליה\u0004 \u0005[נצרכה לו]\u0006 שיאמר הדבר, משום ש\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003לגזר דלמא אתי לבטולי להו\u0004 \u0005[לגזור שמא יבוא לבטל להם],\u0006 כדרך שמותר להם לבטל רשותם לו. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים גזירה זו.","שנינו עוד: \u0003או לאחד שלא עירב.\u0004 ושואלים: \u0003למה לי\u0004 תוספת זו? ומסבירים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 נאמרו \u0005—\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003מקצתן עירבו ומקצתן לא עירבו,\u0004 אפשר לבטל רשות ולהתיר. \u0003אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003כולן לא עירבו ליקנסינהו\u0004 \u0005[שיקנסו אותם]\u0006 שלא יוכלו לבטל, \u0003כדי שלא תשתכח תורת עירוב\u0004 מן הבאים אחריהם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים.","שנינו שם: \u0003אבל אין אחד שעירב נותן רשותו לאחד שלא עירב. לאביי, אף שהדבר פשוט — תנא סיפא לגלויי רישא\u0004 \u0005[שנה\u0006 את \u0005הסוף כדי לגלות\u0006 את פירוש \u0005ההתחלה]\u0006 כפי שהוכיח אביי מכאן שאפשר לבטל רשות לאחד משנים, ולאו דווקא לכל אחד. \u0003לרבה, איידי דתנא רישא תנא נמי סיפא\u0004 \u0005[מתוך ששנה\u0006 את \u0005ההתחלה, שנה גם כן\u0006 את \u0005הסוף]\u0006 באותו סגנון, אבל אין לדייק מלשון זו להלכה.","שנינו: \u0003ואין שנים שעירבו נותנין רשותן לשנים שלא עירבו.\u0004 ומקשים: \u0003הא תו\u0004 \u0005[\u0006דבר \u0005זה עוד]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דבטיל ליה חד מינייהו לחבריה\u0004 \u0005[שביטל לו אחד מהם\u0006 שלא עירב רשותו \u0005לחבירו]\u0006 \u0003מהו דתימא: לשתרי ליה\u0004 \u0005[שתאמר: שיהא מותר לו],\u0006 משום שעתה נשאר רק אחד שיש לו רשות בחצר ולא עירב, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כיון דבעידנא דבטיל\u0004 \u0005[שבזמן שביטל],\u0006 \u0003לא הוו ליה שריותא בהא\u0004 \u0005[היה לו היתר באותה]\u0006 \u0003חצר\u0004 — \u0003לא.\u0004 שהרי לא עירב בה, על כן אי אפשר לבטל לו רשות, שהרי הוא אינו יכול לזכות בה.","נאמר: \u0003ואין שנים שלא עירבו נותנין רשותן לשנים שלא עירבו.\u0004 ושואלים: \u0003הא תו\u0004 \u0005[\u0006דבר \u0005זה עוד]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאמרי\u0004 \u0005[שאמרו]:\u0006 \u0003קני\u0004 \u0005[קנה]\u0006 \u0003על מנת להקנות.\u0004 ויעשה אחד מהם שליח ויקנה רשות לחבריו, והשמיענו שבכל זאת אין תקנה זאת מועילה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן: יורש מהו שיבטל רשות.\u0004 אם שכח אדם ולא עירב, ומת ביום השבת, האם יכול יורשו לבטל?"],["\u0003היכא דאי בעי לערובי\u0004 \u0005[\u0006כרגיל \u0005במקום שאם\u0006 היה אדם \u0005רוצה לערב]\u0006 \u0003מאתמול מצי מערב\u0004 \u0005[יכול היה לערב] —\u0006 \u0003בטולי נמי מבטל\u0004 \u0005[לבטל גם כן\u0006 יכול \u0005לבטל],\u0006 \u0003אבל האי\u0004 \u0005[זה]\u0006 היורש, \u0003כיון דאי בעי לערובי\u0004 \u0005[שאם היה רוצה לערב]\u0006 \u0003מאתמול — לא מצי מערב\u0004 \u0005[היה יכול לערב],\u0006 שהרי הרשות לא היתה שלו, על כן גם היום \u0003לא מצי מבטל\u0004 \u0005[אינו יכול לבטל].\u0006","\u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003יורש כרעיה דאבוה\u0004 \u0005[רגלו של אביו]\u0006 \u0003הוא?\u0004 כלומר, היורש נחשב כחלק מאביו, וכיון שירשו נעשה כממלא מקום אביו לכל דבר, ממילא אף יכול הוא לבטל כמו האב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אני אומר\u0004 יורש \u0003מבטל, והני דבי\u0004 \u0005[ואותם\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל תנו\u0004 \u0005[שנו]:\u0006 \u0003אין מבטל. איתיביה\u0004 \u0005[הקשה לו]\u0006 רבא לרב נחמן ממה ששנינו בברייתא: \u0003זה הכלל, כל שמותר למקצת שבת — הותר לכל השבת, וכל שנאסר למקצת שבת — נאסר לכל השבת, חוץ ממבטל רשות\u0004 שיש לו היתר באמצע השבת.","ומפרטים: \u0003כל שהותר למקצת שבת, מותר לכל השבת — כגון עירב\u0004 בין שתי חצירות סמוכות \u0003דרך הפתח\u0004 שביניהן, \u0003ונסתם הפתח\u0004 בשבת. או \u0003עירב דרך חלון, ונסתם חלון.\u0004 מכיון שהותר לטלטל מחצר לחצר מתחילת השבת, הותר לכל השבת.","\u0003זה הכלל,\u0004 שבא להוסיף על פרט זה — \u0003לאתויי\u0004 \u0005[להביא]\u0006 אף מקרה של \u0003מבוי שניטלו קורותיו או לחייו\u0004 ביום השבת, שמותר להשתמש בו, כיון שהיה מותר עם כניסת השבת.","וכן בהמשך הדברים: \u0003כל שנאסר למקצת שבת, נאסר לכל השבת כולה — כגון\u0004 שהיו \u0003שני בתים בשני צידי רשות הרבים, והקיפום גוים מחיצה בשבת.\u0004 שאף שמחיצה זו נחשבת מחיצה לעניני רשויות, אין האחד יכול לבטל את רשותו לאחר כדי שיוכל להשתמש בה, כיון שלא היו יכולים להתירה מאתמול על ידי עירוב.","\u0003זה הכלל — לאתויי מאי\u0004 \u0005[להביא מה]?\u0006 מקרים נוספים כגון זה: \u0003לאתויי\u0004 \u0005[להביא]\u0006 מקרה ש\u0003מת גוי\u0004 שהיה דר בחצר \u0003בשבת,\u0004 ואותו גוי לא השכיר לישראל רשותו לצורך עירוב, והיתה החצר אסורה בטלטול. וכיון שנאסר לערב מבעוד יום, אף שהגוי האוסר מת בשבת, שוב אין היתר בשבת זו לאיסורה של החצר.","\u0003וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003חוץ ממבטל רשות,\u0004 שמבטל אף בתוך השבת, אף על פי שלא עירב מאתמול. ונדייק: \u0003איהו\u0004 \u0005[הוא\u0006 עצמו\u0005]\u0006 המבטל — \u0003אין\u0004 \u0005[כן]\u0006 יכול לבטל אף בשבת, ואילו \u0003יורש — לא.\u0004 היפך דברי רב נחמן!","והשיב רב נחמן: \u0003אימא\u0004 \u0005[אמור,\u0006 הבן\u0005]\u0006 \u0003חוץ מתורת ביטול רשות,\u0004 שהכוונה בברייתא אינה לאדם מסויים המבטל רשות, אלא לדין ביטול רשות בכללו, ואף היורש בכלל היכולים לבטל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממקור אחר, ששנינו: \u0003אחד מבני חצר שמת, והניח רשותו\u0004 להשתמש בביתו \u0003לאחד מן השוק,\u0004 כלומר, לאדם אחר שאינו מדרי החצר. אם מת \u0003מבעוד יום — אוסר,\u0004 שאנו אומרים שהאיש מן החוץ קבל חלקו ברשות עוד לפני כניסת השבת והיה חייב לערב עם האחרים, וכיון שלא עירב עם בני החצר שוב הרי זו דירה שאינה מעורבת ואוסרת את כל החצר. אם מת הנותן \u0003משחשיכה — אינו אוסר\u0004 שכיון שהותרה למקצת שבת — הותרה לכולה.","\u0003ו\u0004כן \u0003אחד מן השוק\u0004 שהיתה לו דירה בחצר זו \u0003שמת והניח רשותו לאחד מבני החצר\u0004 הדר שם. ואותו אדם, רגיל לערב עם חבריו. אם מת הנותן \u0003מבעוד יום — אינו אוסר,\u0004 שהרי בשעה שעירב דייר החצר את עירובו הרגיל, עירב גם בשביל דירתו החדשה. ואולם אם מת הנותן \u0003משחשיכה,\u0004 ולא עירב — \u0003אוסר,\u0004 שהרי היתה הדירה אסורה עם תחילת השבת, ואין עוד היתר לחצר בשבת זו.","ושאל רבא: לשיטת רב נחמן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אוסר? ניבטיל\u0004 \u0005[שיבטל]\u0006 רשותו לשאר בני החצר, שהרי לשיטת רב נחמן יורש יכול לבטל רשותו! והשיב רב נחמן: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"אוסר\" נמי דקתני\u0004 \u0005[גם כן ששנינו]\u0006 — אוסר \u0003עד שיבטל,\u0004 שאין תקנה על ידי עירוב, אבל על ידי ביטול יש לו אפשרות לתקן.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר, שכן שנינו: \u0003ישראל וגר שרויין\u0004 (דרים) \u0003במגורה\u0004 (במקום העשוי למגורים. ר\"ח) \u0003אחת,\u0004 שיש שם חדרים אחדים. \u0003ומת גר מבעוד יום,\u0004 ולא היו לו בנים לגר זה, וכיון שכך אין לו יורשים אחרים, וכל הקודם זוכה בנכסיו"],["\u0003אף על פי שהחזיק ישראל אחר בנכסיו\u0004 של הגר — \u0003אוסר\u0004 המחזיק על הדר. אם מת \u0003משחשיכה, אף על פי שלא החזיק ישראל אחר\u0004 בנכסיו — \u0003אינו אוסר,\u0004 שכבר הותר להם הטלטול בשבת זו.","ומקשים: \u0003הא גופא קשיא\u0004 \u0005[זה עצמו קשה],\u0006 \u0003אמרת:\u0004 אם מת \u0003מבעוד יום אף על פי שהחזיק,\u0004 ולכאורה מלשון זה אפשר להבין כי \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא החזיק\u0004 ודאי שאסור. והרי אינו כן, \u0003אדרבה\u0004 (להיפך הוא), \u0003כי לא החזיק\u0004 אדם אחר ודאי \u0003לא אסר,\u0004 שהרי אז אין בעלים לנכסי הגר, ואין מי שיאסור בחצר זו!","\u0003אמר רב פפא: אימא\u0004 \u0005[אמור,\u0006 תקן את הגרסה\u0005]\u0006 \u0003אף על פי שלא החזיק.\u0004 ומקשים: וכי כיצד אפשר לתקן כך, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אף על פי שהחזיק\" קתני\u0004 \u0005[שנינו]?\u0006","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין: \u0003אף על פי שלא החזיק מבעוד יום אלא משחשיכה, כיון דהוה ליה\u0004 \u0005[שהיתה לו\u0006 אפשרות\u0005]\u0006 \u0003להחזיק מבעוד יום — אוסר.\u0004 ואם \u0003משחשיכה, אף על פי שלא החזיק ישראל אחר — אינו אוסר.\u0004","ומקשים: \u0003\"אף על פי שלא החזיק ישראל אחר\"\u0004 ולכאורה מלשון זה אפשר להבין כי \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003החזיק,\u0004 שאם החזיק שאינו אוסר?! \u0003אדרבה\u0004 (להיפך הוא), \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003החזיק אסר\u0004 \u0005[אוסר]!\u0006","\u0003אמר רב פפא: אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 \u0003\"אף על פי שהחזיק\".\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אף על פי שלא החזיק\" קתני\u0004 \u0005[שנינו]!\u0006 ומפרשים \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אף על פי שהחזיק משחשיכה, כיון\u0004 ש\u0003לא הוה ליה\u0004 \u0005[היתה לו\u0006 אפשרות\u0005]\u0006 \u0003להחזיק מבעוד יום — אינו אוסר.\u0004","ולאחר תיקון הלשון נבוא לעניננו, \u0003קתני מיהת רישא\u0004 \u0005[שנינו בכל אופן\u0006 ב\u0005תחילת\u0006 הענין\u0005]\u0006 שהאיש שזכה בנכסי הגר \u0003אוסר, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אוסר? ניבטל\u0004 \u0005[שיבטל]\u0006 רשותו! ומשמע מכאן שאינו יכול לבטל.","השיב רב נחמן: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אוסר\" דקתני\u0004 \u0005[ששנינו],\u0006 הכוונה: אוסר \u0003עד שיבטל,\u0004 והביטול מועיל.","\u0003ר' יוחנן אמר: מתניתין\u0004 \u0005[המשניות]\u0006 שהקשו מהן, כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 — כשיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003אין ביטול רשות בשבת\u0004 כלל, אפילו לבעל הרכוש. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנה: \u0003מאימתי נותנין\u0004 (מבטלים) \u0003רשות? בית שמאי אומרים: מבעוד יום\u0004 דוקא, \u0003ובית הלל אומרים:\u0004 אפילו \u0003משתחשך.\u0004","לגופה של מחלוקת זו, \u0003אמר עולא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית הלל\u0004 שמבטלים אף משתחשך, \u0003נעשה כאומר \"כלך אצל יפות\".\u0004 שאם תרם אדם תרומות עבור חבירו שלא מדעתו, ומצאו החבר ואמר לו: מדוע תרמת מאלו? כלך אצל יפות. כלומר היה לך ללכת למצוא יפות מאלה לתרומה. אם היו באותו מקום יפות מהן, תרומתו תרומה. שגילה דעתו למפרע שמסכים להפרשת תרומה זו, והריהו כשלוחו לענין זה. וכך לעניננו, שאם מתכוון אדם להתיר לעצמו ולאחרים את הטלטול בחצר על ידי עירוב, אלא ששכח ולא עירב. וכיון שביטל רשות משחשיכה, נתגלתה דעתו שרצה שתהיה רשותו מעורבת עם של שכניו. ונמצא שאין כאן מעשה גמור, אלא גילוי דעת בלבד.","\u0003אמר אביי:\u0004 אין לסמוך על ביאור זה, שכן אם \u0003מת גוי בשבת מאי\u0004 \u0005[מה\u0006 קשר\u0005]\u0006 ל\u0003\"כלך אצל יפות\" איכא\u0004 \u0005[יש\u0006 כאן\u0005]?\u0006 שהרי לפני שמת הגוי אין תועלת בביטול, ובכל זאת אומרים אנו שלאחר שמת, מועיל הביטול, ואין לומר כאן שהתברר הדבר למפרע!","\u0003אלא\u0004 יש לדחות את דברי עולא ולומר כי \u0003הכא בהא קמיפלגי\u0004 \u0005[כאן בזה הם חולקים]\u0006 ש\u0003בית שמאי סברי\u0004 \u0005[סוברים]:\u0006 \u0003ביטול רשות מיקנא\u0004 \u0005[קניית]\u0006 \u0003רשות הוא,\u0004 שהשכנים קונים על ידי כך את רשות המבטל. \u0003ומיקנא רשותא\u0004 \u0005[ולקנות רשות]\u0006 \u0003בשבת\u0004 — \u0003אסור. ובית הלל סברי\u0004 \u0005[סוברים]:\u0006 \u0003אסתלוקי רשותא בעלמא\u0004 \u0005[סילוק רשות בלבד]\u0006 \u0003הוא, ואסתלוקי רשותא בשבת שפיר דמי\u0004 \u0005[וסילוק רשות בשבת מותר],\u0006 ואין לאוסרו משום גזירת מקח וממכר.","\u0003בעל הבית שהיה שותף לשכניו\u0004 שבמבוי, \u0003לזה ביין ולזה ביין — אינן צריכים לערב.\u0004 שאם יש להם שותפות אמיתית, הרי הם לענין זה כבית אחד, ואין צורך בשיתוף נוסף.","ואם היה שותף \u0003לזה ביין ולזה בשמן — צריכין לערב,\u0004 משום שאין לכולם שותפות באותו דבר, ואינם משותפים יחד. \u0003ר' שמעון אומר: אחד זה ואחד זה,\u0004 גם השותף עם חבריו בדברים שונים, \u0003אינן צריכין לערב.\u0004","\u0003אמר רב:\u0004 מה ששנינו שהשותף לשני שכניו ביין אינו צריך לערב, \u0003ו\u0004בלבד שיהיה היין של כולם \u0003בכלי אחד. אמר רבא: דיקא נמי\u0004 \u0005[מדויק\u0006 הדבר \u0005גם כן\u0006 מן המשנה\u0005]\u0006 \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 היה שותף \u0003לזה ביין ולזה בשמן — צריכין לערב. אי אמרת בשלמא רישא\u0004 \u0005[נניח אם אומר אתה\u0006 ש\u0005בראש\u0006 המשנה\u0005]\u0006 הכוונה שהיה \u0003בכלי אחד, וסיפא\u0004 \u0005[והסוף]\u0006 \u0003בשני כלים,\u0004 של יין לחוד ושמן לחוד — \u0003שפיר\u0004 \u0005[יפה].\u0006 \u0003אלא אי אמרת רישא\u0004 \u0005[אם אומר אתה\u0006 ש\u0005בראש\u0006 המשנה\u0005]\u0006 \u0003בשני כלים, וסיפא\u0004 \u0005[ו\u0006אף \u0005הסוף]\u0006 \u0003בשני כלים, מה לי יין ויין ומה לי שמן ושמן?!\u0004 הלא בשני המקרים המצב הוא זהה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין זו הוכחה. אפשר לומר כי מדובר בראש המשנה שהיה אף היין בכלים נפרדים, אבל ההבדל הוא כי \u0003יין ויין — ראוי לערב\u0004 זה בזה, וגם אם היו בשני כלים אפשר להחשיבם כאחד. \u0003יין ושמן — אין ראוי לערב.\u0004","\u0003ר' שמעון אומר\u0004 שאם היה שותף עם שכניו, אין כל הבדל, ו\u0003אחד זה\u0004 כשהיו שותפים ביין בלבד ו\u0003אחד זה\u0004 שהיו שותפים ביין ובשמן — \u0003אין צריכין לערב.\u0004 ושואלים: \u0003ואפילו לזה ביין ולזה בשמן\u0004 והלא אינם ראויים להתערב! \u0003אמר רבה: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בחצר\u0004 שהיתה \u0003בין שני מבואות, ור' שמעון לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003אמר ר' שמעון: למה הדבר דומה — לשלש חצירות הפתוחות זו לזו ופתוחות לרשות הרבים, עירבו שתים החיצונות עם האמצעית — היא מותרת עמהן, והן מותרות עמה, ושתים החיצונות אסורות זו עם זו.\u0004 משמע שיכולים בני חצר אחת לערב לשני צדדים, ולאו דוקא עם חצר אחת בלבד. אף כאן, החצר מעורבת עם האחד על ידי היין ועם השני על ידי השמן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם קתני\u0004 \u0005[שם שנינו]:\u0006 \u0003שתים החיצונות אסורות\u0004 זו עם זו, \u0003הכא קתני\u0004 \u0005[כאן שנינו]\u0006 ש\u0003\"אין צריכין לערב\",\u0004 משמע שכולם מותרים זה בזה!","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין צריכין לערב\"\u0004 הכוונה \u0003שכנים בהדי\u0004 \u0005[יחד עם]\u0006 \u0003בעל הבית\u0004 כלומר, דיירי החצר כל אחד ואחד עם בן החצר שבאמצע, \u0003אבל שכנים בהדי הדדי\u0004 \u0005[זה עם זה]\u0006 כלומר, הדרים במבואות אם רצונם להיות מותרים אלה באלה — \u0003צריכין לערב\u0004 ולהניח עירובם בחצר שבאמצע."],["\u0003ורב יוסף אמר:\u0004 מדובר כאן במבוי אחד, ו\u0003ר' שמעון ורבנן בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יוחנן בן נורי ורבנן קא מיפלגי\u0004 \u0005[חלוקים];\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 היה \u0003שמן\u0004 של תרומה \u0003צף על גבי יין, ונגע טבול יום\u0004 שמגעו גורם טומאה רק לדברים שהוא נוגע בהם, אבל הם אינם מוסיפים ומטמאים עוד אחרים. אם נגע \u0003בשמן — לא פסל אלא שמן בלבד.\u0004 אבל לא את היין, שהרי היין הוא בפני עצמו, וכאמור אין השמן הפסול מחמת טומאה מטמאו. \u0003ור' יוחנן בן נורי אומר: שניהן חיבורין זה לזה\u0004 ונחשבים כאחד, ולכן אף היין טמא.","ומסבירים: \u0003רבנן\u0004 \u0005[חכמים] —\u0006 \u0003כרבנן\u0004 \u0005[כ\u0006דברי \u0005חכמים]\u0006 סבורים הם, שיין ושמן אינם נחשבים חיבור זה לזה. \u0003ור' שמעון — כר' יוחנן בן נורי\u0004 הסבור ששניהם חיבור, ולכן אפשר גם לעשות עירוב משותף משניהם.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן תדאי אומר: אחד זה ואחד זה צריכין לערב.\u0004 ותוהים: \u0003ואפילו\u0004 היה שותף \u0003לזה ביין ולזה ביין?\u0004 מדוע לא תספיק שותפות זו לעשותם כמעורבים כבר?","\u0003אמר רבה:\u0004 אם נשתתפו על ידי ש\u0003זה בא בלגינו\u0004 המלא יין \u0003ושפך\u0004 יין לחבית, \u0003וזה בא בלגינו ושפך — כולי עלמא לא פליגי דהוי\u0004 \u0005[הכל אינם חולקים שנהיה\u0006 בכך\u0005]\u0006 \u0003עירוב,\u0004 שאף אם לא עשו לכוונת עירוב הרי כעירוב גמור.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003כגון שלקחו חבית של יין בשותפות, ר' אליעזר בן תדאי סבר: אין ברירה,\u0004 ואיננו אומרים שמתגלה למפרע לאחר השימוש למי שייך היה כל חלק מהיין. וכיון שכך, אין לאחד מהם חלק מסוים בשיתוף זה, ואין זה ראוי לעירוב. \u0003ורבנן סברי\u0004 \u0005[ו\u0006אילו \u0005חכמים סבורים]\u0006 כי \u0003יש ברירה,\u0004 ואפשר לסמוך על השותפות.","\u0003רב יוסף אמר\u0004 שיש להסביר אחרת את מחלוקתם, שכן \u0003ר' אליעזר בן תדאי ורבנן\u0004 בבעיה אחרת נחלקו, \u0003בסומכין על שיתוף במקום עירוב.\u0004 אם נשתתפו במבוי, אבל לא עשו עירובי חצירות, \u0003קמיפלגי\u0004 \u0005[נחלקו].\u0006","\u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' אלעזר בן תדאי\u0005]\u0006 \u0003סבר: אין סומכין,\u0004 שצריך דווקא עירוב חצירות ואין לסמוך על השיתוף במבוי. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 חכמים] \u0003סבר: סומכין,\u0004 ועל ידי השיתוף במבוי הותרו אף החצירות.","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה],\u0006 שזהו דבר המחלוקת, שכן \u0003אמר רב יהודה אמר רב: הלכה כר' מאיר\u0004 שאין סומכין על שיתוף במקום עירוב. \u0003ואמר רב ברונא אמר רב: הלכה כר' אליעזר בן תדאי. מאי טעמא\u0004 \u0005[מה טעם]\u0006 פסק כך, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דחד טעמא\u0004 \u0005[שטעם אחד]\u0006 \u0003הוא,\u0004 ויש עקרון אחד בשתי המחלוקות?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ואי חד טעמא, תרתי הלכתא\u0004 \u0005[ואם טעם אחד\u0006 הוא, \u0005שתי הלכות]\u0006 \u0003למה לי?!\u0004 ולהיפך, די לו שיפסוק הלכה כאחד מהם, וממילא נדע את ההלכה גם במקרה השני. ענה לו רב יוסף: בכל זאת יש טעם בשתי הלכות כי \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דלא עבדינן כתרי חומרי\u0004 \u0005[שאין אנו עושים כשתי חומרות]\u0006 שבאות ממקור אחד \u0003בעירובין.\u0004 ואילו היה פוסק כר' מאיר בלבד, היינו פוסקים כמותו רק בפרט אחד. ולכן פסק כשני חכמים, שכל אחד מהם מחמיר בנקודה אחרת, כר' אלעזר בן תדאי לענין שיתוף ביין, וכר' מאיר גם לענין שיתוף בפת.","כיון שהוזכרו דברי ר' מאיר, שואלים: \u0003מאי\u0004 \u0005[מהם]\u0006 דברי \u0003ר' מאיר ומאי רבנן\u0004 \u0005[ומהם\u0006 דברי \u0005חכמים]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מערבין בחצרות\u0004 הפתוחות אחת לשניה \u0003בפת, ואם רצו לערב ביין — אין מערבין.\u0004 ו\u0003משתתפין במבוי\u0004 כדי להתירו בטלטול אף שכבר עירבו חצרותיהם \u0003ביין, ואם רצו להשתתף בפת — משתתפין.\u0004","ומדוע \u0003מערבין בחצרות ומשתתפין\u0004 גם \u0003במבוי — כדי שלא לשכח תורת עירוב מן התינוקות. ש\u0004אם יסתפקו רק בשיתוף, \u0003יאמרו\u0004 התינוקות לאחר זמן: \u0003אבותינו לא עירבו.\u0004 ולכן לצורך חינוך אף מערבים, \u0003דברי ר' מאיר. וחכמים אומרים: או מערבין או משתתפין.\u0004","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בבעיה זו \u0003ר' נחומי ורבה, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אם עירבו חצרותיהם \u0003בפת, דכולי עלמא לא פליגי דבחדא סגי\u0004 \u0005[הכל אינם חלוקים שב\u0006דבר \u0005אחד מספיק],\u0006 ושוב אין צריך להשתתף במבוי. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה כשנשתתפו \u0003ביין,\u0004 שלר' מאיר צריך גם שיתוף, ולחכמים אין צריך."],["\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004: אם עירבו \u0003ביין, דכולי עלמא לא פליגי דבעינן תרתי\u0004 \u0005[הכל אינם חולקים שצריכים שניים]\u0006 גם שיתוף וגם עירוב. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה כאשר עשו עירוב \u0003בפת.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003וחכמים אומרים או מערבין או משתתפין. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה: \u0003או מערבין בחצר בפת, או משתתפין במבוי ביין\u0004 ומשמע שאף בשיתוף ביין נחלקו.","\u0003אמר רב גידל אמר רב:\u0004 לא כן, אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 וכך יש להבין: \u0003או מערבין בחצר בפת — ומותרין כאן וכאן. או משתתפין במבוי בפת — ומותרין כאן וכאן.\u0004","\u0003אמר רב יהודה אמר רב:\u0004 בענין זה \u0003הלכה כר' מאיר. ורב הונא אמר:\u0004 לא נפסקה הלכה ברורה כמותו אלא \u0003מנהג כר' מאיר,\u0004 ולשואל יש לומר שזו ההלכה. \u0003ור' יוחנן אמר:\u0004 אף אין זה מנהג שחכמים קבעוהו, אלא \u0003נהגו העם כר' מאיר,\u0004 ואין אומרים להם שנהגו שלא כדין.","\u0003חמשה חבורות ששבתו בטרקלין אחד,\u0004 שחילקוהו לחמישה חלקים על ידי מחיצות ולכל חלק פתח לחצר. \u0003בית שמאי אומרים: עירוב לכל חבורה וחבורה.\u0004 שכל חבורה צריכה ליתן חלקה בנפרד לצורך עירוב החצר, שכל אחת כבית נפרד. \u0003ובית הלל אומרים: עירוב אחד לכולן,\u0004 שאין בכח המחיצות לעשותם כבתים נפרדים.","\u0003ו\u0004אולם \u0003מודים\u0004 בית הלל \u0003בזמן שמקצתן שרויין בחדרים או בעליות\u0004 המובדלים ממש זה מזה, \u0003שהן צריכין עירוב לכל חבורה וחבורה,\u0004 ואין אומרים שהבית האחד מצרף אותם להיות כאחד.","\u0003אמר רב נחמן: מחלוקת\u0004 רק כאשר חילקו את הטרקלין זה מזה \u0003במסיפס\u0004 (מחיצה נמוכה העשויה מכפיסי עץ), \u0003אבל במחיצה\u0004 בריאה שגובהה \u0003עשרה\u0004 טפחים — \u0003דברי הכל עירוב לכל חבורה וחבורה,\u0004 שזאת חלוקה גמורה ולכל חבורה דירה לעצמה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן אחר, \u0003אמר רב נחמן: אף במסיפס\u0004 יש \u0003מחלוקת\u0004 אם דינו כמחיצה אם לא.","מסופר: כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בבעיה זו \u0003ר' חייא ור' שמעון ברבי\u0004 (בנו של ר' יהודה הנשיא); \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מחלוקת\u0004 זו \u0003במחיצות המגיעות לתקרה, אבל מחיצות שאין מגיעות לתקרה\u0004 שוודאי אינן עושות חלוקה גמורה — \u0003דברי הכל עירוב אחד לכולן. וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: מחלוקת במחיצות שאין מגיעות לתקרה, אבל מחיצות המגיעות לתקרה — דברי הכל צריכין עירוב לכל חבורה וחבורה,\u0004 שהם כבתים נפרדים."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 \u0003אמר ר' יהודה הסבר\u0004 (החריף, בעל הסברה): \u0003לא נחלקו בית שמאי ובית הלל על מחיצות המגיעות לתקרה — שצריכין עירוב לכל חבורה וחבורה. על מה נחלקו — על מחיצות שאין מגיעות לתקרה, שבית שמאי אומרים: עירוב לכל חבורה וחבורה\u0004 לחוד, \u0003ובית הלל אומרים: עירוב אחד לכולן.\u0004","\u0003למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003במחיצות המגיעות לתקרה מחלוקת\u0004 — הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]!\u0006 \u0003ולמאן דאמר\u0004 \u0005[ולמי שאומר]\u0006 \u0003במחיצות שאין מגיעות לתקרה מחלוקת\u0004 — הרי זו \u0003סייעתא\u0004 \u0005[סיוע],\u0006 וכן \u0003להך לישנא\u0004 \u0005[ללשון זו]\u0006 ש\u0003אמר רב נחמן: מחלוקת במסיפס\u0004 — הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 אלא יש לברר:","\u0003להך לישנא\u0004 \u0005[ללשון זו]\u0006 ש\u0003אמר רב נחמן: אף במסיפס מחלוקת, לימא תהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 מדברי ר' יהודה הסבר המנוגדים לה?","\u0003אמר לך רב נחמן: פליגי\u0004 \u0005[נחלקו]\u0006 \u0003במחיצה, והוא הדין במסיפס,\u0004 שאף בו נחלקו. \u0003והאי דקא מיפלגי\u0004 \u0005[וזה שנחלקו\u0006 במפורש\u0005]\u0006 \u0003במחיצה\u0004 ולא במסיפס — \u0003להודיעך כחן\u0004 של \u0003בית הלל.\u0004 שאפילו שהיו חלוקים במחיצה של ממש, עומדים בית הלל על דעתם שכולם נחשבים כרשות אחת.","ומקשים: אם אמנם בשני הדברים נחלקו, \u0003וליפלגי\u0004 \u0005[ושיחלקו\u0006 במשנה\u0005]\u0006 \u0003במסיפס\u0004 ועל ידי כך \u0003להודיעך כחן\u0004 של \u0003בית שמאי\u0004 שמחמירים אפילו במסיפס! ומשיבים: \u0003כח דהתירא\u0004 \u0005[ההיתר]\u0006 \u0003עדיף\u0004 לתנא להשמיענו. שאם יש בידו לסגנן את המחלוקת באופן שיתגלה יותר כוחם של המתירים הרי הוא מביאה בסגנון זה.","\u0003אמר רב נחמן אמר רב: הלכה כר' יהודה הסבר\u0004 שבמחיצות המגיעות לתקרה לדעת כולם צריך עירוב לכל אחת ואחת ולא נחלקו אלא במחיצות שאינן מגיעות לתקרה.","\u0003אמר רב נחמן בר יצחק: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כהסבר זה, \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003ומודים בזמן שמקצתן שרויין בחדרים ובעליות, שצריכין עירוב לכל חבורה וחבורה. מאי\u0004 \u0005[מה\u0006 משמעם\u0005]\u0006 של \u0003חדרים, ומאי\u0004 \u0005[ומה\u0006 משמעם\u0005]\u0006 של \u0003עליות? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003חדרים — חדרים ממש,\u0004 שלא היו מעולם מחוברים, \u0003ועליות — עליות ממש, פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005],\u0006 שהרי כן הוא הדין ברבים הדרים בחצר אחת. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה שהיו \u0003כעין חדרים, כעין עליות. ומאי ניהו\u0004 \u0005[ומה\u0006 הם \u0005אלה]\u0006 — \u0003מחיצות המגיעות לתקרה,\u0004 שאף על פי שאינם חדרים ממש — כעין חדרים הם. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[נלמד מכאן]\u0006 שכן הוא.","\u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003במה דברים אמורים\u0004 שנחלקו בית שמאי והצריכו עירוב, הרי זה \u0003כשמוליכין את עירובן למקום אחר\u0004 בחצר, ולא בטרקלין עצמו. \u0003אבל אם היה עירובן בא אצלן,\u0004 שבני החצר רוצים לערב באותו בית — \u0003דברי הכל עירוב אחד לכולן.\u0004 שמאחר שקובעים את מקום עירובם בבית זה, הרי נעשו כל בני הבית כיחידה אחת.","\u0003ומעירים: כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003חמשה\u0004 שגרים בחצר אחת ו\u0003גבו את עירובן, כשמוליכין את עירובן למקום אחר — עירוב אחד לכולן. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי],\u0006 \u0003כבית הלל\u0004 כפי שהסברנו כאן.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 נוסחה אחרת: \u0003במה דברים אמורים\u0004 שנחלקו בית שמאי ובית הלל, הרי זה \u0003כשהיה עירוב בא אצלן,\u0004 שלבית שמאי צריך עירוב לכל אחד, ולבית הלל די בעירוב אחד לכולם. \u0003אבל אם היו מוליכין את עירובן למקום אחר — דברי הכל צריכין עירוב לכל חבורה וחבורה.\u0004","ואם כן \u0003כמאן אזלא הא דתניא\u0004 \u0005[כמי הולכת זו ששנינו]:\u0006 \u0003חמשה שגבו את עירובן, כשמוליכין את עירובן למקום אחר עירוב אחד לכולן, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 ש\u0003לא כ\u0004שיטת \u0003חד\u0004 \u0005[אחד]\u0006 מהם, שהרי לפי לשון זו אין זו אף שיטת בית הלל.","\u0003האחין שהיו אוכלין על שלחן אביהם וישנים בבתיהם\u0004 המיוחדים להם באותה חצר — \u0003צריכין עירוב לכל אחד ואחד. לפיכך, אם שכח אחד מהם ולא עירב — מבטל את רשותו\u0004 כדי להתיר לכול לטלטל בחצר זו.","\u0003אימתי\u0004 אמרו דין זה, \u0003בזמן שמוליכין עירובן במקום אחר\u0004 בחצר ושלא בבתיהם. \u0003אבל אם היה עירוב בא אצלן\u0004 להיות מונח בבית אביהם, \u0003או שאין עמהם דיורין בחצר\u0004 אלא האחים ואביהם בלבד — \u0003אינן צריכין לערב,\u0004 שהם נחשבים כיחיד הדר בחצר.","ממה שנאמר במשנה שאם היו ישנים בבתיהם צריכים עירוב לכל אחד ואחד, לכאורה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מקום לינה גורם,\u0004 ולפיו קובעים היכן עיקר דירתו של אדם. את המסקנה הזו דוחים: \u0003אמר רב יהודה אמר רב. במקבלי פרס שנו,\u0004 שלא דובר במשנה באחים שהיו ממש אוכלים על שולחן אביהם בביתו, אלא היו אוכלי שולחנו במובן זה שהוא מספק להם את מזונם, ולמעשה הם אוכלין בבתיהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מי שיש לו בית שער\u0004 או \u0003אכסדרה\u0004 כעין מרפסת פתוחה, או \u0003מרפסת בחצר חבירו — הרי זה אין אוסר עליו,\u0004 משום שאין אלה קרויים דירה. אבל אם היה לו \u0003את בית התבן ואת בית הבקר ובית העצים ובית האוצרות\u0004 בחצר חבירו — \u0003הרי זה אוסר עליו\u0004 עד שיערב. \u0003ר' יהודה אומר: אינו אוסר אלא מקום דירה בלבד,\u0004 ובית שאינו מיועד למגורים אינו נחשב לאסור על בני החצר.","\u0003אמר ר' יהודה: מעשה בבן נפחא שהיו לו חמש חצירות באושא\u0004 והוא עצמו דר רק באחת מהן, \u0003ובא מעשה לפני חכמים\u0004 לשאול האם צריך לערב בכל החצירות, \u0003ואמרו: אינו אוסר אלא בית דירה בלבד.\u0004","ותוהים: \u0003בית דירה סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?\u0006 והלא בית דירה יש לו בכל חמש החצירות! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003מקום דירה\u0004 כלומר במקום שדר בו — שם הוא אוסר, אבל לא במקום אחר.","נתעוררה השאלה \u0003מאי\u0004 \u0005[מה\u0006 נקרא\u0005]\u0006 \u0003מקום דירה? רב אמר:\u0004"],["\u0003מקום\u0004 שהוא אוכל את \u0003פיתא\u0004 \u0005[פת],\u0006 \u0003ושמואל אמר: מקום לינה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב: \u0003הרועים, והקייצין\u0004 (שומרי התאנים השטוחות בשדה) \u0003והבורגנין\u0004 (היושבים בסוכות משמר קטנות) \u0003ושומרי פירות, בזמן שדרכן ללין בעיר\u0004 ששם גם מקום אכילתם — \u0003הרי הן כאנשי העיר,\u0004 ומודדים תחומם מהעיר, אף על פי שנכנסה השבת בהיותם בשדה. \u0003בזמן שדרכן ללין בשדה, אף על פי שאוכלים בעיר — יש להם אלפים לכל רוח\u0004 ממקום לינתם בלבד, וקשה לשיטת רב!","ומתרצים: \u0003התם\u0004 \u0005[שם]\u0006 לענין המצויים בשדה \u0003אנן סהדי דאי ממטו להו ריפתא התם, טפי ניחא להו\u0004 \u0005[אנו עדים,\u0006 הכל מבינים, \u0005שאם היו מביאים להם אוכל לשם\u0006 למקום לינתם, \u0005היה נוח להם יותר]\u0006 אך עקרונית הכל תלוי במקום בו חפץ האדם לאכול ולא במקום לינה.","\u0003אמר רב יוסף: לא שמיע לי הא שמעתא\u0004 \u0005[שמעתי הלכה זו]\u0006 של רב, שחלה רב יוסף ושכח תלמודו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הזכירו \u0003אביי\u0004 תלמידו: \u0003את\u0004 \u0005[אתה]\u0006 \u0003אמרת\u0004 אותה \u0003ניהלן\u0004 \u0005[לנו],\u0006 \u0003ואהא\u0004 \u0005[ועל\u0006 דבר \u0005זה]\u0006 \u0003אמרת\u0004 אותה \u0003ניהלן\u0004 \u0005[לנו]:\u0006 \u0003האחין שהיו אוכלין על שלחן אביהן, וישנים בבתיהן — צריכין עירוב לכל אחד ואחד. ואמרינן\u0004 \u0005[ואמרנו]\u0006 \u0003לך: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003מקום לינה גורם,\u0004 ועל פיו קובעים מקום שביתתו של אדם. \u0003ואמרת לן עלה\u0004 \u0005[לנו עליה,\u0006 על כך\u0005]\u0006 \u0003אמר רב יהודה אמר רב: במקבלי פרס שנו\u0004 שאינם אוכלים אצל אביהם אלא בביתם ורק מתפרנסים ממה שהוא נותן להם, ובמובן זה קרויים הם אוכלי שולחנו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003מי שיש לו חמש נשים מקבלות פרס מבעליהן,\u0004 וכל אחת גרה בבית מיוחד בחצר. \u0003ו\u0004כן \u0003חמשה עבדים מקבלין פרס מרביהן,\u0004 שיש לכולם מקום דיור מיוחד בחצר. \u0003ר' יהודה בן בתירא מתיר בנשים,\u0004 שאינן צריכות לערב לחוד ונחשבות כדרות עם בעליהן. \u0003ואוסר בעבדים,\u0004 שאינם קשורים באדוניהם, וכיון שהם מתגוררים בבתים נפרדים, כל אחד מהם הריהו דייר לעצמו.","\u0003ר' יהודה בן בבא מתיר בעבדים,\u0004 שלדעתו העבד נמשך בעל כרחו אחר רבו. \u0003ואוסר בנשים,\u0004 שכל אשה חשובה היא לעצמה ואינה תלויה עד כדי כך בבעלה.","\u0003אמר רב: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה בן בבא,\u0004 שכן נאמר \u0003\"ודניאל בתרע מלכא\"\u0004 \u0005[בשער המלך]\u0006 (דניאל ב, מט) (ושם הכוונה לא למקומו ממש, אלא לתפקידו) לומר לנו: בכל מקום שנמצא בו דניאל, הריהו כבשער המלך, משמע שהעבד נמשך אחרי אדוניו.","ומעתה מבררים צדדים שונים בנושא זה, ותחילה מסכמים את הידוע כבר: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 \u0003בן אצל אביו, כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 במשנה. \u0003אשה אצל בעלה ועבד אצל רבו, פלוגתא\u0004 \u0005[מחלוקת]\u0006 בין \u0003ר' יהודה בן בתירא ור' יהודה בן בבא.\u0004 אולם \u0003תלמיד אצל רבו\u0004 המקבל מרבו את הספקת צרכיו ודר עמו בחצר, \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]\u0006 לגבי קביעות מקומו לענין עירוב?","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, \u0003דרב\u0004 כאשר היה \u0003בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא אמר: אין אנו צריכין לערב, שהרי אנו סומכין על שלחנו של ר' חייא. ו\u0004כן \u0003ר' חייא\u0004 עצמו כשהיה \u0003בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי אמר: אין אנו צריכין לערב, שהרי אנו סומכין על שלחנו של רבי.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: חמשה שגבו את עירובן, כשמוליכין את עירובן למקום אחר\u0004 שרוצים לערב חצר זו עם חצר אחרת, האם \u0003עירוב אחד לכולן, או צריכין\u0004 להביא \u0003עירוב לכל אחד ואחד? אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003עירוב אחד לכולן.\u0004","אמר לו אביי: \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003אחין\u0004 שבמשנתנו, \u0003דכי גבו דמו\u0004 \u0005[שכמי שהיו גובים\u0006 את העירוב \u0005נחשבים],\u0006 \u0003וקתני\u0004 \u0005[ו\u0006בכל זאת \u0005שנינו]:\u0006 \u0003צריכין עירוב לכל אחד ואחד!\u0004 ענה לו רבה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דאיכא דיורין בהדייהו\u0004 \u0005[שיש דיירים עימם],\u0006 שלא היו האב והבנים לבדם בחצר זו, ודרו בה גם זרים. \u0003דמגו דהני אסרי, הני נמי אסרי\u0004 \u0005[שמכיון שאלה\u0006 הדיירים \u0005אוסרים\u0006 על האחים, \u0005אלה\u0006 האחים עצמם \u0005גם כן אוסרים\u0006 האחד על השני\u0005].\u0006","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003אימתי — בזמן שמוליכין את עירובן במקום אחר, אבל אם היה עירובן בא אצלם, או שאין דיורין עמהן בחצר — אין צריכין לערב, שמע מינה [למד מכאן]\u0004 שבתחילה מדובר רק כשהיו דיורים עימם.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב חייא בר אבין מרב ששת: בני בי\u0004 \u0005[תלמידי בית\u0006 מדרשו\u0005]\u0006 של \u0003רב, דאכלי נהמא בבאגא, ואתו ובייתי בבי\u0004 \u0005[האוכלים לחם ב\u0006ביתם ש\u0005בבקעה, ובאים ולנים בבית]\u0006 \u0003רב, כי משחינן להו תחומא\u0004 \u0005[כאשר מודדים אנו להם את תחום\u0006 השבת\u0005],\u0006 \u0003מבי\u0004 \u0005[מבית]\u0006 \u0003רב\u0004 מקום לינתם \u0003משחינן להו\u0004 \u0005[מודדים להם]\u0006 \u0003או מבאגא משחינן להו\u0004 \u0005[מהבקעה\u0006 מקום אכילתם \u0005מודדים להם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משחינן מבי\u0004 \u0005[מודדים להם מבית]\u0006 \u0003רב.\u0004","הקשה לו: \u0003והרי\u0004 ה\u0003נותן את עירובו\u0004 שהוא מקום סעודה \u0003בתוך אלפים אמה,\u0004 ואחר כך \u0003אתי וביית בביתיה, דמשחינן ליה תחומא מעירוביה\u0004 \u0005[והולך ולן בביתו, שמודדים לו תחום מעירובו],\u0006 משמע שמקום האכילה הוא הקובע ולא מקום הלינה!","ומשיבים: \u0003ב\u0004מקרה \u0003ההוא, אנן סהדי\u0004 \u0005[אנו עדים].\u0006 \u0003ובהדא, אנן סהדי\u0004 \u0005[וב\u0006מקרה \u0005זה, אנו עדים]\u0006 שאנו יכולים לקבוע מהו עיקר מקום שביתתו של כל אחד מאלה. \u0003ב\u0004מקרה \u0003ההוא\u0004 של המניח עירובו \u0003אנן סהדי\u0004 \u0005[אנו עדים]\u0006 — \u0003דאי מיתדר ליה התם ניחא ליה\u0004 \u0005[שאילו היה יכול לדור שם\u0006 במקום עירובו \u0005היה נוח לו]\u0006 שאם היה יכול ללון שם, היה עושה זאת. שהרי רצונו ללכת למחרת מאותו מקום והלאה. \u0003ובהדא אנן סהדי\u0004 \u0005[ובזה,\u0006 בעניננו \u0005אנו עדים,\u0006 ברור לנו\u0005]\u0006 \u0003דאי מייתו להו ריפתא לבי רב, ניחא להו טפי\u0004 \u0005[שאם היו מביאים אוכל לבית הרב\u0006 \u0003ויוכלו לאכול שם,\u0004 \u0005היה נוח להם יותר],\u0006 ולכן זהו עיקר מקומם.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא מרב חסדא: אב ובנו, הרב ותלמידו,\u0004 האם \u0003כרבים דמו\u0004 \u0005[נחשבים]\u0006 \u0003או כיחידים דמו\u0004 \u0005[נחשבים]?\u0006 ופרטי השאלה למעשה: אם היו גרים בשתי חצירות, האחת פנימית לחבירתה, האם נחשבים הם כרבים ו\u0003צריכין עירוב\u0004 כדי שלא תאסור רגלם את הטלטול בחיצונה, \u0003או\u0004 שמא נחשבים כיחידים שאין רגלם אוסרת את החיצונה ולכך \u0003אין צריכין עירוב? מבוי שלהן ניתר בלחי וקורה\u0004 כמבוי שיש בו דיורים אחדים, \u0003או אין ניתר בלחי וקורה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003תניתוה\u0004 \u0005[שניתם\u0006 כבר כעין זה\u0005],\u0006 \u0003\"אב ובנו, הרב ותלמידו, בזמן שאין עמהן דיורין — הרי הן כיחידים, ואין צריכין לערב, ומבוי שלהן ניתר בלחי וקורה\u0004 בלא שיתוף\u0003\"\u0004.","היו \u0003חמש חצירות פתוחות זו לזו ופתוחות\u0004 כולן גם \u0003למבוי,\u0004 אם \u0003עירבו\u0004 בני החצירות \u0003בחצירות ולא נשתתפו\u0004 אלה עם אלה \u0003במבוי — מותרין\u0004 לטלטל \u0003בחצירות\u0004 ואולם \u0003אסורין במבוי,\u0004 שהעירוב שעשו אינו יכול לבוא גם במקום שיתוף במבוי,"],["\u0003ואם נשתתפו במבוי — מותרין לטלטל כאן וכאן,\u0004 גם במבוי וגם בחצר.","אם \u0003עירבו בחצירות\u0004 וגם \u0003נשתתפו במבוי, ושכח אחד מבני חצר ולא עירב חצירו אבל נשתתף במבוי — מותרין כאן וכאן\u0004 שהשיתוף מועיל כעירוב.","אולם אם שכח אחד \u0003מבני מבוי ולא נשתתף — מותרין בחצירות ואסורין במבוי,\u0004 כללו של דבר \u0003שהמבוי לחצירות כחצר לבתים.\u0004","שואלים: \u0003מני\u0004 \u0005[\u0006של \u0005מי היא]\u0006 משנתנו זו? ומשיבים: כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עירוב ובעינן\u0004 \u0005[וצריכים אנו]\u0006 \u0003גם שיתוף,\u0004 ולא די באחד מהם.","ומקשים: אם כן \u0003אימא מציעתא\u0004 \u0005[אמור\u0006 את \u0005אמצעה\u0006 של משנה זו\u0005]\u0006 \u0003\"ואם נשתתפו במבוי — מותרין כאן וכאן\", אתאן לרבנן דאמרי בחדא סגיא\u0004 \u0005[הגענו\u0006 איפה \u0005לשיטת חכמים האומרים שבאחד מספיק]\u0006 ואין צורך גם בעירוב וגם בשיתוף!","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 וכך יש להבין \u0003ואם נשתתפו נמי קאמר\u0004 \u0005[גם כן אמר]\u0006 כלומר שאם לא רק עירבו אלא גם השתתפו מותרים בשניהם.","ומקשים עוד \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003עירבו בחצירות ונשתתפו במבוי, ושכח אחד מבני חצר ולא עירב — מותרים כאן וכאן. היכי דמי\u0004 \u0005[כיצד הוא הדבר בדיוק]?\u0006 \u0003אי דלא בטיל\u0004 \u0005[אם שלא ביטל]\u0006 זה ששכח את רשותו לאחרים \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותרים\u0004 הם? \u0003אלא פשיטא דבטיל\u0004 \u0005[פשוט\u0006 לומר \u0005שביטל]\u0006 ואם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]\u0006 \u0003שכח אחד מבני מבוי ולא נשתתפו — מותרין בחצירות ואסורין במבוי ואי דבטיל\u0004 \u0005[ואם ביטל\u0006 רשותו\u0005]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אסורין במבוי?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003קסבר ר' מאיר אין ביטול רשות\u0004 מועיל \u0003במבוי. והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שהרי ביטל לכם רשותו, דברי ר' מאיר\u0004 (לעיל עירובין סח,ב), הרי שר' מאיר מסכים לענין ביטול רשות במבוי.","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שמדובר במקרה ש\u0003לא בטיל\u0004 \u0005[ביטל].\u0006 \u0003ומדסיפא\u0004 \u0005[ומ\u0006כיון \u0005ש\u0006ב\u0005סופה\u0006 של המשנה\u0005]\u0006 מדובר ש\u0003לא בטיל\u0004 \u0005[ביטל] —\u0006 \u0003רישא נמי דלא בטיל\u0004 \u0005[\u0006ב\u0005תחילתה גם כן]\u0006 מדובר שלא בטיל \u0005[ביטל]..\u0006 ויש איפוא להבין שאם השתתפו, מועיל השיתוף לשם עירוב גם כששכח אחד ולא עירב אפילו בלא ביטול רשותו, והוא כדברי חכמים, ונמצאת משנה זו תמוהה היא: \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 כשיטת \u0003ר' מאיר, מציעתא רבנן\u0004 \u0005[אמצעה\u0006 כשיטת \u0005חכמים]!\u0006","ומתרצים: לא כן, \u0003כולה ר' מאיר היא, וטעמא מאי\u0004 \u0005[מה הטעם]\u0006 \u0003אמר ר' מאיר בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עירוב ובעינן\u0004 \u0005[וצריכים אנו]\u0006 \u0003שיתוף\u0004 כדי \u0003שלא לשכח תורת עירוב מן התינוקות\u0004 שאם רק ישתתפו במבואות ישכחו שיש עירוב חצירות, ואולם \u0003הכא\u0004 \u0005[וכאן]\u0006 במקרה שלנו שרק אחד שכח \u0003כיון דרובה\u0004 \u0005[שרובם]\u0006 \u0003עירבו\u0004 בחצירות \u0003לא משתכחא\u0004 \u0005[משתכחת]\u0006 תורת עירוב, ובדיעבד התירו אף במקרה זה.","\u0003אמר רב יהודה: רב לא תני\u0004 \u0005[שנה]\u0006 במשנה זו שהיו חצירות \u0003פתוחות זו לזו,\u0004 אלא כל חצר היתה פתוחה רק למבוי ועירבה כל חצר לעצמה. \u0003וכן אמר רב כהנא: רב לא תני\u0004 \u0005[שנה]\u0006 \u0003\"פתוחות זו לזו\". איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 \u0003רב כהנא גופיה לא תני\u0004 \u0005[עצמו לא שנה\u0006 במשנתנו\u0005]\u0006 \u0003\"פתוחות זו לזו\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מאי טעמא דלא תני\u0004 \u0005[מה טעמו שלא שנה]\u0006 \u0003פתוחות זו לזו.\u0004 אמר לו רב יוסף: ש\u0003סבר כל שיתוף שאין מכניסו ומוציאו דרך פתחים במבוי\u0004 אל המבוי ומשם מכניסים אותו לאחת החצירות \u0003לאו שמיה\u0004 \u0005[אין שמו]\u0006 \u0003שיתוף\u0004 שאם יעבירו את השיתוף דרך החצירות נראה הדבר כעירוב בלבד, ואינו מועיל. ואף כאן אם החצירות פתוחות זו לזו ויעביר דרכם את השיתוף אין זה שיתוף כראוי.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003בעל הבית שהיה שותף לשכניו, לזה ביין ולזה ביין, אין צריכין לערב\u0004 משמע שאין הכרח לקחת ממש את המזון של השיתוף ולהוליכו ממקום למקום ודי שיהא אדם שותף עם שכניו למבוי בחבית אחת שנכנסה לחצירו בלבד ולא חשוב אף אם לא הועבר השיתוף עצמו במבוי. את הקושיה הזו דוחים שממקור זה אין ראיה ואפשר לומר: \u0003התם, דאפקיה ועייליה\u0004 \u0005[שם, שהוציאו\u0006 את היין למבוי ואחר כך \u0005הכניסו\u0006 לחצר שנשמר בה\u0005].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד: והרי שנינו במשנה \u0003כיצד משתתפין במבוי,\u0004 שדי רק בזיכוי השיתוף על ידי אחד בלבד לאחרים ואין צריך להעבירה בכל פתחי המבוי! ודוחים: \u0003התם נמי דאפקיה ועייליה\u0004 \u0005[שם גם כן\u0006 מדובר \u0005שהוציאו והכניסו]\u0006 את מזון השיתוף.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה בר חנן אלא מעתה הקנה לו פת בסלו הכי נמי דלא הוי\u0004 \u0005[כך גם כן לא יהא\u0006 נחשב\u0005]\u0006 \u0003שיתוף?! וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך הוא גם כן]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב\u0004 עצמו: \u0003בני חבורה שהיו מסובין\u0004 ואוכלין יחד בערב שבת \u0003וקדש עליהן היום\u0004 ונכנסה השבת — \u0003הפת שעל\u0004 ה\u0003שלחן סומכים עליה משום עירוב\u0004 חצירות \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003משום שיתוף\u0004 מבואות.","\u0003ואמר רבה: לא פליגי\u0004 \u0005[נחלקו\u0006 שתי הלשונות\u0005]\u0006 אם עירוב אם שיתוף, אלא \u0003כאן\u0004 שסומכין משום עירוב מדובר כשהם \u0003מסובין בבית\u0004 ובמזון המונח בבית יכולים להשתמש כעירוב לחצר, \u0003כאן במסובין בחצר,\u0004 יכולים לסמוך על הפת שבחצר לשם שיתוף במבוי. ומכל מקום לענינינו למדנו כי אף לדעת רב אין צורך דוקא להוציא את השיתוף למבוי ולהחזירו לחצר.","\u0003אלא\u0004 יש לחזור מן ההסבר הקודם ולומר \u0003טעמא\u0004 \u0005[הטעם]\u0006 שלא שנה \u0003רב\u0004 \"פתוחות זו לזו\" \u0003דקא סבר: אין מבוי ניתר בלחי וקורה עד שיהו בתים וחצירות פתוחים לתוכו\u0004 בלבד, ואם היו החצירות פתוחות זו לזו הרי הן כחצר אחת ואין למבוי זה היתר על ידי לחי וקורה וממילא אין בו שיתוף.","\u0003גופא כיון שהוזכרו דברי רב דנים עתה בגופם של דברים; אמר רב: אין מבוי ניתר בלחי וקורה\u0004 כדרך שמתירים את המבואות"]]};
